// Create new room
app.post('/api/admin/rooms', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  const { room_number, room_type } = await c.req.json()

  try {
    const qr_code_data = `qr-${room_number}-${crypto.randomUUID()}`

    const room = await DB.prepare(`
      INSERT INTO rooms (property_id, room_number, room_type, qr_code_data, status)
      VALUES (?, ?, ?, ?, 'vacant')
      RETURNING room_id, qr_code_data
    `).bind(property_id, room_number, room_type || 'standard', qr_code_data).first()

    return c.json({
      success: true,
      room_id: room.room_id,
      qr_code_data: room.qr_code_data,
      qr_code_url: `/api/qr/${room.qr_code_data}`
    })
  } catch (error) {
    console.error('Create room error:', error)
    return c.json({ error: 'Internal server error' }, 500)
  }
})

// Regenerate room QR code
app.post('/api/admin/rooms/:room_id/regenerate-qr', async (c) => {
  const { DB } = c.env
  const { room_id } = c.req.param()

  try {
    const room = await DB.prepare(`
      SELECT room_number FROM rooms WHERE room_id = ?
    `).bind(room_id).first()

    if (!room) {
      return c.json({ error: 'Room not found' }, 404)
    }

    const new_qr_code_data = `qr-${room.room_number}-${crypto.randomUUID()}`

    await DB.prepare(`
      UPDATE rooms
      SET qr_code_data = ?, updated_at = datetime('now')
      WHERE room_id = ?
    `).bind(new_qr_code_data, room_id).run()

    return c.json({
      success: true,
      qr_code_data: new_qr_code_data,
      qr_code_url: `/api/qr/${new_qr_code_data}`
    })
  } catch (error) {
    console.error('Regenerate QR error:', error)
    return c.json({ error: 'Internal server error' }, 500)
  }
})

// Generate unique room QR codes for all rooms (for guest auto-detection)
app.post('/api/admin/rooms/generate-guest-qr-codes', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'

  try {
    // Get all rooms for the property
    const rooms = await DB.prepare(`
      SELECT room_id, room_number, room_qr_code
      FROM rooms
      WHERE property_id = ?
      ORDER BY room_number
    `).bind(propertyId).all()

    let generated = 0
    let skipped = 0

    // Generate QR codes for rooms that don't have one
    for (const room of rooms.results) {
      if (!room.room_qr_code) {
        // Generate unique QR code: ROOM-{PROPERTY_ID}-{ROOM_NUMBER}-{RANDOM}
        const roomQrCode = `ROOM-${propertyId}-${room.room_number}-${crypto.randomUUID().substring(0, 8).toUpperCase()}`
        
        await DB.prepare(`
          UPDATE rooms
          SET room_qr_code = ?
          WHERE room_id = ?
        `).bind(roomQrCode, room.room_id).run()
        
        generated++
      } else {
        skipped++
      }
    }

    return c.json({
      success: true,
      message: `Generated ${generated} room QR codes, skipped ${skipped} existing`,
      generated,
      skipped,
      total: rooms.results.length
    })
  } catch (error) {
    console.error('Generate room QR codes error:', error)
    return c.json({ error: 'Failed to generate QR codes: ' + error.message }, 500)
  }
})

