// QR Card Designer - Save/Update QR card template
app.put('/api/admin/qr-card/:property_id', async (c) => {
  const { DB } = c.env
  const { property_id } = c.req.param()
  const {
    card_title,
    card_subtitle,
    background_color,
    text_color,
    qr_size,
    border_radius,
    show_logo,
    festive_overlay,
    custom_message
  } = await c.req.json()

  try {
    // Check if template exists
    const existing = await DB.prepare(`
      SELECT design_id FROM qr_card_designs WHERE property_id = ?
    `).bind(property_id).first()

    if (existing) {
      // Update existing template
      await DB.prepare(`
        UPDATE qr_card_designs 
        SET card_title = ?,
            card_subtitle = ?,
            bottom_message = ?,
            card_bg_color = ?,
            text_color = ?,
            qr_size = ?,
            show_logo = ?,
            festive_overlay = ?,
            updated_at = datetime('now')
        WHERE property_id = ?
      `).bind(
        card_title,
        card_subtitle,
        custom_message || 'Scan for more information',
        background_color || '#FFFFFF',
        text_color || '#1F2937',
        qr_size || 'large',
        show_logo ? 1 : 0,
        festive_overlay || 'none',
        property_id
      ).run()
    } else {
      // Insert new template
      await DB.prepare(`
        INSERT INTO qr_card_designs (
          property_id, card_title, card_subtitle, bottom_message,
          card_bg_color, text_color, qr_size, show_logo,
          festive_overlay
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        property_id,
        card_title,
        card_subtitle,
        custom_message || 'Scan for more information',
        background_color || '#FFFFFF',
        text_color || '#1F2937',
        qr_size || 'large',
        show_logo ? 1 : 0,
        festive_overlay || 'none'
      ).run()
    }

    return c.json({ success: true })
  } catch (error) {
    console.error('Save QR card error:', error)
    return c.json({ error: 'Internal server error' }, 500)
  }
})

