// Update info page
app.put('/api/admin/info-pages/:page_id', async (c) => {
  const { DB } = c.env
  const { page_id } = c.req.param()
  const data = await c.req.json()
  
  try {
    // Build update query dynamically based on provided fields
    const updates = []
    const values = []
    
    if (data.title_en !== undefined) { updates.push('title_en = ?'); values.push(data.title_en); }
    if (data.content_en !== undefined) { updates.push('content_en = ?'); values.push(data.content_en); }
    if (data.icon_class !== undefined) { updates.push('icon_class = ?'); values.push(data.icon_class); }
    if (data.color_theme !== undefined) { updates.push('color_theme = ?'); values.push(data.color_theme); }
    if (data.layout_type !== undefined) { updates.push('layout_type = ?'); values.push(data.layout_type); }
    if (data.is_published !== undefined) { updates.push('is_published = ?'); values.push(data.is_published); }
    if (data.display_order !== undefined) { updates.push('display_order = ?'); values.push(data.display_order); }
    if (data.show_in_menu !== undefined) { updates.push('show_in_menu = ?'); values.push(data.show_in_menu); }
    
    // Add multilingual fields
    const languages = ['ar', 'de', 'ru', 'pl', 'it', 'fr', 'cs', 'uk', 'zh', 'es', 'ja', 'pt', 'ko', 'hi', 'tr', 'el', 'sv', 'no', 'da', 'ro', 'hu', 'fi', 'hr', 'sk', 'bg', 'sr', 'sl', 'th', 'id', 'vi', 'tl', 'ms'];
    languages.forEach(lang => {
      if (data[`title_${lang}`] !== undefined) {
        updates.push(`title_${lang} = ?`);
        values.push(data[`title_${lang}`]);
      }
      if (data[`content_${lang}`] !== undefined) {
        updates.push(`content_${lang} = ?`);
        values.push(data[`content_${lang}`]);
      }
    });
    
    updates.push('updated_at = datetime(\'now\')');
    values.push(page_id);
    
    await DB.prepare(`
      UPDATE info_pages SET ${updates.join(', ')} WHERE page_id = ?
    `).bind(...values).run()
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Update info page error:', error)
    return c.json({ error: 'Failed to update info page' }, 500)
  }
})

// Upload and parse CSV file for info pages (convert to styled table)
app.post('/api/admin/info-pages/parse-csv', async (c) => {
  try {
    const body = await c.req.json()
    const { csvData, fileName } = body
    
    if (!csvData) {
      return c.json({ error: 'No CSV data provided' }, 400)
    }
    
    // Parse CSV (handle comma, tab, and semicolon separators)
    const lines = csvData.split(/\r?\n/).filter(line => line.trim())
    
    if (lines.length === 0) {
      return c.json({ error: 'Empty file' }, 400)
    }
    
    // Detect separator (comma, tab, or semicolon)
    let separator = ','
    if (lines[0].includes('\t')) separator = '\t'
    else if (lines[0].includes(';') && !lines[0].includes(',')) separator = ';'
    
    // Parse rows with proper CSV handling (quotes, escaped characters)
    const rows = []
    for (const line of lines) {
      const cells = []
      let currentCell = ''
      let insideQuotes = false
      
      for (let i = 0; i < line.length; i++) {
        const char = line[i]
        const nextChar = line[i + 1]
        
        if (char === '"') {
          if (insideQuotes && nextChar === '"') {
            currentCell += '"'
            i++ // Skip next quote
          } else {
            insideQuotes = !insideQuotes
          }
        } else if (char === separator && !insideQuotes) {
          cells.push(currentCell.trim())
          currentCell = ''
        } else {
          currentCell += char
        }
      }
      cells.push(currentCell.trim())
      rows.push(cells)
    }
    
    // Generate styled HTML table with color coding based on content
    let tableHTML = '<div class="overflow-x-auto shadow-lg rounded-lg border border-gray-200">\n'
    tableHTML += '<table class="min-w-full bg-white">\n'
    
    // Header row with styling
    if (rows.length > 0) {
      tableHTML += '  <thead>\n    <tr class="bg-gradient-to-r from-green-400 via-blue-400 to-purple-400 text-gray-900">\n'
      rows[0].forEach(cell => {
        tableHTML += `      <th class="px-6 py-4 text-left text-sm font-bold uppercase tracking-wider border-r border-gray-300/40 last:border-r-0">${cell || '&nbsp;'}</th>\n`
      })
      tableHTML += '    </tr>\n  </thead>\n'
    }
    
    // Body rows with alternating colors and category-based styling
    if (rows.length > 1) {
      tableHTML += '  <tbody>\n'
      for (let i = 1; i < rows.length; i++) {
        const firstCell = rows[i][0]?.toLowerCase() || ''
        
        // Detect row type and apply color
        let rowBgClass = 'bg-white'
        let rowTextClass = 'text-gray-800'
        
        if (firstCell.includes('news') || rows[i][1]?.toLowerCase().includes('news')) {
          rowBgClass = 'bg-yellow-50'
        } else if (firstCell.includes('internal') || rows[i][1]?.toLowerCase().includes('internal')) {
          rowBgClass = 'bg-gray-100'
        } else if (firstCell.includes('entertainment') || firstCell.includes('intertirment') || rows[i][1]?.toLowerCase().includes('entertain')) {
          rowBgClass = 'bg-blue-50'
        } else if (i % 2 === 0) {
          rowBgClass = 'bg-gray-50'
        }
        
        tableHTML += `    <tr class="${rowBgClass} hover:bg-indigo-50 transition-colors">\n`
        rows[i].forEach((cell, idx) => {
          const cellClass = idx === 0 ? 'font-semibold text-gray-900' : rowTextClass
          tableHTML += `      <td class="px-6 py-3 text-sm ${cellClass} border-b border-gray-200">${cell || '&nbsp;'}</td>\n`
        })
        tableHTML += '    </tr>\n'
      }
      tableHTML += '  </tbody>\n'
    }
    
    tableHTML += '</table>\n</div>'
    
    return c.json({
      success: true,
      tableHTML: tableHTML,
      rowCount: rows.length,
      columnCount: rows[0]?.length || 0
    })
    
  } catch (error) {
    console.error('Parse CSV error:', error)
    return c.json({ error: 'Failed to parse file: ' + error.message }, 500)
  }
})

