// Get tables with availability check for à la carte bookings
app.get('/api/restaurant/:offering_id/tables/availability', async (c) => {
  const { DB } = c.env
  const { offering_id } = c.req.param()
  const date = c.req.query('date') || new Date().toISOString().split('T')[0]
  const time = c.req.query('time') || '12:00'
  
  try {
    // Get all tables
    const tables = await DB.prepare(`
      SELECT * FROM restaurant_tables 
      WHERE offering_id = ? AND is_active = 1
      ORDER BY table_number
    `).bind(offering_id).all()
    
    // Get reserved table_numbers for this date/time from alacarte_vouchers
    // Check for bookings within ±1 hour of the selected time
    const reservedTables = await DB.prepare(`
      SELECT DISTINCT table_number
      FROM alacarte_vouchers
      WHERE restaurant_id = ?
        AND reservation_date = ?
        AND table_number IS NOT NULL
        AND status IN ('confirmed', 'preparing', 'ready')
        AND (
          reservation_time = ?
          OR ABS(
            (CAST(SUBSTR(reservation_time, 1, 2) AS INTEGER) * 60 + CAST(SUBSTR(reservation_time, 4, 2) AS INTEGER))
            - (CAST(SUBSTR(?, 1, 2) AS INTEGER) * 60 + CAST(SUBSTR(?, 4, 2) AS INTEGER))
          ) <= 60
        )
    `).bind(offering_id, date, time, time, time).all()
    
    const reservedTableNumbers = new Set(reservedTables.results.map(r => r.table_number))
    
    console.log('Availability check:', {
      restaurant: offering_id,
      date,
      time,
      totalTables: tables.results.length,
      reservedTables: Array.from(reservedTableNumbers)
    })
    
    return c.json({ 
      success: true,
      tables: tables.results.map(t => ({
        ...t,
        features: t.features ? JSON.parse(t.features) : [],
        is_available: !reservedTableNumbers.has(t.table_number)
      }))
    })
  } catch (error) {
    console.error('Get tables availability error:', error)
    return c.json({ error: 'Failed to get tables availability' }, 500)
  }
})

// Create table (Admin)
app.post('/api/admin/restaurant/table', requirePermission('restaurant_tables'), async (c) => {
  const { DB } = c.env
  const data = await c.req.json()
  
  try {
    // Check if table exists (even if inactive)
    const existing = await DB.prepare(`
      SELECT table_id, is_active FROM restaurant_tables 
      WHERE offering_id = ? AND table_number = ?
    `).bind(data.offering_id, data.table_number).first()
    
    if (existing) {
      // If exists but inactive, reactivate it
      if (existing.is_active === 0) {
        await DB.prepare(`
          UPDATE restaurant_tables SET
            is_active = 1,
            table_name = ?,
            capacity = ?,
            position_x = ?,
            position_y = ?,
            width = ?,
            height = ?,
            shape = ?,
            table_type = ?,
            features = ?,
            rotation = ?,
            updated_at = CURRENT_TIMESTAMP
          WHERE table_id = ?
        `).bind(
          data.table_name || null,
          data.capacity,
          data.position_x || 0,
          data.position_y || 0,
          data.width || 100,
          data.height || 80,
          data.shape || 'rectangle',
          data.table_type || 'standard',
          JSON.stringify(data.features || []),
          data.rotation || 0,
          existing.table_id
        ).run()
        
        return c.json({ 
          success: true,
          table_id: existing.table_id,
          reactivated: true
        })
      } else {
        // Table exists and is active - duplicate error
        return c.json({ 
          error: 'Table number already exists', 
          details: 'UNIQUE constraint failed: restaurant_tables.table_number'
        }, 400)
      }
    }
    
    // Table doesn't exist, create new one
    const result = await DB.prepare(`
      INSERT INTO restaurant_tables (
        offering_id, table_number, table_name, capacity,
        position_x, position_y, width, height, shape, table_type, features, rotation
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      data.offering_id,
      data.table_number,
      data.table_name || null,
      data.capacity,
      data.position_x || 0,
      data.position_y || 0,
      data.width || 100,
      data.height || 80,
      data.shape || 'rectangle',
      data.table_type || 'standard',
      JSON.stringify(data.features || []),
      data.rotation || 0
    ).run()
    
    return c.json({ 
      success: true,
      table_id: result.meta.last_row_id
    })
  } catch (error: any) {
    console.error('Create table error:', error)
    const errorMsg = error?.message || error?.cause?.message || 'Failed to create table'
    return c.json({ 
      error: 'Failed to create table', 
      details: errorMsg,
      hint: errorMsg.includes('FOREIGN KEY') ? 'Restaurant offering does not exist' : undefined
    }, 500)
  }
})

