// Create table reservation
app.post('/api/restaurant/reserve', async (c) => {
  const { DB } = c.env
  const data = await c.req.json()
  
  try {
    // Validate table capacity
    const table = await DB.prepare(`
      SELECT capacity FROM restaurant_tables WHERE table_id = ?
    `).bind(data.table_id).first()
    
    if (!table) {
      return c.json({ error: 'Table not found' }, 404)
    }
    
    if (data.num_guests > table.capacity) {
      return c.json({ error: `Table capacity is ${table.capacity} guests` }, 400)
    }
    
    // Note: Removed duplicate booking check to allow multiple table bookings
    // Frontend should handle preventing duplicate submissions
    
    // Create or get guest
    let guest = await DB.prepare(`
      SELECT guest_id FROM guests WHERE email = ?
    `).bind(data.guest_email).first()
    
    let guestId = guest?.guest_id
    
    if (!guestId) {
      const nameParts = (data.guest_name || '').split(' ')
      const firstName = nameParts[0] || 'Guest'
      const lastName = nameParts.slice(1).join(' ') || ''
      
      const newGuest = await DB.prepare(`
        INSERT INTO guests (property_id, first_name, last_name, email, phone, preferred_language)
        VALUES (?, ?, ?, ?, ?, 'en')
      `).bind(data.property_id || 1, firstName, lastName, data.guest_email, data.guest_phone).run()
      guestId = newGuest.meta.last_row_id
    }
    
    // Get session details for reservation_time and date
    const session = await DB.prepare(`
      SELECT session_time, session_date, offering_id FROM dining_sessions WHERE session_id = ?
    `).bind(data.session_id).first()
    
    // Use guest_count or num_guests
    const guestCount = data.guest_count || data.num_guests || 1
    
    // Update guest with room number if provided
    if (data.room_number) {
      await DB.prepare(`
        UPDATE guests SET room_number = ? WHERE guest_id = ?
      `).bind(data.room_number, guestId).run()
    }
    
    // Create reservation
    const result = await DB.prepare(`
      INSERT INTO table_reservations (
        session_id, table_id, guest_id, property_id,
        reservation_date, reservation_time, num_guests,
        special_requests, dietary_requirements, room_number, status
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      data.session_id,
      data.table_id,
      guestId,
      data.property_id || 1,
      data.reservation_date || session.session_date,
      session.session_time,
      guestCount,
      data.special_requests || null,
      data.dietary_requirements || null,
      data.room_number || null,
      'confirmed'
    ).run()
    
    // Update session booking count
    await DB.prepare(`
      UPDATE dining_sessions 
      SET current_bookings = current_bookings + ?
      WHERE session_id = ?
    `).bind(guestCount, data.session_id).run()
    
    // Generate reservation reference (using reservation_id)
    const reservationRef = `RES${String(result.meta.last_row_id).padStart(6, '0')}`
    
    // Try to update existing timeline item first (if guest added it from timeline)
    const updateResult = await DB.prepare(`
      UPDATE timeline_items 
      SET status = 'confirmed', reference_id = ?, item_type = 'restaurant'
      WHERE item_date = ?
      AND status = 'planned'
      AND SUBSTR(start_time, 1, 5) = ?
    `).bind(
      result.meta.last_row_id,
      data.reservation_date || session.session_date,
      session.session_time.substring(0, 5)
    ).run()
    
    // If no timeline item was updated, create a new one (direct booking from Reserve button)
    if (updateResult.meta.changes === 0) {
      // Try to create timeline item (optional - don't fail reservation if this fails)
      try {
        // Get guest's stay plan
        const guestPass = await DB.prepare(`
          SELECT pass_id FROM digital_passes WHERE guest_id = ?
        `).bind(guestId).first()
        
        if (guestPass) {
          const plan = await DB.prepare(`
            SELECT plan_id FROM guest_stay_plans WHERE guest_id = ? AND property_id = ?
          `).bind(guestId, data.property_id || 1).first()
          
          if (plan) {
            // Get restaurant details
            const restaurant = await DB.prepare(`
              SELECT title_en FROM hotel_offerings WHERE offering_id = ?
            `).bind(session.offering_id).first()
            
            // Calculate end time (assume 2 hours for restaurant)
            const startHour = parseInt(session.session_time.substring(0, 2))
            const startMin = parseInt(session.session_time.substring(3, 5))
            const endHour = startHour + 2
            const endTime = `${String(endHour).padStart(2, '0')}:${String(startMin).padStart(2, '0')}`
            
            // Create timeline item
            await DB.prepare(`
              INSERT INTO timeline_items 
              (plan_id, item_type, reference_id, item_date, start_time, end_time, title, location, icon, color, status)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).bind(
              plan.plan_id,
              'restaurant',
              result.meta.last_row_id,
              data.reservation_date || session.session_date,
              session.session_time,
              endTime,
              restaurant?.title_en || 'Restaurant Reservation',
              'Resort Dining',
              '🍽️',
              'orange',
              'confirmed'
            ).run()
          }
        }
      } catch (timelineError) {
        // Timeline creation failed but reservation succeeded - that's OK
        console.warn('Timeline creation failed (non-critical):', timelineError)
      }
    }
    
    return c.json({ 
      success: true,
      reservation_id: result.meta.last_row_id,
      reservation_reference: reservationRef,
      message: 'Table reserved successfully!'
    })
  } catch (error) {
    console.error('Create reservation error:', error)
    return c.json({ 
      error: 'Failed to create reservation', 
      details: error.message || String(error),
      stack: error.stack 
    }, 500)
  }
})

// Cancel booking (Restaurant, Activity, Beach)
app.post('/api/booking/cancel/:type/:id', async (c) => {
  const { DB } = c.env
  const bookingType = c.req.param('type')
  const bookingId = c.req.param('id')
  
  try {
    if (bookingType === 'restaurant') {
      // First check if it's an alacarte voucher or regular table reservation
      const voucher = await DB.prepare(`
        SELECT voucher_id FROM alacarte_vouchers WHERE voucher_id = ?
      `).bind(bookingId).first()
      
      if (voucher) {
        // It's an alacarte voucher - cancel it
        await DB.prepare(`
          UPDATE alacarte_vouchers 
          SET status = 'cancelled'
          WHERE voucher_id = ?
        `).bind(bookingId).run()
        
        return c.json({ success: true, message: 'Restaurant booking cancelled successfully' })
      } else {
        // It's a regular table reservation - cancel it
        await DB.prepare(`
          UPDATE table_reservations 
          SET status = 'cancelled'
          WHERE reservation_id = ?
        `).bind(bookingId).run()
        
        return c.json({ success: true, message: 'Restaurant reservation cancelled' })
      }
      
    } else if (bookingType === 'activity') {
      // Cancel activity booking
      await DB.prepare(`
        UPDATE bookings 
        SET booking_status = 'cancelled'
        WHERE booking_id = ?
      `).bind(bookingId).run()
      
      return c.json({ success: true, message: 'Activity booking cancelled' })
      
    } else if (bookingType === 'beach') {
      // Cancel beach booking
      await DB.prepare(`
        UPDATE beach_bookings 
        SET booking_status = 'cancelled'
        WHERE beach_booking_id = ?
      `).bind(bookingId).run()
      
      return c.json({ success: true, message: 'Beach booking cancelled' })
      
    } else {
      return c.json({ error: 'Invalid booking type' }, 400)
    }
  } catch (error) {
    console.error('Cancel booking error:', error)
    return c.json({ error: 'Failed to cancel booking', details: error.message }, 500)
  }
})

