// Check in reservation
app.post('/api/admin/restaurant/reservation/:reference/checkin', requirePermission('restaurant_checkin'), async (c) => {
  const { DB } = c.env
  const { reference } = c.req.param()
  
  try {
    // SECURITY: Get authenticated property_id
    const property_id = getAuthenticatedPropertyId(c);
    if (!property_id) {
      return c.json({ error: 'Unauthorized' }, 401);
    }
    
    // Extract reservation_id from reference (RES000001 -> 1)
    const reservationId = reference.replace('RES', '').replace(/^0+/, '')
    
    // Validate reservation belongs to property
    const reservation = await DB.prepare(`
      SELECT tr.* FROM table_reservations tr
      JOIN restaurant_tables rt ON tr.table_id = rt.table_id
      JOIN hotel_offerings ho ON rt.offering_id = ho.offering_id
      WHERE tr.reservation_id = ? AND ho.property_id = ?
    `).bind(reservationId, property_id).first()
    
    if (!reservation) {
      return c.json({ error: 'Reservation not found' }, 404)
    }
    
    await DB.prepare(`
      UPDATE table_reservations 
      SET status = 'checked_in', checked_in_at = CURRENT_TIMESTAMP 
      WHERE reservation_id = ?
    `).bind(reservationId).run()
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Check in reservation error:', error)
    return c.json({ error: 'Failed to check in reservation' }, 500)
  }
})

// Cancel reservation
app.post('/api/admin/restaurant/reservation/:reference/cancel', async (c) => {
  const { DB } = c.env
  const { reference } = c.req.param()
  
  try {
    // SECURITY: Get authenticated property_id
    const property_id = getAuthenticatedPropertyId(c);
    if (!property_id) {
      return c.json({ error: 'Unauthorized' }, 401);
    }
    
    // Extract reservation_id from reference (RES000001 -> 1)
    const reservationId = reference.replace('RES', '').replace(/^0+/, '')
    
    // Validate reservation belongs to property
    const reservation = await DB.prepare(`
      SELECT tr.* FROM table_reservations tr
      JOIN restaurant_tables rt ON tr.table_id = rt.table_id
      JOIN hotel_offerings ho ON rt.offering_id = ho.offering_id
      WHERE tr.reservation_id = ? AND ho.property_id = ?
    `).bind(reservationId, property_id).first()
    
    if (!reservation) {
      return c.json({ error: 'Reservation not found' }, 404)
    }
    
    await DB.prepare(`
      UPDATE table_reservations 
      SET status = 'cancelled', cancelled_at = CURRENT_TIMESTAMP 
      WHERE reservation_id = ?
    `).bind(reservationId).run()
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Cancel reservation error:', error)
    return c.json({ error: 'Failed to cancel reservation' }, 500)
  }
})

// Check in reservation by ID (for staff dashboard)
app.post('/api/admin/restaurant/reservations/:reservation_id/check-in', async (c) => {
  const { DB } = c.env
  const { reservation_id } = c.req.param()
  
  try {
    // SECURITY: Get authenticated property_id
    const property_id = getAuthenticatedPropertyId(c);
    if (!property_id) {
      return c.json({ error: 'Unauthorized' }, 401);
    }
    
    // Validate reservation belongs to property
    const checkReservation = await DB.prepare(`
      SELECT tr.* FROM table_reservations tr
      JOIN restaurant_tables rt ON tr.table_id = rt.table_id
      JOIN hotel_offerings ho ON rt.offering_id = ho.offering_id
      WHERE tr.reservation_id = ? AND ho.property_id = ?
    `).bind(reservation_id, property_id).first()
    
    if (!checkReservation) {
      return c.json({ error: 'Reservation not found' }, 404)
    }
    
    // Update reservation status to checked_in
    await DB.prepare(`
      UPDATE table_reservations 
      SET status = 'checked_in', checked_in_at = CURRENT_TIMESTAMP 
      WHERE reservation_id = ?
    `).bind(reservation_id).run()
    
    // Create guest dining session for this reservation
    const reservation = await DB.prepare(`
      SELECT tr.*, rt.table_number, rt.offering_id, g.first_name, g.last_name, g.phone
      FROM table_reservations tr
      JOIN restaurant_tables rt ON tr.table_id = rt.table_id
      JOIN guests g ON tr.guest_id = g.guest_id
      WHERE tr.reservation_id = ?
    `).bind(reservation_id).first()
    
    if (reservation) {
      const guestName = `${reservation.first_name} ${reservation.last_name}`
      
      // Create guest dining session
      await DB.prepare(`
        INSERT INTO guest_dining_sessions (
          offering_id, guest_name, number_of_guests, table_number, 
          session_date, session_time, status, phone_number, special_requests, source
        ) VALUES (?, ?, ?, ?, ?, ?, 'active', ?, ?, 'reservation')
      `).bind(
        reservation.offering_id,
        guestName,
        reservation.num_guests,
        reservation.table_number,
        reservation.reservation_date,
        reservation.reservation_time,
        reservation.phone,
        reservation.special_requests
      ).run()
    }
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Check in reservation error:', error)
    return c.json({ error: 'Failed to check in reservation' }, 500)
  }
})

