// ========================================
// STRUCTURED MENU SYSTEM - AI PARSING
// ========================================

// Parse OCR text into structured menu (categories → items → prices)
app.post('/api/admin/restaurant/menus/:menu_id/parse-structure', async (c) => {
  const { menu_id } = c.req.param()
  const { DB, OPENAI_API_KEY } = c.env
  
  if (!OPENAI_API_KEY) {
    return c.json({ error: 'OpenAI API key not configured' }, 500)
  }

  try {
    // Get menu with extracted text
    const menu = await DB.prepare(`
      SELECT menu_id, menu_name, extracted_text 
      FROM restaurant_menus 
      WHERE menu_id = ?
    `).bind(menu_id).first()

    if (!menu || !menu.extracted_text) {
      return c.json({ error: 'Menu text not extracted yet' }, 400)
    }

    // Create parsing log
    await DB.prepare(`
      INSERT INTO menu_parsing_logs (menu_id, raw_text, parsing_status)
      VALUES (?, ?, 'processing')
    `).bind(menu_id, menu.extracted_text).run()

    // AI prompt for structured parsing
    const prompt = `You are a restaurant menu parser. Parse the following menu text into structured JSON format.

Extract:
1. Categories (Appetizers, Main Course, Desserts, Beverages, etc.)
2. For each item: name, description, price, currency, dietary info (vegetarian/vegan/gluten-free), spice level, allergens

CRITICAL RULES:
- Return ONLY valid, parseable JSON - no comments, no trailing commas
- For spice_level, ONLY use: "none", "mild", "medium", "hot", "extra_hot"
- If price is unclear, use 0
- If allergens are unclear, use empty array []
- Keep descriptions under 100 characters
- DO NOT add trailing commas in arrays or objects

Menu Text:
${menu.extracted_text}

Return ONLY valid JSON in this exact format (NO trailing commas):
{
  "categories": [
    {
      "name": "Category Name",
      "description": "Optional category description",
      "items": [
        {
          "name": "Item Name",
          "description": "Item description",
          "price": 12.99,
          "currency": "USD",
          "is_vegetarian": false,
          "is_vegan": false,
          "is_gluten_free": false,
          "spice_level": "none",
          "allergens": ["nuts", "dairy"]
        }
      ]
    }
  ]
}`

    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${OPENAI_API_KEY}`
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: 'You are a menu parsing expert. Return only valid JSON with NO trailing commas.' },
          { role: 'user', content: prompt }
        ],
        temperature: 0.2,
        max_tokens: 8000  // Increased to handle large menus
      })
    })

    const data = await response.json()
    
    // Check if response was truncated
    if (data.choices[0].finish_reason === 'length') {
      throw new Error('AI response was truncated due to length. The menu is too large. Please upload fewer images or a smaller menu.')
    }
    
    let aiResponse = data.choices[0].message.content.trim()
    
    // Remove markdown code blocks if present
    aiResponse = aiResponse.replace(/```json\s*/g, '').replace(/```\s*/g, '')
    
    // Parse AI response - extract JSON object
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/)
    if (!jsonMatch) {
      console.error('AI Response:', aiResponse)
      throw new Error('AI did not return valid JSON')
    }
    
    let jsonString = jsonMatch[0]
    
    // Clean common JSON formatting issues from AI responses
    // 1. Remove trailing commas before closing brackets/braces (multiple passes)
    let prevLength = 0
    while (prevLength !== jsonString.length) {
      prevLength = jsonString.length
      jsonString = jsonString.replace(/,(\s*[}\]])/g, '$1')
    }
    // 2. Remove comments (// or /* */)
    jsonString = jsonString.replace(/\/\/.*$/gm, '')
    jsonString = jsonString.replace(/\/\*[\s\S]*?\*\//g, '')
    // 3. Fix multiple commas
    jsonString = jsonString.replace(/,\s*,+/g, ',')
    // 4. Fix missing commas between array elements (common AI error)
    jsonString = jsonString.replace(/\}\s*\{/g, '},{')
    jsonString = jsonString.replace(/\]\s*\[/g, '],[')
    // 5. Remove any weird unicode characters
    jsonString = jsonString.replace(/[\u0000-\u001F\u007F-\u009F]/g, '')
    
    let parsed
    try {
      parsed = JSON.parse(jsonString)
    } catch (parseError) {
      // Log detailed error information
      console.error('JSON Parse Error. Raw response:', aiResponse.substring(0, 1000) + '...')
      console.error('Extracted JSON (before cleaning):', jsonMatch[0].substring(0, 500) + '...')
      console.error('Cleaned JSON (after cleaning):', jsonString.substring(0, 500) + '...')
      console.error('Error at position:', parseError.message)
      
      // Try to extract the problematic section
      const errorMatch = parseError.message.match(/position (\d+)/)
      if (errorMatch) {
        const errorPos = parseInt(errorMatch[1])
        const contextStart = Math.max(0, errorPos - 100)
        const contextEnd = Math.min(jsonString.length, errorPos + 100)
        console.error('Context around error:', jsonString.substring(contextStart, contextEnd))
      }
      
      throw new Error('Failed to parse AI response as JSON: ' + parseError.message)
    }
    
    // Save parsed data to database
    let totalItems = 0
    
    for (let catIndex = 0; catIndex < parsed.categories.length; catIndex++) {
      const category = parsed.categories[catIndex]
      
      // Insert category
      const catResult = await DB.prepare(`
        INSERT INTO menu_categories (menu_id, category_name, category_description, display_order)
        VALUES (?, ?, ?, ?)
      `).bind(menu_id, category.name, category.description || '', catIndex).run()
      
      const categoryId = catResult.meta.last_row_id
      
      // Insert items
      for (let itemIndex = 0; itemIndex < category.items.length; itemIndex++) {
        const item = category.items[itemIndex]
        
        // Normalize spice level to valid values
        const validSpiceLevels = ['none', 'mild', 'medium', 'hot', 'extra_hot']
        let spiceLevel = 'none'
        if (item.spice_level) {
          const normalized = item.spice_level.toLowerCase().trim()
          if (validSpiceLevels.includes(normalized)) {
            spiceLevel = normalized
          } else if (normalized.includes('extra') || normalized.includes('very')) {
            spiceLevel = 'extra_hot'
          } else if (normalized.includes('hot') || normalized.includes('spicy')) {
            spiceLevel = 'hot'
          } else if (normalized.includes('medium') || normalized.includes('moderate')) {
            spiceLevel = 'medium'
          } else if (normalized.includes('mild') || normalized.includes('low') || normalized.includes('light')) {
            spiceLevel = 'mild'
          }
        }
        
        await DB.prepare(`
          INSERT INTO menu_items (
            category_id, item_name, description, price, currency,
            is_vegetarian, is_vegan, is_gluten_free, spice_level,
            allergens, display_order
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          categoryId,
          item.name,
          item.description || '',
          item.price || 0,
          item.currency || 'USD',
          item.is_vegetarian ? 1 : 0,
          item.is_vegan ? 1 : 0,
          item.is_gluten_free ? 1 : 0,
          spiceLevel,
          JSON.stringify(item.allergens || []),
          itemIndex
        ).run()
        
        totalItems++
      }
    }

    // Update parsing log
    await DB.prepare(`
      UPDATE menu_parsing_logs 
      SET parsed_json = ?, categories_found = ?, items_found = ?, parsing_status = 'completed'
      WHERE menu_id = ? AND parsing_status = 'processing'
    `).bind(JSON.stringify(parsed), parsed.categories.length, totalItems, menu_id).run()

    // CRITICAL: Update restaurant_menus.ocr_status to 'completed' so menu appears in menu-display
    await DB.prepare(`
      UPDATE restaurant_menus 
      SET ocr_status = 'completed', ocr_processed_at = CURRENT_TIMESTAMP
      WHERE menu_id = ?
    `).bind(menu_id).run()

    return c.json({
      success: true,
      message: `Menu parsed! Found ${parsed.categories.length} categories with ${totalItems} items`,
      categories: parsed.categories.length,
      items: totalItems
    })

  } catch (error) {
    console.error('Menu parsing error:', error)
    console.error('Error stack:', error.stack)
    
    const errorMessage = error.message || 'Unknown error'
    
    // Update log with error
    try {
      await DB.prepare(`
        UPDATE menu_parsing_logs 
        SET parsing_status = 'failed', error_message = ?
        WHERE menu_id = ? AND parsing_status = 'processing'
      `).bind(errorMessage, menu_id).run()
    } catch (dbError) {
      console.error('Failed to update parsing log:', dbError)
    }
    
    // Update restaurant_menus status
    try {
      await DB.prepare(`
        UPDATE restaurant_menus 
        SET ocr_status = 'failed'
        WHERE menu_id = ?
      `).bind(menu_id).run()
    } catch (dbError) {
      console.error('Failed to update menu status:', dbError)
    }
    
    return c.json({ 
      error: 'Menu parsing failed: ' + errorMessage,
      details: error.stack || errorMessage
    }, 500)
  }
})

// Get structured menu data
app.get('/api/admin/restaurant/menus/:menu_id/structure', async (c) => {
  const { menu_id } = c.req.param()
  const { DB } = c.env

  try {
    // Get categories with items
    const categories = await DB.prepare(`
      SELECT category_id, category_name, category_description, display_order
      FROM menu_categories
      WHERE menu_id = ?
      ORDER BY display_order ASC
    `).bind(menu_id).all()

    const result = []
    
    for (const category of categories.results) {
      const items = await DB.prepare(`
        SELECT * FROM menu_items
        WHERE category_id = ?
        ORDER BY display_order ASC
      `).bind(category.category_id).all()
      
      result.push({
        ...category,
        items: items.results.map(item => ({
          ...item,
          allergens: JSON.parse(item.allergens || '[]')
        }))
      })
    }

    return c.json({ success: true, categories: result })
  } catch (error) {
    return c.json({ error: 'Failed to get menu structure: ' + error.message }, 500)
  }
})

