app.put('/api/admin/all-inclusive/tiers/:tier_id', async (c) => {
  const { DB } = c.env
  const { tier_id } = c.req.param()
  const property_id = c.req.header('X-Property-ID')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }
  
  try {
    const body = await c.req.json()
    const {
      tier_display_name,
      tier_color,
      tier_icon,
      tier_description,
      tier_features,
      access_locations,
      daily_upgrade_price,
      is_active,
      display_order,
      alacarte_meals_per_stay,
      alacarte_eligible_restaurants,
      alacarte_premium_surcharge,
      alacarte_privileges_message
    } = body
    
    // Verify tier belongs to property
    const tier = await DB.prepare(`
      SELECT * FROM all_inclusive_tiers WHERE tier_id = ? AND property_id = ?
    `).bind(tier_id, property_id).first()
    
    if (!tier) {
      return c.json({ error: 'Tier not found' }, 404)
    }
    
    await DB.prepare(`
      UPDATE all_inclusive_tiers
      SET tier_display_name = ?,
          tier_color = ?,
          tier_icon = ?,
          tier_description = ?,
          tier_features = ?,
          access_locations = ?,
          daily_upgrade_price = ?,
          is_active = ?,
          display_order = ?,
          alacarte_meals_per_stay = ?,
          alacarte_eligible_restaurants = ?,
          alacarte_premium_surcharge = ?,
          alacarte_privileges_message = ?,
          updated_at = CURRENT_TIMESTAMP
      WHERE tier_id = ? AND property_id = ?
    `).bind(
      tier_display_name || tier.tier_display_name,
      tier_color || tier.tier_color,
      tier_icon || tier.tier_icon,
      tier_description,
      tier_features ? JSON.stringify(tier_features) : tier.tier_features,
      access_locations ? JSON.stringify(access_locations) : tier.access_locations,
      daily_upgrade_price !== undefined ? daily_upgrade_price : tier.daily_upgrade_price,
      is_active !== undefined ? is_active : tier.is_active,
      display_order !== undefined ? display_order : tier.display_order,
      alacarte_meals_per_stay !== undefined ? alacarte_meals_per_stay : (tier.alacarte_meals_per_stay || 0),
      alacarte_eligible_restaurants !== undefined ? alacarte_eligible_restaurants : tier.alacarte_eligible_restaurants,
      alacarte_premium_surcharge !== undefined ? alacarte_premium_surcharge : (tier.alacarte_premium_surcharge || 0),
      alacarte_privileges_message !== undefined ? alacarte_privileges_message : tier.alacarte_privileges_message,
      tier_id,
      property_id
    ).run()
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Update tier error:', error)
    return c.json({ error: 'Failed to update tier' }, 500)
  }
})

// Admin: Delete tier
app.delete('/api/admin/all-inclusive/tiers/:tier_id', async (c) => {
  const { DB } = c.env
  const { tier_id } = c.req.param()
  const property_id = c.req.header('X-Property-ID')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }
  
  try {
    // Check if any passes are using this tier
    const passCount = await DB.prepare(`
      SELECT COUNT(*) as count FROM digital_passes
      WHERE tier_id = ? AND pass_status = 'active'
    `).bind(tier_id).first()
    
    if (passCount && passCount.count > 0) {
      return c.json({ error: `Cannot delete tier: ${passCount.count} active passes are using it` }, 400)
    }
    
    await DB.prepare(`
      DELETE FROM all_inclusive_tiers
      WHERE tier_id = ? AND property_id = ?
    `).bind(tier_id, property_id).run()
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Delete tier error:', error)
    return c.json({ error: 'Failed to delete tier' }, 500)
  }
})

