// Admin: Get all digital passes for property
app.get('/api/admin/all-inclusive/passes', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  const status = c.req.query('status') // active, expired, all
  const page = parseInt(c.req.query('page') || '1')
  const per_page = 50
  const offset = (page - 1) * per_page
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }
  
  try {
    let query = `
      SELECT 
        dp.*,
        ait.tier_display_name,
        ait.tier_color,
        ait.tier_icon,
        (SELECT COUNT(*) FROM pass_family_members WHERE pass_id = dp.pass_id) as family_count
      FROM digital_passes dp
      JOIN all_inclusive_tiers ait ON dp.tier_id = ait.tier_id
      WHERE dp.property_id = ?
    `
    
    const bindings = [property_id]
    
    if (status && status !== 'all') {
      query += ` AND dp.pass_status = ?`
      bindings.push(status)
    }
    
    query += ` ORDER BY dp.issued_at DESC LIMIT ? OFFSET ?`
    bindings.push(per_page, offset)
    
    const passes = await DB.prepare(query).bind(...bindings).all()
    
    // Get total count
    let countQuery = `SELECT COUNT(*) as total FROM digital_passes WHERE property_id = ?`
    const countBindings = [property_id]
    
    if (status && status !== 'all') {
      countQuery += ` AND pass_status = ?`
      countBindings.push(status)
    }
    
    const countResult = await DB.prepare(countQuery).bind(...countBindings).first()
    
    return c.json({
      success: true,
      passes: passes.results || [],
      pagination: {
        page,
        per_page,
        total: countResult?.total || 0,
        total_pages: Math.ceil((countResult?.total || 0) / per_page)
      }
    })
  } catch (error) {
    console.error('Get passes error:', error)
    return c.json({ error: 'Failed to get passes' }, 500)
  }
})

// Admin: Create new digital pass
app.post('/api/admin/all-inclusive/passes', requirePermission('settings_manage'), async (c) => {
  const { DB } = c.env
  const property_id = getAuthenticatedPropertyId(c)
  const user_id = c.req.header('X-User-ID')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized' }, 401)
  }
  
  try {
    const body = await c.req.json()
    const {
      primary_guest_name,
      primary_guest_photo_url,
      guest_email,
      guest_phone,
      room_number,
      tier_id,
      num_adults,
      num_children,
      valid_from,
      valid_until,
      family_members,
      notes
    } = body
    
    // Validate required fields
    if (!primary_guest_name || !tier_id || !valid_from || !valid_until) {
      return c.json({ error: 'Missing required fields' }, 400)
    }
    
    // Verify tier belongs to property
    const tier = await DB.prepare(`
      SELECT * FROM all_inclusive_tiers WHERE tier_id = ? AND property_id = ?
    `).bind(tier_id, property_id).first()
    
    if (!tier) {
      return c.json({ error: 'Invalid tier' }, 400)
    }
    
    // Generate unique pass reference
    const timestamp = Date.now()
    const random = Math.random().toString(36).substring(2, 7).toUpperCase()
    const pass_reference = `PASS-${timestamp}-${random}`
    
    // Generate QR secret for rotating QR codes
    const qr_secret = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
    
    // Generate secure guest access token for self-service portal
    const guest_access_token = Math.random().toString(36).substring(2) + Date.now().toString(36) + Math.random().toString(36).substring(2)
    
    // Generate unique NFC ID (16-character alphanumeric for NFC compatibility)
    const nfc_id = 'NFC' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).substring(2, 10).toUpperCase()
    
    // Generate 6-digit PIN for easy guest access
    const guest_pin = Math.floor(100000 + Math.random() * 900000).toString() // 100000-999999
    
    // Try to insert with NFC support first, fallback to without if columns don't exist
    let result
    try {
      // Try to insert with guest_pin column
      result = await DB.prepare(`
        INSERT INTO digital_passes (
          property_id, pass_reference, primary_guest_name, primary_guest_photo_url,
          guest_email, guest_phone, room_number, tier_id, pass_status,
          num_adults, num_children, valid_from, valid_until,
          qr_secret, issued_by_user_id, notes, guest_access_token, verification_preference, qr_code_displayed,
          nfc_id, nfc_enabled, guest_pin
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, 'qr', 1, ?, 1, ?)
      `).bind(
        property_id,
        pass_reference,
        primary_guest_name,
        primary_guest_photo_url || null,
        guest_email || null,
        guest_phone || null,
        room_number || null,
        tier_id,
        num_adults || 1,
        num_children || 0,
        valid_from,
        valid_until,
        qr_secret,
        user_id || null,
        notes || null,
        guest_access_token,
        nfc_id,
        guest_pin
      ).run()
    } catch (pinError) {
      console.log('guest_pin column not found, trying without PIN:', pinError)
      try {
        // Fallback: Insert with NFC but without PIN
        result = await DB.prepare(`
          INSERT INTO digital_passes (
            property_id, pass_reference, primary_guest_name, primary_guest_photo_url,
            guest_email, guest_phone, room_number, tier_id, pass_status,
            num_adults, num_children, valid_from, valid_until,
            qr_secret, issued_by_user_id, notes, guest_access_token, verification_preference, qr_code_displayed,
            nfc_id, nfc_enabled
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, 'qr', 1, ?, 1)
        `).bind(
          property_id,
          pass_reference,
          primary_guest_name,
          primary_guest_photo_url || null,
          guest_email || null,
          guest_phone || null,
          room_number || null,
          tier_id,
          num_adults || 1,
          num_children || 0,
          valid_from,
          valid_until,
          qr_secret,
          user_id || null,
          notes || null,
          guest_access_token,
          nfc_id
        ).run()
      } catch (nfcError) {
      console.log('NFC columns not found, inserting without NFC support:', nfcError)
      // Fallback: Insert without NFC columns
      result = await DB.prepare(`
        INSERT INTO digital_passes (
          property_id, pass_reference, primary_guest_name, primary_guest_photo_url,
          guest_email, guest_phone, room_number, tier_id, pass_status,
          num_adults, num_children, valid_from, valid_until,
          qr_secret, issued_by_user_id, notes, guest_access_token, verification_preference, qr_code_displayed
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, 'qr', 1)
      `).bind(
        property_id,
        pass_reference,
        primary_guest_name,
        primary_guest_photo_url || null,
        guest_email || null,
        guest_phone || null,
        room_number || null,
        tier_id,
        num_adults || 1,
        num_children || 0,
        valid_from,
        valid_until,
        qr_secret,
        user_id || null,
        notes || null,
        guest_access_token
      ).run()
      }
    }
    
    const pass_id = result.meta.last_row_id
    
    // Insert family members if provided
    if (family_members && Array.isArray(family_members)) {
      for (const member of family_members) {
        await DB.prepare(`
          INSERT INTO pass_family_members (
            pass_id, member_name, member_type, member_age, member_photo_url, relationship, is_primary
          ) VALUES (?, ?, ?, ?, ?, ?, ?)
        `).bind(
          pass_id,
          member.member_name,
          member.member_type || 'adult',
          member.member_age || null,
          member.member_photo_url || null,
          member.relationship || null,
          member.is_primary || 0
        ).run()
      }
    }
    
    // Generate guest portal URL with secure token
    const guest_portal_url = `/guest-portal.html?pass=${pass_reference}&token=${guest_access_token}`
    
    return c.json({
      success: true,
      pass_id,
      pass_reference,
      guest_pin,
      pass_url: `/guest-pass/${pass_reference}`,
      guest_portal_url,
      guest_access_token
    })
  } catch (error) {
    console.error('Create pass error:', error)
    return c.json({ error: 'Failed to create pass' }, 500)
  }
})

