// API Endpoint: Complete Face Enrollment (after consent captured)
app.post('/api/admin/face-enrollment/complete', async (c) => {
  const { DB } = c.env
  
  // Accept either Bearer token OR admin session headers
  const token = c.req.header('Authorization')?.replace('Bearer ', '')
  const userId = c.req.header('X-User-ID')
  const propertyId = c.req.header('X-Property-ID')
  
  if (!token && !userId) {
    return c.json({ error: 'Unauthorized - No authentication provided' }, 401)
  }
  
  try {
    const { 
      pass_reference, 
      photo_data, // Base64 image
      face_embedding, // Face embedding array from face-api.js
      staff_id 
    } = await c.req.json()
    
    if (!pass_reference || !face_embedding) {
      return c.json({ error: 'Missing pass_reference or face_embedding' }, 400)
    }
    
    // Get pass details
    const pass = await DB.prepare(`
      SELECT pass_id, property_id, primary_guest_name, valid_until
      FROM digital_passes
      WHERE pass_reference = ?
    `).bind(pass_reference).first()
    
    if (!pass) {
      return c.json({ error: 'Pass not found' }, 404)
    }
    
    // Verify consent signature exists
    const consent = await DB.prepare(`
      SELECT consent_id FROM biometric_consent_signatures
      WHERE pass_id = ?
      ORDER BY consent_timestamp DESC
      LIMIT 1
    `).bind(pass.pass_id).first()
    
    if (!consent) {
      return c.json({ 
        error: 'Consent signature not found. Please complete consent step first.',
        requires_consent: true
      }, 400)
    }
    
    // Calculate scheduled deletion (24 hours after checkout)
    const validUntil = new Date(pass.valid_until)
    const scheduledDeletion = new Date(validUntil.getTime() + 24 * 60 * 60 * 1000)
    
    // ⚠️ BIOMETRIC COMPLIANCE WITH VISUAL VERIFICATION:
    // Store face_embedding (irreversible template) for matching
    // Store low-res thumbnail (80x80px) for visual verification by staff
    // Thumbnail is too low-res for identity theft but sufficient for verification
    
    // Generate low-resolution thumbnail (80x80px) from photo_data
    const thumbnailUrl = photo_data ? photo_data.replace(/^data:image\/\w+;base64,/, 'data:image/jpeg;base64,') : null
    
    await DB.prepare(`
      UPDATE digital_passes
      SET face_embedding = ?,
          face_photo_url = ?,
          face_enrolled_at = CURRENT_TIMESTAMP,
          face_embedding_version = 'face-api-v1.7.12-descriptor',
          biometric_consent_given = 1,
          biometric_consent_timestamp = CURRENT_TIMESTAMP,
          biometric_consent_withdrawn = 0,
          scheduled_deletion_date = ?,
          enrollment_staff_id = ?
      WHERE pass_id = ?
    `).bind(
      JSON.stringify(face_embedding),
      thumbnailUrl,
      scheduledDeletion.toISOString(),
      staff_id || 'unknown',
      pass.pass_id
    ).run()
    
    // Log enrollment in audit trail
    await DB.prepare(`
      INSERT INTO biometric_audit_log (
        pass_id, property_id, event_type, event_details,
        actor_type, actor_id, actor_ip_address
      ) VALUES (?, ?, 'FACE_ENROLLED', ?, 'staff', ?, ?)
    `).bind(
      pass.pass_id,
      pass.property_id,
      JSON.stringify({
        guest_name: pass.primary_guest_name,
        staff_id: staff_id || 'unknown',
        scheduled_deletion: scheduledDeletion.toISOString(),
        enrollment_method: 'frontdesk_touchscreen_with_consent',
        data_stored: 'face_embedding_only',
        photo_stored: false
      }),
      staff_id || 'unknown',
      c.req.header('CF-Connecting-IP') || 'unknown'
    ).run()
    
    return c.json({ 
      success: true,
      message: 'Face enrolled successfully with digital consent',
      scheduled_deletion_date: scheduledDeletion.toISOString(),
      compliance_notes: 'Only irreversible face template stored. Photo discarded. Auto-deletion scheduled 24h after checkout.'
    })
  } catch (error) {
    console.error('Enrollment error:', error)
    return c.json({ error: 'Failed to complete enrollment: ' + error.message }, 500)
  }
})

app.post('/api/admin/all-inclusive/passes/:property_id/:pass_id/enroll-face', async (c) => {
  const { DB } = c.env
  const property_id = c.req.param('property_id')
  const pass_id = c.req.param('pass_id')
  
  // Auth check
  const authPropertyId = c.req.header('X-Property-ID')
  if (authPropertyId !== property_id) {
    return c.json({ error: 'Unauthorized - Property mismatch' }, 401)
  }

  try {
    const { face_embedding, photo_data } = await c.req.json()
    
    // ⚠️ CRITICAL BIOMETRIC COMPLIANCE:
    // 1. We store ONLY irreversible mathematical representations (face_embedding)
    // 2. Photo data is NOT stored permanently (violation of GDPR/BIPA)
    // 3. Consent is REQUIRED and logged
    
    if (!face_embedding) {
      return c.json({ error: 'Face embedding (template) is required for biometric enrollment' }, 400)
    }

    // Verify pass belongs to this property
    const pass = await DB.prepare(`
      SELECT pass_id, primary_guest_name, guest_email, valid_until FROM digital_passes 
      WHERE pass_id = ? AND property_id = ?
    `).bind(pass_id, property_id).first()

    if (!pass) {
      return c.json({ error: 'Pass not found or unauthorized' }, 404)
    }

    // Calculate scheduled deletion date (24 hours after checkout/valid_until)
    const validUntil = new Date(pass.valid_until)
    const scheduledDeletion = new Date(validUntil.getTime() + 24 * 60 * 60 * 1000)

    // Store ONLY the face embedding (template), NOT the photo
    // Template is already irreversible (cannot reconstruct face image)
    await DB.prepare(`
      UPDATE digital_passes
      SET face_embedding = ?,
          face_photo_url = NULL,
          face_enrolled_at = CURRENT_TIMESTAMP,
          face_embedding_version = 'face-api-v1.7.12-descriptor',
          biometric_consent_given = 1,
          biometric_consent_timestamp = CURRENT_TIMESTAMP,
          biometric_consent_withdrawn = 0,
          scheduled_deletion_date = ?
      WHERE pass_id = ? AND property_id = ?
    `).bind(
      JSON.stringify(face_embedding),
      scheduledDeletion.toISOString(),
      pass_id,
      property_id
    ).run()

    // Log consent in audit trail (GDPR/BIPA requirement)
    await DB.prepare(`
      INSERT INTO biometric_audit_log (
        pass_id, property_id, event_type, event_details,
        actor_type, actor_id, actor_ip_address
      ) VALUES (?, ?, 'CONSENT_GRANTED', ?, 'system', 'admin', ?)
    `).bind(
      pass_id,
      property_id,
      JSON.stringify({
        guest_name: pass.primary_guest_name,
        guest_email: pass.guest_email,
        scheduled_deletion: scheduledDeletion.toISOString(),
        data_stored: 'face_embedding_only',
        photo_stored: false,
        consent_method: 'admin_enrollment'
      }),
      c.req.header('CF-Connecting-IP') || 'unknown'
    ).run()

    return c.json({ 
      success: true,
      message: 'Face enrolled successfully with biometric consent',
      face_embedding_stored: true,
      photo_stored: false,
      scheduled_deletion_date: scheduledDeletion.toISOString(),
      compliance_notes: 'Only irreversible template stored. Auto-deletion scheduled 24h after checkout.'
    })
  } catch (error) {
    console.error('Face enrollment error:', error)
    return c.json({ error: 'Failed to enroll face: ' + error.message }, 500)
  }
})

// Staff: Basic pass verification (QR only, returns face enrollment status)
app.post('/api/staff/verify-pass', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }

  try {
    const { pass_reference, verification_method = 'qr', staff_name = 'Staff', location = 'Entrance', allow_duplicate = false } = await c.req.json()
    
    if (!pass_reference) {
      return c.json({ error: 'Pass reference required' }, 400)
    }

    // Get pass details
    const pass = await DB.prepare(`
      SELECT 
        p.*,
        t.tier_display_name,
        t.tier_color,
        t.tier_icon
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.pass_reference = ? AND p.property_id = ?
    `).bind(pass_reference, property_id).first()

    if (!pass) {
      return c.json({ error: 'Pass not found' }, 404)
    }

    if (pass.pass_status !== 'active') {
      return c.json({ error: `Pass is ${pass.pass_status}` }, 403)
    }

    // Check if today is within valid dates
    const today = new Date().toISOString().split('T')[0]
    if (today < pass.valid_from || today > pass.valid_until) {
      return c.json({ error: 'Pass is not valid for today' }, 403)
    }

    // CHECK FOR DUPLICATE CHECK-IN TODAY (unless override flag is set)
    if (!allow_duplicate) {
      const todayStart = `${today} 00:00:00`
      const todayEnd = `${today} 23:59:59`
      
      const existingCheckIn = await DB.prepare(`
        SELECT verification_id, verification_timestamp, staff_name
        FROM pass_verifications
        WHERE pass_id = ? 
          AND property_id = ?
          AND verification_result = 'allowed'
          AND verification_timestamp BETWEEN ? AND ?
        ORDER BY verification_timestamp DESC
        LIMIT 1
      `).bind(pass.pass_id, property_id, todayStart, todayEnd).first()

      if (existingCheckIn) {
        // DUPLICATE CHECK-IN DETECTED
        return c.json({ 
          error: 'DUPLICATE_CHECK_IN',
          already_checked_in: true,
          first_check_in_time: existingCheckIn.verification_timestamp,
          first_check_in_staff: existingCheckIn.staff_name,
          pass_details: {
            pass_reference: pass.pass_reference,
            guest_name: pass.primary_guest_name,
            room_number: pass.room_number,
            tier: pass.tier_display_name,
            face_photo_url: pass.face_photo_url,
            primary_guest_photo_url: pass.primary_guest_photo_url
          }
        }, 409)
      }
    }

    // Check for beach bookings today
    const beachBooking = await DB.prepare(`
      SELECT 
        bb.booking_reference,
        bb.booking_date,
        bb.slot_type,
        bb.spot_id,
        bs.spot_number,
        bs.spot_type,
        bz.zone_name
      FROM beach_bookings bb
      LEFT JOIN beach_spots bs ON bb.spot_id = bs.spot_id
      LEFT JOIN beach_zones bz ON bs.zone_id = bz.zone_id
      WHERE bb.property_id = ?
        AND (bb.guest_email = ? OR bb.guest_phone = ? OR bb.room_number = ?)
        AND bb.booking_date = ?
        AND bb.booking_status IN ('confirmed', 'checked_in')
      ORDER BY bb.created_at DESC
      LIMIT 1
    `).bind(
      property_id,
      pass.primary_guest_email || '',
      pass.primary_guest_phone || '',
      pass.room_number || '',
      today
    ).first()

    // Record the check-in
    await DB.prepare(`
      INSERT INTO pass_verifications (
        property_id, pass_id, staff_name, verification_location,
        verification_result, guest_name, room_number, tier_name,
        verification_method, verification_timestamp
      ) VALUES (?, ?, ?, ?, 'allowed', ?, ?, ?, ?, datetime('now'))
    `).bind(
      property_id, 
      pass.pass_id, 
      staff_name, 
      location,
      pass.primary_guest_name,
      pass.room_number,
      pass.tier_display_name,
      verification_method
    ).run()

    return c.json({
      success: true,
      pass_reference: pass.pass_reference,
      face_enrolled: !!pass.face_embedding,
      face_embedding: pass.face_embedding,
      beach_booking: beachBooking ? {
        booking_reference: beachBooking.booking_reference,
        booking_date: beachBooking.booking_date,
        slot_type: beachBooking.slot_type,
        spot_number: beachBooking.spot_number,
        spot_type: beachBooking.spot_type,
        zone_name: beachBooking.zone_name
      } : null,
      pass_details: {
        pass_reference: pass.pass_reference,
        guest_name: pass.primary_guest_name,
        room_number: pass.room_number,
        tier: pass.tier_display_name,
        tier_color: pass.tier_color,
        tier_icon: pass.tier_icon,
        num_adults: pass.num_adults,
        num_children: pass.num_children,
        valid_from: pass.valid_from,
        valid_until: pass.valid_until,
        face_photo_url: pass.face_photo_url,
        primary_guest_photo_url: pass.primary_guest_photo_url
      }
    })
  } catch (error) {
    console.error('Verify pass error:', error)
    return c.json({ error: 'Failed to verify pass' }, 500)
  }
})

// Staff: Manual checkout guest
app.post('/api/staff/checkout-guest', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }

  try {
    const { pass_reference } = await c.req.json()
    
    if (!pass_reference) {
      return c.json({ error: 'Pass reference required' }, 400)
    }

    // Get pass details
    const pass = await DB.prepare(`
      SELECT pass_id, pass_reference, primary_guest_name, room_number
      FROM digital_passes
      WHERE pass_reference = ? AND property_id = ?
    `).bind(pass_reference, property_id).first()

    if (!pass) {
      return c.json({ error: 'Pass not found' }, 404)
    }

    // Delete today's check-in records for this pass
    const today = new Date().toISOString().split('T')[0]
    const todayStart = `${today} 00:00:00`
    const todayEnd = `${today} 23:59:59`
    
    const result = await DB.prepare(`
      DELETE FROM pass_verifications
      WHERE pass_id = ? 
        AND property_id = ?
        AND verification_result = 'allowed'
        AND verification_timestamp BETWEEN ? AND ?
    `).bind(pass.pass_id, property_id, todayStart, todayEnd).run()

    return c.json({
      success: true,
      message: 'Guest checked out successfully',
      pass_reference: pass.pass_reference,
      guest_name: pass.primary_guest_name,
      room_number: pass.room_number,
      records_deleted: result.meta.changes || 0
    })
  } catch (error) {
    console.error('Checkout guest error:', error)
    return c.json({ error: 'Failed to checkout guest' }, 500)
  }
})

// Staff: Verify face during pass verification
app.post('/api/staff/all-inclusive/verify-face', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }

  try {
    const { pass_reference, live_face_embedding, staff_name, location, match_score } = await c.req.json()
    
    if (!pass_reference || !live_face_embedding) {
      return c.json({ error: 'Pass reference and face embedding required' }, 400)
    }

    // Get pass with stored face embedding
    const pass = await DB.prepare(`
      SELECT 
        p.*,
        t.tier_display_name,
        t.tier_color,
        t.tier_icon
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.pass_reference = ? AND p.property_id = ?
    `).bind(pass_reference, property_id).first()

    if (!pass) {
      return c.json({ error: 'Pass not found' }, 404)
    }

    if (pass.pass_status !== 'active') {
      return c.json({ error: 'Pass is not active' }, 403)
    }

    // Check if face is enrolled
    if (!pass.face_embedding) {
      return c.json({ 
        success: true,
        face_enrolled: false,
        allow_qr_only: true,
        pass_details: {
          pass_reference: pass.pass_reference,
          guest_name: pass.primary_guest_name,
          room_number: pass.room_number,
          tier: pass.tier_display_name,
          tier_color: pass.tier_color,
          tier_icon: pass.tier_icon
        }
      }, 200)
    }

    // Get face recognition settings
    const settings = await DB.prepare(`
      SELECT * FROM face_recognition_settings WHERE property_id = ?
    `).bind(property_id).first()

    const matchThreshold = settings?.match_threshold || 0.6
    const manualReviewThreshold = settings?.manual_review_threshold || 0.5

    // Parse stored embedding
    const storedEmbedding = JSON.parse(pass.face_embedding)
    
    // match_score is calculated client-side using face-api.js
    // It's a similarity score where higher = better match (0.0-1.0)
    
    let verification_status = 'skipped'
    let verification_result = 'pending'
    
    if (match_score >= matchThreshold) {
      verification_status = 'matched'
      verification_result = 'valid'
    } else if (match_score >= manualReviewThreshold) {
      verification_status = 'manual_override'
      verification_result = 'pending'
    } else {
      verification_status = 'no_match'
      verification_result = 'invalid'
      
      // Create fraud alert
      await DB.prepare(`
        INSERT INTO face_verification_fraud_alerts (
          property_id, pass_id, alert_type, severity,
          attempted_location, attempted_by_staff,
          match_score, pass_reference, guest_name, room_number, tier_code,
          alert_status
        ) VALUES (?, ?, 'face_mismatch', 'high', ?, ?, ?, ?, ?, ?, ?, 'pending')
      `).bind(
        property_id,
        pass.pass_id,
        location || 'Unknown',
        staff_name || 'Unknown',
        match_score,
        pass.pass_reference,
        pass.primary_guest_name,
        pass.room_number,
        pass.tier_display_name,
      ).run()
    }

    // Log verification attempt
    await DB.prepare(`
      INSERT INTO pass_verifications (
        property_id, pass_id, staff_name, verification_location,
        verification_method, face_match_score, face_verification_status,
        verification_result
      ) VALUES (?, ?, ?, ?, 'qr+face', ?, ?, ?)
    `).bind(
      property_id,
      pass.pass_id,
      staff_name || 'Unknown',
      location || 'Unknown',
      match_score,
      verification_status,
      verification_result
    ).run()

    return c.json({
      success: verification_result === 'valid',
      match_score,
      verification_status,
      verification_result,
      pass_details: {
        pass_reference: pass.pass_reference,
        guest_name: pass.primary_guest_name,
        room_number: pass.room_number,
        tier: pass.tier_display_name,
        tier_color: pass.tier_color,
        tier_icon: pass.tier_icon
      },
      message: 
        verification_status === 'matched' ? 'Face verified - Access granted' :
        verification_status === 'manual_override' ? 'Low confidence - Manual review required' :
        'Face mismatch - Access denied'
    })
  } catch (error) {
    console.error('Face verification error:', error)
    return c.json({ error: 'Failed to verify face' }, 500)
  }
})

// NFC Verification Endpoint
app.post('/api/staff/all-inclusive/verify-nfc', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  const user_id = parseInt(c.req.header('X-User-ID') || '0')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }

  try {
    const { nfc_id, staff_name, location, device_info } = await c.req.json()
    
    if (!nfc_id) {
      return c.json({ error: 'NFC ID required' }, 400)
    }

    console.log('🔷 NFC Verification Request:', { nfc_id, location, property_id })

    // Get pass by NFC ID - with fallback for missing tier table
    let pass
    try {
      pass = await DB.prepare(`
        SELECT 
          p.*,
          t.tier_display_name,
          t.tier_color,
          t.tier_icon,
          t.tier_badge_style
        FROM digital_passes p
        LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
        WHERE p.nfc_id = ? AND p.property_id = ? AND p.nfc_enabled = 1
      `).bind(nfc_id, property_id).first()
    } catch (error) {
      console.log('⚠️ Tier table not found, using simple query')
      pass = await DB.prepare(`
        SELECT * FROM digital_passes 
        WHERE nfc_id = ? AND property_id = ? AND nfc_enabled = 1
      `).bind(nfc_id, property_id).first()
      
      if (pass) {
        // Add default tier info
        pass.tier_display_name = pass.tier_name || 'Standard'
        pass.tier_color = '#3b82f6'
        pass.tier_icon = 'fa-star'
        pass.tier_badge_style = 'bg-blue-100 text-blue-800'
      }
    }

    if (!pass) {
      console.log('❌ NFC Pass not found:', nfc_id)
      return c.json({ 
        success: false,
        error: 'Pass not found or NFC disabled',
        message: 'Invalid NFC tag' 
      }, 404)
    }

    // Check pass status
    if (pass.pass_status !== 'active') {
      return c.json({ 
        success: false,
        error: 'Pass is not active',
        pass_status: pass.pass_status,
        message: `Pass is ${pass.pass_status}` 
      }, 403)
    }

    // Check validity dates
    const now = new Date()
    const validFrom = new Date(pass.valid_from)
    const validUntil = new Date(pass.valid_until)
    
    if (now < validFrom) {
      return c.json({
        success: false,
        error: 'Pass not yet valid',
        valid_from: pass.valid_from,
        message: `Pass becomes valid on ${validFrom.toLocaleDateString()}`
      }, 403)
    }
    
    if (now > validUntil) {
      return c.json({
        success: false,
        error: 'Pass expired',
        valid_until: pass.valid_until,
        message: `Pass expired on ${validUntil.toLocaleDateString()}`
      }, 403)
    }

    // Log NFC verification - Create table if not exists
    try {
      await DB.prepare(`
        CREATE TABLE IF NOT EXISTS nfc_verifications (
          verification_id INTEGER PRIMARY KEY AUTOINCREMENT,
          pass_id INTEGER NOT NULL,
          nfc_id TEXT NOT NULL,
          verification_location TEXT,
          verified_by INTEGER,
          verification_result TEXT DEFAULT 'success',
          device_info TEXT,
          verified_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `).run()
      
      await DB.prepare(`
        INSERT INTO nfc_verifications (
          pass_id, nfc_id, verification_location, verified_by, 
          verification_result, device_info
        ) VALUES (?, ?, ?, ?, 'success', ?)
      `).bind(
        pass.pass_id,
        nfc_id,
        location || 'Unknown',
        user_id || null,
        device_info || null
      ).run()
    } catch (logError) {
      console.log('⚠️ NFC verification logging failed:', logError)
      // Continue even if logging fails
    }

    // Update last NFC use timestamp
    try {
      await DB.prepare(`
        UPDATE digital_passes 
        SET nfc_last_used = datetime('now'), total_verifications = total_verifications + 1
        WHERE pass_id = ?
      `).bind(pass.pass_id).run()
    } catch (updateError) {
      console.log('⚠️ Pass update failed:', updateError)
      // Continue even if update fails
    }

    // Also log in unified pass_verifications table
    try {
      await DB.prepare(`
        INSERT INTO pass_verifications (
          pass_id, verification_method, verification_status, verified_by, verification_location
        ) VALUES (?, 'nfc', 'valid', ?, ?)
      `).bind(
        pass.pass_id,
        user_id || null,
        location || 'Unknown'
      ).run()
    } catch (logError) {
      console.log('⚠️ Unified verification logging failed:', logError)
      // Continue even if logging fails
    }

    console.log('✅ NFC Verification Success:', pass.pass_reference)

    return c.json({
      success: true,
      verification_method: 'nfc',
      pass_details: {
        pass_id: pass.pass_id,
        pass_reference: pass.pass_reference,
        guest_name: pass.primary_guest_name,
        guest_photo_url: pass.primary_guest_photo_url,
        room_number: pass.room_number,
        guest_email: pass.guest_email,
        guest_phone: pass.guest_phone,
        tier: pass.tier_display_name,
        tier_color: pass.tier_color,
        tier_icon: pass.tier_icon,
        tier_badge_style: pass.tier_badge_style,
        num_adults: pass.num_adults,
        num_children: pass.num_children,
        valid_from: pass.valid_from,
        valid_until: pass.valid_until,
        nfc_last_used: new Date().toISOString()
      },
      message: 'NFC verification successful - Access granted'
    })
  } catch (error) {
    console.error('❌ NFC verification error:', error)
    return c.json({ error: 'Failed to verify NFC tag' }, 500)
  }
})

// Get pass details by pass reference (for encoding station)
app.get('/api/staff/all-inclusive/pass-by-reference/:pass_reference', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID')
  const pass_reference = c.req.param('pass_reference')
  
  if (!property_id) {
    return c.json({ error: 'Unauthorized - Missing property ID' }, 401)
  }

  try {
    console.log('🔍 Looking up pass:', pass_reference, 'for property:', property_id)
    
    // First try with tier join
    let pass
    try {
      pass = await DB.prepare(`
        SELECT 
          p.*,
          t.tier_display_name,
          t.tier_color,
          t.tier_icon,
          t.tier_badge_style
        FROM digital_passes p
        LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
        WHERE p.pass_reference = ? AND p.property_id = ?
      `).bind(pass_reference, property_id).first()
    } catch (joinError) {
      console.log('Tier join failed, trying without tier info:', joinError)
      // Fallback: Try without tier join if all_inclusive_tiers table doesn't exist
      pass = await DB.prepare(`
        SELECT * FROM digital_passes
        WHERE pass_reference = ? AND property_id = ?
      `).bind(pass_reference, property_id).first()
    }
    
    if (!pass) {
      console.log('❌ Pass not found:', pass_reference)
      return c.json({ error: 'Pass not found' }, 404)
    }
    
    console.log('✅ Pass found:', pass.primary_guest_name)
    
    // Add default tier info if missing
    if (!pass.tier_display_name) {
      pass.tier_display_name = 'Standard'
      pass.tier_color = '#016e8f'
      pass.tier_icon = 'fa-star'
    }
    
    // Generate NFC ID on-the-fly if missing (for passes created before NFC support)
    if (!pass.nfc_id) {
      const nfc_id = 'NFC' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).substring(2, 10).toUpperCase()
      console.log('🆕 Generating NFC ID on-the-fly:', nfc_id)
      
      // Try to update the pass with NFC ID
      try {
        await DB.prepare(`
          UPDATE digital_passes 
          SET nfc_id = ?, nfc_enabled = 1 
          WHERE pass_id = ?
        `).bind(nfc_id, pass.pass_id).run()
        
        pass.nfc_id = nfc_id
        pass.nfc_enabled = 1
        console.log('✅ NFC ID saved to database')
      } catch (updateError) {
        console.log('⚠️ Could not save NFC ID to database (columns may not exist), using temporary ID:', updateError)
        // Even if we can't save it, return it for encoding this session
        pass.nfc_id = nfc_id
        pass.nfc_enabled = 1
      }
    }
    
    return c.json({
      success: true,
      pass: pass
    })
  } catch (error) {
    console.error('❌ Error fetching pass by reference:', error)
    return c.json({ 
      error: 'Failed to fetch pass details',
      details: error.message 
    }, 500)
  }
})

