// Guest: Link pass by PIN (for session linking)
app.post('/api/guest/link-pass', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  const { guest_pin } = await c.req.json()
  
  if (!guest_pin) {
    return c.json({ error: 'PIN code required' }, 400)
  }
  
  try {
    // Get pass with property isolation using PIN
    const pass = await DB.prepare(`
      SELECT 
        p.pass_reference,
        p.guest_access_token,
        p.primary_guest_name,
        p.guest_email,
        p.guest_phone,
        p.room_number,
        p.num_adults,
        p.num_children,
        p.pass_status,
        p.valid_from,
        p.valid_until,
        p.property_id,
        t.tier_display_name as tier_name,
        t.tier_color
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.guest_pin = ? AND p.property_id = ?
    `).bind(guest_pin, propertyId).first()
    
    if (!pass) {
      return c.json({ 
        success: false, 
        error: 'Invalid PIN code. Please check and try again.' 
      }, 404)
    }
    
    // Check if pass is active
    if (pass.pass_status !== 'active') {
      return c.json({ 
        success: false, 
        error: 'This pass is not active. Please contact the front desk.' 
      }, 400)
    }
    
    // Check if pass is valid (current date between valid_from and valid_until)
    const now = new Date()
    const validFrom = new Date(pass.valid_from)
    const validUntil = new Date(pass.valid_until)
    
    if (now < validFrom) {
      return c.json({ 
        success: false, 
        error: 'This pass is not yet active. Valid from: ' + validFrom.toLocaleDateString() 
      }, 400)
    }
    
    if (now > validUntil) {
      return c.json({ 
        success: false, 
        error: 'This pass has expired. Valid until: ' + validUntil.toLocaleDateString() 
      }, 400)
    }
    
    // Split name into first and last
    const nameParts = pass.primary_guest_name?.split(' ') || ['', '']
    const firstName = nameParts[0] || ''
    const lastName = nameParts.slice(1).join(' ') || ''
    
    // Return success with token for session
    return c.json({
      success: true,
      guest: {
        pass_reference: pass.pass_reference,
        token: pass.guest_access_token, // This is the secure session token
        first_name: firstName,
        last_name: lastName,
        full_name: pass.primary_guest_name,
        email: pass.guest_email,
        phone: pass.guest_phone,
        room_number: pass.room_number,
        adults: pass.num_adults,
        children: pass.num_children,
        tier: pass.tier_name,
        tier_color: pass.tier_color
      }
    })
  } catch (error) {
    console.error('Link pass error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to link pass. Please try again.' 
    }, 500)
  }
})

// Guest: Request pass link by name (for guests who don't have PIN)
app.post('/api/guest/request-pass-link', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  const { guest_name, page_url } = await c.req.json()
  
  if (!guest_name) {
    return c.json({ error: 'Guest name required' }, 400)
  }
  
  try {
    // Insert request into pass_link_requests table (create if not exists)
    await DB.prepare(`
      CREATE TABLE IF NOT EXISTS pass_link_requests (
        request_id INTEGER PRIMARY KEY AUTOINCREMENT,
        property_id INTEGER NOT NULL,
        guest_name TEXT NOT NULL,
        page_url TEXT,
        request_status TEXT DEFAULT 'pending',
        linked_pass_reference TEXT,
        linked_by_staff_id INTEGER,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        resolved_at DATETIME
      )
    `).run()
    
    // Insert the request
    const result = await DB.prepare(`
      INSERT INTO pass_link_requests (property_id, guest_name, page_url, request_status)
      VALUES (?, ?, ?, 'pending')
    `).bind(propertyId, guest_name, page_url || '').run()
    
    return c.json({
      success: true,
      message: 'Request sent to front desk',
      request_id: result.meta.last_row_id
    })
    
  } catch (error) {
    console.error('Request pass link error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to send request. Please try again.' 
    }, 500)
  }
})

// Guest: Check pass link request status
app.get('/api/guest/check-pass-link-status/:request_id', async (c) => {
  const { DB } = c.env
  const { request_id } = c.req.param()
  const propertyId = c.req.header('X-Property-ID') || c.req.query('property_id') || '1'
  
  if (!request_id) {
    return c.json({ error: 'Request ID required' }, 400)
  }
  
  try {
    const request = await DB.prepare(`
      SELECT 
        r.request_id,
        r.request_status,
        r.linked_pass_reference,
        r.created_at,
        r.resolved_at
      FROM pass_link_requests r
      WHERE r.request_id = ? AND r.property_id = ?
    `).bind(request_id, propertyId).first()
    
    if (!request) {
      return c.json({ error: 'Request not found' }, 404)
    }
    
    // If completed, fetch the pass details
    if (request.request_status === 'completed' && request.linked_pass_reference) {
      const pass = await DB.prepare(`
        SELECT 
          p.pass_reference,
          p.primary_guest_name,
          p.room_number,
          p.guest_pin,
          p.guest_access_token,
          p.num_adults,
          p.num_children,
          t.tier_display_name as tier_name,
          t.tier_color
        FROM digital_passes p
        LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
        WHERE p.pass_reference = ? AND p.property_id = ?
      `).bind(request.linked_pass_reference, propertyId).first()
      
      if (pass) {
        return c.json({
          success: true,
          status: 'completed',
          pass: {
            pass_reference: pass.pass_reference,
            full_name: pass.primary_guest_name,
            first_name: pass.primary_guest_name.split(' ')[0],
            last_name: pass.primary_guest_name.split(' ').slice(1).join(' '),
            room_number: pass.room_number,
            guest_pin: pass.guest_pin,
            guest_access_token: pass.guest_access_token,
            num_adults: pass.num_adults,
            num_children: pass.num_children,
            tier_name: pass.tier_name || 'Standard',
            tier_color: pass.tier_color || '#3B82F6'
          }
        })
      }
    }
    
    return c.json({
      success: true,
      status: request.request_status,
      created_at: request.created_at,
      resolved_at: request.resolved_at
    })
    
  } catch (error) {
    console.error('Check pass link status error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to check status' 
    }, 500)
  }
})

// Admin: Get pending pass link requests
app.get('/api/admin/pass-link-requests', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  
  try {
    const requests = await DB.prepare(`
      SELECT 
        r.*,
        u.first_name as linked_by_first_name,
        u.last_name as linked_by_last_name
      FROM pass_link_requests r
      LEFT JOIN users u ON r.linked_by_staff_id = u.user_id
      WHERE r.property_id = ?
      ORDER BY 
        CASE r.request_status 
          WHEN 'pending' THEN 1 
          WHEN 'completed' THEN 2 
          ELSE 3 
        END,
        r.created_at DESC
      LIMIT 50
    `).bind(propertyId).all()
    
    return c.json({
      success: true,
      requests: requests.results || []
    })
    
  } catch (error) {
    console.error('Get pass link requests error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to load requests',
      requests: []
    }, 500)
  }
})

// Admin: Link guest name request to digital pass
app.post('/api/admin/link-guest-to-pass', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  const userId = c.req.header('X-User-ID')
  const { request_id, pass_reference } = await c.req.json()
  
  if (!request_id || !pass_reference) {
    return c.json({ error: 'Request ID and Pass Reference required' }, 400)
  }
  
  try {
    // Verify pass exists
    const pass = await DB.prepare(`
      SELECT pass_id, pass_reference, primary_guest_name, room_number
      FROM digital_passes
      WHERE pass_reference = ? AND property_id = ?
    `).bind(pass_reference, propertyId).first()
    
    if (!pass) {
      return c.json({ error: 'Pass not found' }, 404)
    }
    
    // Update request status
    await DB.prepare(`
      UPDATE pass_link_requests
      SET request_status = 'completed',
          linked_pass_reference = ?,
          linked_by_staff_id = ?,
          resolved_at = CURRENT_TIMESTAMP
      WHERE request_id = ? AND property_id = ?
    `).bind(pass_reference, userId || null, request_id, propertyId).run()
    
    return c.json({
      success: true,
      message: 'Guest linked to pass successfully',
      pass: {
        pass_reference: pass.pass_reference,
        guest_name: pass.primary_guest_name,
        room_number: pass.room_number
      }
    })
    
  } catch (error) {
    console.error('Link guest to pass error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to link guest. Please try again.' 
    }, 500)
  }
})

