// Admin: Update guest lookup request status (dismiss, etc.)
app.patch('/api/admin/guest-lookup-requests/:request_id', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  const requestId = c.req.param('request_id')
  const { status } = await c.req.json()
  
  if (!status || !['pending', 'completed', 'dismissed'].includes(status)) {
    return c.json({ error: 'Invalid status' }, 400)
  }
  
  try {
    await DB.prepare(`
      UPDATE pass_link_requests
      SET request_status = ?,
          resolved_at = CASE WHEN ? != 'pending' THEN CURRENT_TIMESTAMP ELSE resolved_at END
      WHERE request_id = ? AND property_id = ?
    `).bind(status, status, requestId, propertyId).run()
    
    return c.json({
      success: true,
      message: 'Request status updated'
    })
    
  } catch (error) {
    console.error('Update request status error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to update request status' 
    }, 500)
  }
})

// Admin: Search for digital passes by room number or PIN
app.get('/api/admin/search-digital-pass', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.query('property_id') || '1'
  const query = c.req.query('query') || ''
  
  if (!query || query.length < 2) {
    return c.json({ 
      success: false, 
      error: 'Search query too short',
      passes: []
    }, 400)
  }
  
  try {
    // Search by room number or guest PIN
    const passes = await DB.prepare(`
      SELECT 
        p.pass_id,
        p.pass_reference,
        p.primary_guest_name,
        p.room_number,
        p.guest_pin,
        p.valid_from,
        p.valid_until,
        p.pass_status,
        t.tier_name,
        t.tier_color
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.property_id = ? 
        AND p.pass_status = 'active'
        AND (p.room_number LIKE ? OR p.guest_pin LIKE ?)
      ORDER BY p.pass_id DESC
      LIMIT 20
    `).bind(propertyId, '%' + query + '%', '%' + query + '%').all()
    
    return c.json({
      success: true,
      passes: passes.results || []
    })
    
  } catch (error) {
    console.error('Search digital pass error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to search passes',
      passes: []
    }, 500)
  }
})

// Admin: Create new digital pass and link to guest request
app.post('/api/admin/create-and-link-pass', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  const userId = c.req.header('X-User-ID')
  const { request_id, guest_name, room_number, num_adults, num_children, valid_from, valid_until, tier_id } = await c.req.json()
  
  if (!request_id || !guest_name || !room_number || !valid_from || !valid_until) {
    return c.json({ error: 'Missing required fields' }, 400)
  }
  
  try {
    // Generate a unique 6-digit PIN
    const guestPin = Math.floor(100000 + Math.random() * 900000).toString()
    
    // Generate pass reference (format: PASS-YYYYMMDD-XXXX)
    const date = new Date()
    const dateStr = date.toISOString().split('T')[0].replace(/-/g, '')
    const randomStr = Math.random().toString(36).substring(2, 6).toUpperCase()
    const passReference = `PASS-${dateStr}-${randomStr}`
    
    // Generate guest access token
    const guestAccessToken = Math.random().toString(36).substring(2) + Date.now().toString(36)
    
    // Generate QR secret (for secure QR code generation)
    const qrSecret = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
    
    // Validate property exists
    const propertyExists = await DB.prepare(`
      SELECT property_id FROM properties WHERE property_id = ?
    `).bind(propertyId).first()
    
    if (!propertyExists) {
      console.error('Property does not exist:', propertyId)
      return c.json({ 
        success: false, 
        error: 'Invalid property ID. Please contact support.'
      }, 400)
    }
    
    // Use provided tier_id or find/create one
    let finalTierId = tier_id ? parseInt(tier_id) : null
    let tierName = null
    
    if (finalTierId) {
      // Validate the provided tier exists and belongs to this property
      const tier = await DB.prepare(`
        SELECT tier_id, tier_display_name, tier_code 
        FROM all_inclusive_tiers 
        WHERE tier_id = ? AND property_id = ?
      `).bind(finalTierId, propertyId).first()
      
      if (!tier) {
        return c.json({ 
          success: false, 
          error: 'Invalid tier selected. Please choose a valid tier or refresh the page.'
        }, 400)
      }
      
      tierName = tier.tier_display_name || tier.tier_code
      console.log('Using selected tier:', finalTierId, tierName)
    } else {
      // No tier provided, try to find or create one
      try {
        // First, try to find existing tier
        const tier = await DB.prepare(`
          SELECT tier_id, tier_display_name, tier_code FROM all_inclusive_tiers 
          WHERE property_id = ?
          ORDER BY 
            CASE tier_code 
              WHEN 'Standard' THEN 1 
              ELSE 2 
            END
          LIMIT 1
        `).bind(propertyId).first()
        
        if (tier) {
          finalTierId = tier.tier_id
          tierName = tier.tier_display_name || tier.tier_code
          console.log('Found existing tier:', finalTierId, tierName)
        } else {
          // No tiers exist, try to create a default Standard tier
          console.log('No tiers found for property', propertyId, '- attempting to create default tier')
          
          try {
            // Make sure all_inclusive_tiers table exists without foreign keys
            await DB.prepare(`
              CREATE TABLE IF NOT EXISTS all_inclusive_tiers (
                tier_id INTEGER PRIMARY KEY AUTOINCREMENT,
                property_id INTEGER NOT NULL,
                tier_code TEXT NOT NULL,
                tier_display_name TEXT NOT NULL,
                tier_description TEXT,
                tier_color TEXT DEFAULT '#3B82F6',
                display_order INTEGER DEFAULT 1,
                is_active INTEGER DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
              )
            `).run()
            
            const createTierResult = await DB.prepare(`
              INSERT INTO all_inclusive_tiers (
                property_id, tier_code, tier_display_name, tier_description, 
                tier_color, display_order, is_active
              ) VALUES (?, 'Standard', 'Standard', 'Standard All-Inclusive Package', '#3B82F6', 1, 1)
            `).bind(parseInt(propertyId)).run()
            
            finalTierId = createTierResult.meta.last_row_id
            tierName = 'Standard'
            console.log('Created default tier with ID:', finalTierId)
          } catch (createError) {
            console.error('Failed to create tier:', createError)
          }
        }
      } catch (tierError) {
        console.error('Tier lookup/create error:', tierError)
      }
    }
    
    if (!finalTierId) {
      return c.json({ 
        success: false, 
        error: 'Unable to assign tier to digital pass. Please configure All-Inclusive tiers first in the admin settings, or contact support.'
      }, 400)
    }
    
    // Ensure table exists (without strict foreign keys)
    await DB.prepare(`
      CREATE TABLE IF NOT EXISTS digital_passes (
        pass_id INTEGER PRIMARY KEY AUTOINCREMENT,
        property_id INTEGER NOT NULL,
        pass_reference TEXT UNIQUE NOT NULL,
        primary_guest_name TEXT NOT NULL,
        room_number TEXT NOT NULL,
        guest_pin TEXT NOT NULL,
        guest_access_token TEXT NOT NULL,
        qr_secret TEXT NOT NULL,
        guest_email TEXT,
        guest_phone TEXT,
        num_adults INTEGER DEFAULT 2,
        num_children INTEGER DEFAULT 0,
        tier_id INTEGER,
        valid_from DATE NOT NULL,
        valid_until DATE NOT NULL,
        pass_status TEXT DEFAULT 'active',
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `).run()
    
    // Insert new digital pass (tier_id is required)
    const passResult = await DB.prepare(`
      INSERT INTO digital_passes (
        property_id, pass_reference, primary_guest_name, 
        room_number, guest_pin, guest_access_token, qr_secret,
        num_adults, num_children, tier_id,
        valid_from, valid_until, pass_status
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active')
    `).bind(
      parseInt(propertyId), // Ensure it's an integer
      passReference,
      guest_name,
      room_number,
      guestPin,
      guestAccessToken,
      qrSecret,
      num_adults || 2,
      num_children || 0,
      finalTierId, // Use the validated tier ID
      valid_from,
      valid_until
    ).run()
    
    // Update the guest lookup request
    await DB.prepare(`
      UPDATE pass_link_requests
      SET request_status = 'completed',
          linked_pass_reference = ?,
          linked_by_staff_id = ?,
          resolved_at = CURRENT_TIMESTAMP
      WHERE request_id = ? AND property_id = ?
    `).bind(passReference, userId || null, request_id, propertyId).run()
    
    return c.json({
      success: true,
      message: 'Digital pass created and linked successfully',
      pass_reference: passReference,
      guest_pin: guestPin,
      room_number: room_number,
      tier_name: tierName || 'Standard'
    })
    
  } catch (error) {
    console.error('Create and link pass error:', error)
    console.error('Error details:', {
      message: error.message,
      stack: error.stack,
      propertyId,
      guest_name,
      room_number
    })
    return c.json({ 
      success: false, 
      error: 'Failed to create digital pass: ' + (error.message || 'Unknown error')
    }, 500)
  }
})

// Guest: Lookup pass by room number (for front desk)
app.get('/api/guest/lookup-room', async (c) => {
  const { DB } = c.env
  const property_id = c.req.query('property_id') || '1'
  const room_number = c.req.query('room_number')
  
  if (!room_number) {
    return c.json({ error: 'Room number required' }, 400)
  }
  
  try {
    // Look up active pass for this room
    const pass = await DB.prepare(`
      SELECT 
        pass_id,
        pass_reference,
        primary_guest_name,
        room_number,
        num_adults,
        num_children,
        pass_status,
        valid_from,
        valid_until
      FROM digital_passes
      WHERE room_number = ? AND property_id = ? AND pass_status = 'active'
      ORDER BY pass_id DESC
      LIMIT 1
    `).bind(room_number, property_id).first()
    
    if (!pass) {
      return c.json({ 
        success: false, 
        error: 'No active pass found for this room' 
      }, 404)
    }
    
    // Check if pass is currently valid
    const now = new Date()
    const validFrom = new Date(pass.valid_from)
    const validUntil = new Date(pass.valid_until)
    
    if (now < validFrom || now > validUntil) {
      return c.json({ 
        success: false, 
        error: 'Pass found but not currently valid' 
      }, 400)
    }
    
    return c.json({
      success: true,
      pass: {
        pass_id: pass.pass_id,
        pass_reference: pass.pass_reference,
        primary_guest_name: pass.primary_guest_name,
        room_number: pass.room_number,
        num_adults: pass.num_adults,
        num_children: pass.num_children
      }
    })
  } catch (error) {
    console.error('Lookup room error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to lookup room',
      details: error.message
    }, 500)
  }
})

// Guest: Get tier benefits for linked pass
app.get('/api/guest/tier-benefits', async (c) => {
  const { DB } = c.env
  const propertyId = c.req.header('X-Property-ID') || '1'
  const passReference = c.req.query('pass_reference')
  const language = c.req.query('lang') || c.req.query('language') || 'en'
  
  if (!passReference) {
    return c.json({ error: 'Pass reference required' }, 400)
  }
  
  try {
    // Get pass with tier information
    const pass = await DB.prepare(`
      SELECT 
        p.pass_id,
        p.tier_id,
        p.property_id,
        t.tier_display_name,
        t.tier_color,
        t.tier_icon,
        t.tier_description,
        t.daily_upgrade_price,
        t.alacarte_meals_per_stay,
        t.alacarte_eligible_restaurants,
        t.alacarte_premium_surcharge,
        t.alacarte_privileges_message
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.pass_reference = ? AND p.property_id = ? AND p.pass_status = 'active'
    `).bind(passReference, propertyId).first()
    
    if (!pass) {
      return c.json({ error: 'Pass not found or not active' }, 404)
    }
    
    // Translate tier name and description if needed
    let tierName = pass.tier_display_name
    let tierDescription = pass.tier_description
    
    if (language !== 'en') {
      try {
        if (tierName) {
          const nameResult = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${c.env.OPENAI_API_KEY}`
            },
            body: JSON.stringify({
              model: 'gpt-4o-mini',
              messages: [{
                role: 'system',
                content: `You are a professional translator. Translate the following hotel tier name to ${language}. Keep it concise. Return ONLY the translation, nothing else.`
              }, {
                role: 'user',
                content: tierName
              }],
              temperature: 0.3
            })
          })
          const nameData = await nameResult.json()
          tierName = nameData.choices[0].message.content.trim()
        }
        
        if (tierDescription) {
          const descResult = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${c.env.OPENAI_API_KEY}`
            },
            body: JSON.stringify({
              model: 'gpt-4o-mini',
              messages: [{
                role: 'system',
                content: `You are a professional translator. Translate the following hotel tier description to ${language}. Return ONLY the translation, nothing else.`
              }, {
                role: 'user',
                content: tierDescription
              }],
              temperature: 0.3
            })
          })
          const descData = await descResult.json()
          tierDescription = descData.choices[0].message.content.trim()
        }
      } catch (translateError) {
        console.error('Tier translation error:', translateError)
        // Keep English if translation fails
      }
    }
    
    // Helper function to get default benefit name and description
    function getBenefitDefaults(benefitType) {
      const defaults = {
        'buffet_access': {
          name: 'Buffet Access',
          description: 'Unlimited access to all buffet meals including breakfast, lunch, and dinner'
        },
        'restaurant_access': {
          name: 'Restaurant Access',
          description: 'Access to all à la carte restaurants with your meal plan'
        },
        'a_la_carte': {
          name: 'À La Carte Dining',
          description: 'Enjoy fine dining at our specialty restaurants'
        },
        'room_service': {
          name: 'Room Service',
          description: '24/7 in-room dining service'
        },
        'snacks': {
          name: 'Snacks & Light Bites',
          description: 'Complimentary snacks available throughout the day'
        },
        'alcoholic': {
          name: 'Alcoholic Beverages',
          description: 'Selection of alcoholic drinks including beer, wine, and spirits'
        },
        'non_alcoholic': {
          name: 'Non-Alcoholic Beverages',
          description: 'Unlimited soft drinks, juices, and hot beverages'
        },
        'premium_bar': {
          name: 'Premium Bar Access',
          description: 'Access to premium branded alcoholic beverages'
        },
        'minibar': {
          name: 'Minibar',
          description: 'Complimentary minibar stocked daily with drinks and snacks'
        },
        'pool': {
          name: 'Pool Access',
          description: 'Access to all swimming pools and pool amenities'
        },
        'beach': {
          name: 'Beach Access',
          description: 'Private beach access with complimentary beach chairs and umbrellas'
        },
        'gym': {
          name: 'Fitness Center',
          description: 'Fully equipped gym with modern exercise equipment'
        },
        'spa': {
          name: 'Spa Services',
          description: 'Access to spa facilities and wellness treatments'
        },
        'entertainment': {
          name: 'Entertainment',
          description: 'Daily entertainment programs and live shows'
        },
        'activities': {
          name: 'Activities',
          description: 'Complimentary access to hotel activities and sports'
        },
        'concierge': {
          name: 'Concierge Service',
          description: 'Dedicated concierge assistance for all your needs'
        },
        'late_checkout': {
          name: 'Late Checkout',
          description: 'Extended checkout time based on availability'
        },
        'early_checkin': {
          name: 'Early Check-in',
          description: 'Early check-in privilege based on availability'
        },
        'turndown': {
          name: 'Turndown Service',
          description: 'Evening turndown service with amenities'
        },
        'laundry': {
          name: 'Laundry Service',
          description: 'Complimentary laundry and pressing services'
        },
        'wifi': {
          name: 'WiFi',
          description: 'High-speed internet access throughout the property'
        },
        'parking': {
          name: 'Parking',
          description: 'Complimentary parking for your vehicle'
        }
      }
      
      return defaults[benefitType] || {
        name: benefitType.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
        description: ''
      }
    }
    
    // Get tier benefits
    let benefits = []
    if (pass.tier_id) {
      try {
        const result = await DB.prepare(`
          SELECT 
            tb.*,
            ho.title_en as venue_name,
            ho.offering_type as venue_type
          FROM tier_benefits tb
          LEFT JOIN hotel_offerings ho ON tb.venue_id = ho.offering_id
          WHERE tb.tier_id = ? AND tb.property_id = ? AND tb.is_active = 1
          ORDER BY tb.benefit_category, tb.display_order, tb.benefit_id
        `).bind(pass.tier_id, pass.property_id).all()
        benefits = result.results || []
        
        // Fetch linked venues for each benefit (new many-to-many relationship)
        for (const benefit of benefits) {
          benefit.linked_venues = []
          
          // Try to fetch from benefit_venues junction table
          try {
            const venuesResult = await DB.prepare(`
              SELECT 
                bv.custom_cta_text,
                bv.display_order,
                ho.offering_id,
                ho.title_en as name,
                ho.offering_type as type,
                ho.short_description_en as description,
                ho.images,
                ho.location,
                ho.price,
                ho.currency
              FROM benefit_venues bv
              JOIN hotel_offerings ho ON bv.venue_id = ho.offering_id
              WHERE bv.benefit_id = ? AND ho.status = 'active'
              ORDER BY bv.display_order, bv.benefit_venue_id
            `).bind(benefit.benefit_id).all()
            
            benefit.linked_venues = venuesResult.results || []
          } catch (venuesError) {
            // Table might not exist yet, that's okay
            console.log('benefit_venues table not available, using fallback')
          }
          
          // FALLBACK: If no linked venues but has old venue_id, create a linked venue
          if (benefit.linked_venues.length === 0 && benefit.venue_id) {
            try {
              const singleVenueResult = await DB.prepare(`
                SELECT 
                  offering_id,
                  title_en as name,
                  offering_type as type,
                  short_description_en as description,
                  images,
                  location,
                  price,
                  currency
                FROM hotel_offerings
                WHERE offering_id = ? AND status = 'active'
              `).bind(benefit.venue_id).first()
              
              if (singleVenueResult) {
                benefit.linked_venues = [{
                  ...singleVenueResult,
                  custom_cta_text: benefit.venue_cta_text || 'View Details',
                  display_order: 1
                }]
                console.log('✅ Fallback venue loaded for benefit:', benefit.benefit_title, '→', singleVenueResult.name)
              } else {
                console.log('⚠️ Venue not found for venue_id:', benefit.venue_id)
              }
            } catch (singleVenueError) {
              console.log('❌ Could not fetch single venue fallback:', singleVenueError)
            }
          }
          
          // ALWAYS use benefit_title from database as primary source
          benefit.display_name = benefit.benefit_title || benefit.venue_name || benefit.benefit_type
          
          // ALWAYS use benefit_description from database as primary source
          benefit.display_description = benefit.benefit_description || benefit.description || ''
          
          // Only use defaults if BOTH title and description are missing (shouldn't happen)
          if (!benefit.display_name || benefit.display_name === benefit.benefit_type) {
            const defaults = getBenefitDefaults(benefit.benefit_type)
            if (!benefit.display_name) {
              benefit.display_name = defaults.name
            }
            if (!benefit.display_description) {
              benefit.display_description = defaults.description
            }
          }
        }
      } catch (joinError) {
        // Fallback without join if hotel_offerings doesn't exist
        const result = await DB.prepare(`
          SELECT tb.*
          FROM tier_benefits tb
          WHERE tb.tier_id = ? AND tb.property_id = ? AND tb.is_active = 1
          ORDER BY tb.benefit_category, tb.display_order, tb.benefit_id
        `).bind(pass.tier_id, pass.property_id).all()
        benefits = result.results || []
        
        // Add display names and descriptions from database
        for (const benefit of benefits) {
          // ALWAYS use benefit_title from database as primary source
          benefit.display_name = benefit.benefit_title || benefit.benefit_type
          benefit.display_description = benefit.benefit_description || ''
          
          // Only use defaults if title is missing
          if (!benefit.display_name) {
            const defaults = getBenefitDefaults(benefit.benefit_type)
            benefit.display_name = defaults.name
            if (!benefit.display_description) {
              benefit.display_description = defaults.description
            }
          }
        }
      }
    }
    
    // Translate benefits if not English
    if (language !== 'en' && benefits.length > 0) {
      for (const benefit of benefits) {
        try {
          // Translate display_name
          if (benefit.display_name) {
            const nameResult = await fetch('https://api.openai.com/v1/chat/completions', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${c.env.OPENAI_API_KEY}`
              },
              body: JSON.stringify({
                model: 'gpt-4o-mini',
                messages: [{
                  role: 'system',
                  content: `You are a professional translator. Translate the following hotel benefit name to ${language}. Keep it concise (1-4 words). Return ONLY the translation, nothing else.`
                }, {
                  role: 'user',
                  content: benefit.display_name
                }],
                temperature: 0.3
              })
            })
            const nameData = await nameResult.json()
            benefit.display_name = nameData.choices[0].message.content.trim()
          }
          
          // Translate display_description
          if (benefit.display_description) {
            const descResult = await fetch('https://api.openai.com/v1/chat/completions', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${c.env.OPENAI_API_KEY}`
              },
              body: JSON.stringify({
                model: 'gpt-4o-mini',
                messages: [{
                  role: 'system',
                  content: `You are a professional translator. Translate the following hotel benefit description to ${language}. Return ONLY the translation, nothing else.`
                }, {
                  role: 'user',
                  content: benefit.display_description
                }],
                temperature: 0.3
              })
            })
            const descData = await descResult.json()
            benefit.display_description = descData.choices[0].message.content.trim()
          }
        } catch (translateError) {
          console.error('Benefit translation error:', translateError)
          // Keep English if translation fails
        }
      }
    }
    
    // Deduplicate benefits by benefit_id (primary key)
    // This ensures each unique benefit is shown once
    const seenBenefits = new Set()
    const uniqueBenefits = []
    
    for (const benefit of benefits) {
      // Use benefit_id as the unique key since it's the primary key
      const key = benefit.benefit_id
      if (!seenBenefits.has(key)) {
        seenBenefits.add(key)
        uniqueBenefits.push(benefit)
      }
    }
    
    // Group benefits by category
    const groupedBenefits = {
      dining: [],
      drinks: [],
      recreation: [],
      services: [],
      amenities: []
    }
    
    uniqueBenefits.forEach(benefit => {
      const category = benefit.benefit_category || 'amenities'
      if (groupedBenefits[category]) {
        groupedBenefits[category].push(benefit)
      }
    })
    
    return c.json({
      success: true,
      tier: {
        name: tierName,
        color: pass.tier_color,
        icon: pass.tier_icon,
        description: tierDescription,
        upgrade_price: pass.daily_upgrade_price,
        alacarte_meals_per_stay: pass.alacarte_meals_per_stay,
        alacarte_eligible_restaurants: pass.alacarte_eligible_restaurants,
        alacarte_premium_surcharge: pass.alacarte_premium_surcharge
      },
      benefits: groupedBenefits,
      total_benefits: uniqueBenefits.length
    })
  } catch (error) {
    console.error('Get tier benefits error:', error)
    return c.json({ error: 'Failed to load tier benefits' }, 500)
  }
})

