// Get ALL guest bookings (restaurant, activities, beach, spa) - Direct from source tables
app.get('/api/guest/bookings/:pass_reference', async (c) => {
  const { DB } = c.env
  const pass_reference = c.req.param('pass_reference')
  
  try {
    // Get guest from digital pass
    const pass = await DB.prepare(`
      SELECT pass_id, property_id, primary_guest_name, guest_email, room_number
      FROM digital_passes 
      WHERE pass_reference = ?
    `).bind(pass_reference).first()
    
    if (!pass) {
      return c.json({ error: 'Pass not found' }, 404)
    }
    
    // Try to find guest by email
    let guest = null
    if (pass.guest_email) {
      guest = await DB.prepare(`
        SELECT guest_id FROM guests WHERE email = ?
      `).bind(pass.guest_email).first()
    }
    
    const guestId = guest?.guest_id
    const allBookings = []
    
    // 1. Fetch Restaurant Reservations from table_reservations (by guest_id OR room_number)
    if (guestId || pass.room_number) {
      let query = `
        SELECT 
          tr.reservation_id as id,
          'restaurant' as type,
          tr.reservation_date as date,
          ds.session_time as start_time,
          NULL as end_time,
          COALESCE(ho.title_en, 'Restaurant Reservation') as title,
          COALESCE(ho.location, 'Resort Dining') as location,
          tr.status,
          tr.num_guests,
          'RES' || SUBSTR('000000' || tr.reservation_id, -6) as reference,
          ho.offering_id as offering_id
        FROM table_reservations tr
        LEFT JOIN dining_sessions ds ON tr.session_id = ds.session_id
        LEFT JOIN restaurant_tables rt ON tr.table_id = rt.table_id
        LEFT JOIN hotel_offerings ho ON rt.offering_id = ho.offering_id
        WHERE (tr.guest_id = ? OR tr.room_number = ?) AND tr.status != 'cancelled'
        ORDER BY tr.reservation_date ASC, ds.session_time ASC
      `
      
      const restaurants = await DB.prepare(query).bind(guestId || null, pass.room_number || null).all()
      
      allBookings.push(...restaurants.results)
    }
    
    // 1b. Fetch A La Carte Vouchers (bookings made through OnePass system)
    if (pass.pass_id) {
      try {
        const vouchers = await DB.prepare(`
          SELECT 
            av.voucher_id as id,
            'restaurant' as type,
            av.reservation_date as date,
            av.reservation_time as start_time,
            NULL as end_time,
            COALESCE(ho.title_en, 'A La Carte Dining') as title,
            COALESCE(ho.location, 'Resort Dining') as location,
            av.status,
            av.party_size as num_guests,
            av.voucher_code as reference,
            av.restaurant_id as offering_id
          FROM alacarte_vouchers av
          LEFT JOIN hotel_offerings ho ON av.restaurant_id = ho.offering_id
          WHERE av.pass_id = ? AND av.status IN ('confirmed', 'used')
          ORDER BY av.reservation_date ASC, av.reservation_time ASC
        `).bind(pass.pass_id).all()
        
        console.log('A la carte vouchers found:', vouchers.results.length, 'for pass_id:', pass.pass_id)
        allBookings.push(...vouchers.results)
      } catch (e) {
        console.log('A la carte vouchers query error:', e.message)
      }
    }
    
    // 2. Fetch Activity Bookings (if exist)
    if (guestId) {
      try {
        const activities = await DB.prepare(`
          SELECT 
            b.booking_id as id,
            'activity' as type,
            b.activity_date as date,
            b.activity_time as start_time,
            NULL as end_time,
            a.activity_name as title,
            COALESCE(a.location, 'Resort Activity') as location,
            b.booking_status as status,
            b.num_participants as num_guests,
            b.booking_reference as reference
          FROM bookings b
          LEFT JOIN activities a ON b.activity_id = a.activity_id
          WHERE b.guest_id = ? AND b.booking_status = 'confirmed'
          ORDER BY b.activity_date ASC, b.activity_time ASC
        `).bind(guestId).all()
        
        allBookings.push(...activities.results)
      } catch (e) {
        // Table might not exist, skip
      }
    }
    
    // 3. Fetch Beach Bookings (by guest_id OR room_number)
    if (guestId || pass.room_number) {
      try {
        const beach = await DB.prepare(`
          SELECT 
            bb.beach_booking_id as id,
            'beach' as type,
            bb.booking_date as date,
            COALESCE(bb.start_time, '08:00') as start_time,
            bb.end_time,
            'Beach Spot' as title,
            COALESCE('Spot ' || bs.spot_number, 'Beach Area') as location,
            bb.booking_status as status,
            bb.num_guests,
            bb.booking_reference as reference,
            NULL as offering_id
          FROM beach_bookings bb
          LEFT JOIN beach_spots bs ON bb.spot_id = bs.spot_id
          WHERE (bb.guest_id = ? OR bb.guest_room_number = ?) AND bb.booking_status != 'cancelled'
          ORDER BY bb.booking_date ASC
        `).bind(guestId || null, pass.room_number || null).all()
        
        console.log('Beach bookings found:', beach.results.length, 'for guest_id:', guestId, 'room:', pass.room_number)
        allBookings.push(...beach.results)
      } catch (e) {
        // Table might not exist, skip
        console.log('Beach bookings table error:', e.message)
      }
    }
    
    return c.json({
      success: true,
      bookings: allBookings,
      guest: {
        name: pass.primary_guest_name,
        email: pass.guest_email,
        room: pass.room_number
      },
      debug: {
        guest_id: guestId,
        room_number: pass.room_number,
        total_bookings: allBookings.length
      }
    })
  } catch (error) {
    console.error('Get bookings error:', error)
    return c.json({ error: 'Failed to fetch bookings', details: error.message }, 500)
  }
})

// Get guest's complete timeline for their stay
app.get('/api/guest/my-week/:pass_reference', async (c) => {
  const { DB } = c.env
  const pass_reference = c.req.param('pass_reference')
  
  try {
    // Get guest info from digital_passes
    const guest = await DB.prepare(`
      SELECT 
        p.pass_id as guest_id,
        p.property_id,
        p.pass_reference,
        p.primary_guest_name as name,
        p.guest_email as email,
        p.room_number,
        p.valid_from as check_in,
        p.valid_until as check_out,
        JULIANDAY(p.valid_until) - JULIANDAY(p.valid_from) as nights,
        t.tier_display_name as tier_name
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.pass_reference = ?
    `).bind(pass_reference).first()
    
    if (!guest) {
      return c.json({ error: 'Guest not found' }, 404)
    }
    
    // Get or create stay plan
    let plan = await DB.prepare(`
      SELECT * FROM guest_stay_plans 
      WHERE guest_id = ? AND property_id = ?
    `).bind(guest.guest_id, guest.property_id).first()
    
    if (!plan && guest.check_in && guest.check_out) {
      // Create new plan
      const result = await DB.prepare(`
        INSERT INTO guest_stay_plans (guest_id, property_id, checkin_date, checkout_date, total_nights)
        VALUES (?, ?, ?, ?, ?)
      `).bind(guest.guest_id, guest.property_id, guest.check_in, guest.check_out, Math.round(guest.nights)).run()
      
      plan = { 
        plan_id: result.meta.last_row_id, 
        guest_id: guest.guest_id,
        property_id: guest.property_id,
        checkin_date: guest.check_in,
        checkout_date: guest.check_out,
        total_nights: Math.round(guest.nights)
      }
      
      // Auto-import ALL existing bookings (activities, restaurants, beach, events)
      
      // 1. Activity Bookings
      const activityBookings = await DB.prepare(`
        SELECT 
          b.booking_id,
          b.activity_date as booking_date,
          b.activity_time as booking_time,
          b.duration_minutes,
          a.activity_name as title,
          a.activity_description as description,
          a.activity_type,
          'activity' as booking_type
        FROM bookings b
        LEFT JOIN activities a ON b.activity_id = a.activity_id
        WHERE b.guest_id = ? AND b.booking_status = 'confirmed'
      `).bind(guest.guest_id).all()
      
      for (const booking of activityBookings.results) {
        await DB.prepare(`
          INSERT INTO timeline_items 
          (plan_id, item_type, reference_id, item_date, start_time, end_time, title, location, icon, color, status)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          plan.plan_id,
          'activity',
          booking.booking_id,
          booking.booking_date,
          booking.booking_time || '09:00',
          null,
          booking.title || 'Activity',
          'Resort Activity',
          '🎯',
          'blue',
          'confirmed'
        ).run()
      }
      
      // 2. Restaurant Reservations
      const restaurantBookings = await DB.prepare(`
        SELECT 
          tr.reservation_id,
          tr.reservation_date,
          tr.reservation_time,
          ho.title_en as restaurant_name,
          tr.party_size,
          'restaurant' as booking_type
        FROM table_reservations tr
        LEFT JOIN hotel_offerings ho ON tr.offering_id = ho.offering_id
        WHERE (tr.guest_id = ? OR tr.room_number = ?) AND tr.status = 'confirmed'
      `).bind(guest.guest_id, guest.room_number).all()
      
      for (const booking of restaurantBookings.results) {
        await DB.prepare(`
          INSERT INTO timeline_items 
          (plan_id, item_type, reference_id, item_date, start_time, end_time, title, location, icon, color, status)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          plan.plan_id,
          'restaurant',
          booking.reservation_id,
          booking.reservation_date,
          booking.reservation_time,
          null,
          booking.restaurant_name || 'Restaurant',
          'Resort Dining',
          '🍽️',
          'orange',
          'confirmed'
        ).run()
      }
      
      // 3. Beach Bookings
      const beachBookings = await DB.prepare(`
        SELECT 
          bb.booking_id,
          bb.booking_date,
          bb.booking_time,
          bb.zone_name,
          bb.spot_number,
          'beach' as booking_type
        FROM beach_bookings bb
        WHERE (bb.guest_id = ? OR bb.guest_room_number = ?) AND bb.status = 'confirmed'
      `).bind(guest.guest_id, guest.room_number).all()
      
      for (const booking of beachBookings.results) {
        await DB.prepare(`
          INSERT INTO timeline_items 
          (plan_id, item_type, reference_id, item_date, start_time, end_time, title, location, icon, color, status)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          plan.plan_id,
          'beach',
          booking.booking_id,
          booking.booking_date,
          booking.booking_time || '08:00',
          null,
          `Beach - ${booking.zone_name}`,
          `Spot ${booking.spot_number}`,
          '🏖️',
          'cyan',
          'confirmed'
        ).run()
      }
      
      // 4. Hotel Offering Bookings (Events, Spa, etc.)
      const offeringBookings = await DB.prepare(`
        SELECT 
          ob.booking_id,
          ob.booking_date,
          ob.start_time,
          ob.end_time,
          ho.title_en,
          ho.offering_type,
          'offering' as booking_type
        FROM offering_bookings ob
        LEFT JOIN hotel_offerings ho ON ob.offering_id = ho.offering_id
        WHERE ob.guest_id = ? AND ob.status = 'confirmed'
      `).bind(guest.guest_id).all()
      
      for (const booking of offeringBookings.results) {
        const icon = booking.offering_type === 'event' ? '🎉' : 
                     booking.offering_type === 'spa' ? '💆' : 
                     booking.offering_type === 'service' ? '🛎️' : '✨'
        const color = booking.offering_type === 'event' ? 'purple' : 
                      booking.offering_type === 'spa' ? 'pink' : 
                      'green'
        
        await DB.prepare(`
          INSERT INTO timeline_items 
          (plan_id, item_type, reference_id, item_date, start_time, end_time, title, location, icon, color, status)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
          plan.plan_id,
          booking.offering_type || 'event',
          booking.booking_id,
          booking.booking_date,
          booking.start_time || '10:00',
          booking.end_time,
          booking.title_en || 'Event',
          'Resort',
          icon,
          color,
          'confirmed'
        ).run()
      }
    }
    
    // Get all timeline items
    const timelineItems = await DB.prepare(`
      SELECT * FROM timeline_items 
      WHERE plan_id = ?
      ORDER BY item_date ASC, start_time ASC
    `).bind(plan.plan_id).all()
    
    // Get smart suggestions
    const suggestions = await DB.prepare(`
      SELECT ts.*, ho.title_en, ho.full_description_en as description, ho.offering_type, ho.images, ho.price, ho.currency
      FROM timeline_suggestions ts
      JOIN hotel_offerings ho ON ts.offering_id = ho.offering_id
      WHERE ts.plan_id = ? AND ts.is_dismissed = 0 AND ts.is_accepted = 0
      ORDER BY ts.relevance_score DESC
      LIMIT 10
    `).bind(plan.plan_id).all()
    
    // Generate array of days for the stay
    const days = []
    if (plan) {
      const checkin = new Date(plan.checkin_date)
      const checkout = new Date(plan.checkout_date)
      const nights = Math.round((checkout - checkin) / (1000 * 60 * 60 * 24))
      
      for (let i = 0; i < nights; i++) {
        const date = new Date(checkin)
        date.setDate(date.getDate() + i)
        const dateStr = date.toISOString().split('T')[0]
        
        days.push({
          day_number: i + 1,
          date: dateStr,
          day_name: date.toLocaleDateString('en-US', { weekday: 'short' }),
          is_past: dateStr < new Date().toISOString().split('T')[0],
          is_today: dateStr === new Date().toISOString().split('T')[0],
          items: timelineItems.results.filter(item => item.item_date === dateStr)
        })
      }
    }
    
    return c.json({
      success: true,
      plan_id: plan?.plan_id,  // Add plan_id for frontend use
      stay: {
        checkin: plan?.checkin_date,
        checkout: plan?.checkout_date,
        nights: plan?.total_nights
      },
      days: days,
      timeline_items: timelineItems.results,
      suggestions: suggestions.results,
      guest: {
        name: guest.name,
        room: guest.room_number,
        tier: guest.tier_name || 'Standard'
      }
    })
    
  } catch (error) {
    console.error('My Perfect Week error:', error)
    return c.json({ error: 'Failed to load timeline' }, 500)
  }
})

