// Generate smart suggestions for a guest
app.post('/api/guest/my-week/generate-suggestions', async (c) => {
  const { DB } = c.env
  const body = await c.req.json()
  const { pass_reference } = body
  
  try {
    // Get guest and plan info
    const guest = await DB.prepare(`
      SELECT g.*, gsp.plan_id, gsp.checkin_date, gsp.checkout_date, gsp.total_nights
      FROM guests g
      LEFT JOIN guest_stay_plans gsp ON g.guest_id = gsp.guest_id
      WHERE g.pass_reference = ?
    `).bind(pass_reference).first()
    
    if (!guest || !guest.plan_id) {
      return c.json({ error: 'Guest plan not found' }, 404)
    }
    
    // Get tier benefits
    const tierBenefits = await DB.prepare(`
      SELECT DISTINCT tb.benefit_id, ho.offering_id, ho.title_en, ho.description_en, ho.offering_type, ho.price
      FROM tier_benefits tb
      LEFT JOIN benefit_venues bv ON tb.benefit_id = bv.benefit_id
      LEFT JOIN hotel_offerings ho ON bv.venue_id = ho.offering_id
      WHERE tb.tier_id = ? AND ho.status = 'active'
    `).bind(guest.tier_id).all()
    
    // Get already booked items
    const bookedOfferings = await DB.prepare(`
      SELECT DISTINCT reference_id FROM timeline_items WHERE plan_id = ? AND item_type IN ('booking', 'activity')
    `).bind(guest.plan_id).all()
    const bookedIds = bookedOfferings.results.map(b => b.reference_id)
    
    // Generate suggestions
    const suggestions = []
    
    // 1. Tier-included activities not yet tried
    for (const benefit of tierBenefits.results) {
      if (benefit.offering_id && !bookedIds.includes(benefit.offering_id)) {
        const checkin = new Date(guest.checkin_date)
        checkin.setDate(checkin.getDate() + 1) // Suggest for day 2
        
        let suggestedTime = '10:00' // Default for activities
        
        // For restaurants, get actual available time from dining sessions
        if (benefit.offering_type === 'restaurant') {
          const sessions = await DB.prepare(`
            SELECT session_time FROM dining_sessions 
            WHERE offering_id = ? AND is_active = 1
            ORDER BY session_time ASC
            LIMIT 1
          `).bind(benefit.offering_id).first()
          
          if (sessions && sessions.session_time) {
            suggestedTime = sessions.session_time
          } else {
            // Skip this restaurant if no sessions configured
            continue
          }
        }
        
        suggestions.push({
          plan_id: guest.plan_id,
          offering_id: benefit.offering_id,
          suggested_date: checkin.toISOString().split('T')[0],
          suggested_time: suggestedTime,
          reason_code: 'tier_included',
          reason_text: `✨ Included in your ${guest.tier_name || 'tier'} (FREE)`,
          relevance_score: 90
        })
      }
    }
    
    // 2. Popular activities (if we have them)
    const popularActivities = await DB.prepare(`
      SELECT ho.offering_id, ho.title_en, COUNT(*) as booking_count
      FROM bookings b
      JOIN hotel_offerings ho ON b.offering_id = ho.offering_id
      WHERE ho.property_id = ? AND ho.status = 'active' AND ho.offering_type = 'activity'
      GROUP BY ho.offering_id
      ORDER BY booking_count DESC
      LIMIT 5
    `).bind(guest.property_id).all()
    
    for (const activity of popularActivities.results) {
      if (!bookedIds.includes(activity.offering_id)) {
        const checkin = new Date(guest.checkin_date)
        checkin.setDate(checkin.getDate() + 2) // Suggest for day 3
        
        let suggestedTime = '14:00' // Default for activities
        
        // For restaurants, get actual available time from dining sessions
        const offeringType = await DB.prepare(`
          SELECT offering_type FROM hotel_offerings WHERE offering_id = ?
        `).bind(activity.offering_id).first()
        
        if (offeringType && offeringType.offering_type === 'restaurant') {
          const sessions = await DB.prepare(`
            SELECT session_time FROM dining_sessions 
            WHERE offering_id = ? AND is_active = 1
            ORDER BY session_time ASC
            LIMIT 1
          `).bind(activity.offering_id).first()
          
          if (sessions && sessions.session_time) {
            suggestedTime = sessions.session_time
          } else {
            // Skip this restaurant if no sessions configured
            continue
          }
        }
        
        suggestions.push({
          plan_id: guest.plan_id,
          offering_id: activity.offering_id,
          suggested_date: checkin.toISOString().split('T')[0],
          suggested_time: suggestedTime,
          reason_code: 'popular',
          reason_text: '⭐ Popular with other guests',
          relevance_score: 75
        })
      }
    }
    
    // Insert suggestions into database
    for (const suggestion of suggestions.slice(0, 10)) { // Limit to 10
      await DB.prepare(`
        INSERT INTO timeline_suggestions 
        (plan_id, offering_id, suggested_date, suggested_time, reason_code, reason_text, relevance_score)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(
        suggestion.plan_id,
        suggestion.offering_id,
        suggestion.suggested_date,
        suggestion.suggested_time,
        suggestion.reason_code,
        suggestion.reason_text,
        suggestion.relevance_score
      ).run()
    }
    
    return c.json({ 
      success: true, 
      suggestions_count: suggestions.length,
      message: `Generated ${suggestions.length} personalized suggestions!` 
    })
    
  } catch (error) {
    console.error('Generate suggestions error:', error)
    return c.json({ error: 'Failed to generate suggestions' }, 500)
  }
})

app.get('/api/guest/pass/:pass_reference', async (c) => {
  const { DB } = c.env
  const pass_reference = c.req.param('pass_reference')
  const token = c.req.query('token')
  
  if (!token) {
    return c.json({ error: 'Access token required' }, 401)
  }
  
  try {
    // Get pass with token verification
    const pass = await DB.prepare(`
      SELECT 
        p.*,
        t.tier_display_name as tier_name,
        t.tier_color,
        t.tier_icon
      FROM digital_passes p
      LEFT JOIN all_inclusive_tiers t ON p.tier_id = t.tier_id
      WHERE p.pass_reference = ? AND p.guest_access_token = ?
    `).bind(pass_reference, token).first()
    
    if (!pass) {
      return c.json({ error: 'Invalid pass or access token' }, 404)
    }
    
    return c.json({
      pass_reference: pass.pass_reference,
      primary_guest_name: pass.primary_guest_name,
      guest_email: pass.guest_email,
      room_number: pass.room_number,
      tier_name: pass.tier_name,
      tier_color: pass.tier_color,
      tier_icon: pass.tier_icon,
      valid_from: pass.valid_from,
      valid_until: pass.valid_until,
      pass_status: pass.pass_status,
      verification_preference: pass.verification_preference || 'qr',
      face_enrolled: !!pass.face_embedding,
      wallet_pass_generated: !!pass.wallet_pass_generated
    })
  } catch (error) {
    console.error('Get guest pass error:', error)
    return c.json({ error: 'Failed to load pass' }, 500)
  }
})

// Guest: Update verification preference
app.post('/api/guest/pass/:pass_reference/preference', async (c) => {
  const { DB } = c.env
  const pass_reference = c.req.param('pass_reference')
  const { token, preference } = await c.req.json()
  
  if (!token) {
    return c.json({ error: 'Access token required' }, 401)
  }
  
  if (!['qr', 'face', 'wallet', 'both'].includes(preference)) {
    return c.json({ error: 'Invalid preference' }, 400)
  }
  
  try {
    // Verify token
    const pass = await DB.prepare(`
      SELECT pass_id, property_id, verification_preference 
      FROM digital_passes 
      WHERE pass_reference = ? AND guest_access_token = ?
    `).bind(pass_reference, token).first()
    
    if (!pass) {
      return c.json({ error: 'Invalid pass or access token' }, 404)
    }
    
    const oldPreference = pass.verification_preference || 'qr'
    
    // Update preference
    await DB.prepare(`
      UPDATE digital_passes
      SET verification_preference = ?,
          guest_portal_accessed_at = CURRENT_TIMESTAMP
      WHERE pass_reference = ? AND guest_access_token = ?
    `).bind(preference, pass_reference, token).run()
    
    // Log the change
    await DB.prepare(`
      INSERT INTO guest_consent_changes (
        pass_id, property_id, old_preference, new_preference,
        change_reason, changed_by, ip_address, user_agent
      ) VALUES (?, ?, ?, ?, 'guest_switched', 'guest', ?, ?)
    `).bind(
      pass.pass_id,
      pass.property_id,
      oldPreference,
      preference,
      c.req.header('CF-Connecting-IP') || 'unknown',
      c.req.header('User-Agent') || 'unknown'
    ).run()
    
    return c.json({ 
      success: true,
      message: 'Preference updated successfully'
    })
  } catch (error) {
    console.error('Update preference error:', error)
    return c.json({ error: 'Failed to update preference' }, 500)
  }
})

// Guest: Withdraw biometric consent (self-service, no staff needed)
app.post('/api/guest/pass/:pass_reference/withdraw-consent', async (c) => {
  const { DB } = c.env
  const pass_reference = c.req.param('pass_reference')
  const { token } = await c.req.json()
  
  if (!token) {
    return c.json({ error: 'Access token required' }, 401)
  }
  
  try {
    // Verify token and get pass details
    const pass = await DB.prepare(`
      SELECT pass_id, property_id, primary_guest_name, face_embedding, face_photo_url
      FROM digital_passes 
      WHERE pass_reference = ? AND guest_access_token = ?
    `).bind(pass_reference, token).first()
    
    if (!pass) {
      return c.json({ error: 'Invalid pass or access token' }, 404)
    }
    
    const hadBiometricData = !!(pass.face_embedding || pass.face_photo_url)
    
    // IMMEDIATE deletion of ALL biometric data
    await DB.prepare(`
      UPDATE digital_passes
      SET face_embedding = NULL,
          face_photo_url = NULL,
          face_enrolled_at = NULL,
          face_embedding_version = NULL,
          biometric_consent_given = 0,
          biometric_consent_withdrawn = 1,
          biometric_consent_withdrawn_at = CURRENT_TIMESTAMP,
          verification_preference = 'qr',
          scheduled_deletion_date = NULL,
          guest_portal_accessed_at = CURRENT_TIMESTAMP
      WHERE pass_reference = ? AND guest_access_token = ?
    `).bind(pass_reference, token).run()
    
    // Log the withdrawal
    await DB.prepare(`
      INSERT INTO biometric_audit_log (
        pass_id, property_id, action_type, action_details,
        performed_by, ip_address, user_agent
      ) VALUES (?, ?, 'CONSENT_WITHDRAWN_SELF_SERVICE', ?, 'guest_self_service', ?, ?)
    `).bind(
      pass.pass_id,
      pass.property_id,
      JSON.stringify({
        guest_name: pass.primary_guest_name,
        data_deleted: hadBiometricData,
        withdrawal_method: 'guest_self_service_portal',
        timestamp: new Date().toISOString()
      }),
      c.req.header('CF-Connecting-IP') || 'unknown',
      c.req.header('User-Agent') || 'unknown'
    ).run()
    
    // Log consent change
    await DB.prepare(`
      INSERT INTO guest_consent_changes (
        pass_id, property_id, old_preference, new_preference,
        change_reason, changed_by, ip_address, user_agent
      ) VALUES (?, ?, 'face', 'qr', 'consent_withdrawn', 'guest', ?, ?)
    `).bind(
      pass.pass_id,
      pass.property_id,
      c.req.header('CF-Connecting-IP') || 'unknown',
      c.req.header('User-Agent') || 'unknown'
    ).run()
    
    return c.json({ 
      success: true,
      message: 'Biometric consent withdrawn successfully',
      data_deleted: hadBiometricData,
      fallback_method: 'qr'
    })
  } catch (error) {
    console.error('Guest withdraw consent error:', error)
    return c.json({ error: 'Failed to withdraw consent' }, 500)
  }
})

