// Admin: Delete form
app.delete('/api/admin/feedback/forms/:form_id', async (c) => {
  const { DB } = c.env
  const { form_id } = c.req.param()
  
  try {
    // 🛡️ PROTECTION: Check if this is a mood check form
    const form = await DB.prepare(`
      SELECT form_type, form_name FROM feedback_forms WHERE form_id = ?
    `).bind(form_id).first()
    
    if (!form) {
      return c.json({ error: 'Form not found' }, 404)
    }
    
    // 🚫 PREVENT DELETION of mood check forms
    if (form.form_type === 'mood_check') {
      return c.json({ 
        error: 'Mood Check forms cannot be deleted',
        message: 'Mood Check forms are system forms and cannot be deleted. You can deactivate them instead.'
      }, 403)
    }
    
    // Delete in correct order to respect foreign key constraints
    // 1. Delete all answers for submissions of this form
    await DB.prepare(`
      DELETE FROM feedback_answers 
      WHERE submission_id IN (
        SELECT submission_id FROM feedback_submissions WHERE form_id = ?
      )
    `).bind(form_id).run()
    
    // 2. Delete all submissions for this form
    await DB.prepare(`
      DELETE FROM feedback_submissions WHERE form_id = ?
    `).bind(form_id).run()
    
    // 3. Delete all questions for this form (should cascade, but doing explicitly)
    await DB.prepare(`
      DELETE FROM feedback_questions WHERE form_id = ?
    `).bind(form_id).run()
    
    // 4. Finally delete the form itself
    await DB.prepare(`
      DELETE FROM feedback_forms WHERE form_id = ?
    `).bind(form_id).run()
    
    console.log(`✅ Successfully deleted feedback form ${form_id} (${form.form_name}) and all related data`)
    
    return c.json({ success: true })
  } catch (error) {
    console.error('Delete form error:', error)
    return c.json({ error: 'Failed to delete form: ' + error.message }, 500)
  }
})

