        window.toggleTierDetails = function() {
          const panel = document.getElementById('tierDetailsPanel');
          const icon = document.getElementById('tierToggleIcon');
          const text = document.getElementById('tierToggleText');
          
          if (panel && icon) {
            const isHidden = panel.classList.contains('hidden');
            panel.classList.toggle('hidden');
            icon.classList.toggle('rotate-180');
            
            // Update button text
            if (text) {
              text.textContent = isHidden ? 'Hide Details' : 'View Details';
            }
            
            // If opening the panel AND we have restaurant cards, inject them
            if (isHidden && window.alacarteRestaurantCards) {
              const alacarteSection = document.getElementById('alacarteRestaurantsSection');
              const alacarteList = document.getElementById('alacarteRestaurantsList');
              
              if (alacarteSection && alacarteList) {
                alacarteList.innerHTML = window.alacarteRestaurantCards;
                alacarteSection.classList.remove('hidden');
              }
            }
          }
        }
        
        // Open chatbot and optionally ask about benefits
        window.openChatbotWithBenefitsPrompt = function() {
          // Open chatbot window
          const chatWindow = document.getElementById('chatWindow');
          if (chatWindow) {
            chatWindow.classList.remove('hidden');
            
            // Focus on input
            setTimeout(() => {
              const chatInput = document.getElementById('chatInput');
              if (chatInput) {
                chatInput.focus();
                // Optionally pre-fill a helpful prompt
                chatInput.placeholder = "Try asking: 'What can I eat with my tier?' or 'Where can I dine?'";
              }
            }, 100);
          }
        }
        
