      // ========== FEEDBACK MANAGEMENT FUNCTIONS ==========
      
      let currentFormId = null;
      let formQuestions = [];
      let currentQuestionIndex = 0;

      // Load daily mood check statistics
      async function loadMoodStats() {
        try {
          const response = await fetch('/api/admin/feedback/mood-stats/' + propertyId);
          const data = await response.json();
          
          if (data.success && data.today) {
            const today = data.today;
            
            // Update overall mood display
            document.getElementById('topMoodEmoji').textContent = today.top_mood;
            document.getElementById('topMoodLabel').textContent = today.top_mood_label;
            document.getElementById('sentimentScoreDisplay').textContent = today.sentiment_score;
            
            // Update counts
            document.getElementById('happyCount').textContent = today.happy;
            document.getElementById('okayCount').textContent = today.okay;
            document.getElementById('unhappyCount').textContent = today.unhappy;
            document.getElementById('totalMoodChecks').textContent = today.total;
            document.getElementById('urgentMoodCount').textContent = today.urgent_count;
            
            // Update percentages and progress bars
            document.getElementById('happyPercent').textContent = today.happy_percent + '%';
            document.getElementById('happyBar').style.width = today.happy_percent + '%';
            
            document.getElementById('okayPercent').textContent = today.okay_percent + '%';
            document.getElementById('okayBar').style.width = today.okay_percent + '%';
            
            document.getElementById('unhappyPercent').textContent = today.unhappy_percent + '%';
            document.getElementById('unhappyBar').style.width = today.unhappy_percent + '%';
            
            // Update timestamp
            const now = new Date();
            const timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
            document.getElementById('moodLastUpdated').textContent = timeStr;
            
            // Show mood check section
            document.getElementById('moodCheckSection').style.display = 'block';
          } else {
            // No mood check data yet - show empty state
            document.getElementById('moodCheckSection').style.display = 'block';
          }
        } catch (error) {
          console.error('Load mood stats error:', error);
          // Don't show error to user - just hide the section if data unavailable
          document.getElementById('moodCheckSection').style.display = 'none';
        }
      }
      
      // Load detailed mood checks list
      async function loadMoodChecks() {
        try {
          const detailsResponse = await fetch('/api/admin/feedback/mood-checks/' + propertyId);
          const detailsData = await detailsResponse.json();
          
          if (detailsData.success && detailsData.mood_checks && detailsData.mood_checks.length > 0) {
            const detailsList = document.getElementById('moodCheckDetailsList');
            let html = '';
            detailsData.mood_checks.forEach(check => {
              const bgClass = check.mood_score === 3 ? 'bg-green-100 text-green-800' :
                              check.mood_score === 2 ? 'bg-blue-100 text-blue-800' :
                              'bg-red-100 text-red-800';
              const moodLabel = check.mood_score === 3 ? 'Happy' :
                               check.mood_score === 2 ? 'Okay' : 'Unhappy';
              const timeStr = new Date(check.created_at).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
              
              html += '<div class="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-all">';
              html += '  <div class="flex items-center gap-3">';
              html += '    <span class="text-3xl">' + check.mood_emoji + '</span>';
              html += '    <div>';
              html += '      <p class="font-semibold text-gray-800">' + (check.guest_name || 'Guest') + '</p>';
              html += '      <p class="text-sm text-gray-600">';
              html += '        <i class="fas fa-door-open mr-1"></i>Room ' + (check.room_number || 'N/A');
              html += '        <span class="mx-2">•</span>';
              html += '        <i class="fas fa-calendar-day mr-1"></i>Day ' + (check.stay_day || '?') + ' of stay';
              html += '      </p>';
              html += '    </div>';
              html += '  </div>';
              html += '  <div class="text-right">';
              html += '    <span class="inline-block px-3 py-1 rounded-full text-xs font-semibold ' + bgClass + '">';
              html += moodLabel;
              html += '    </span>';
              html += '    <p class="text-xs text-gray-500 mt-1">' + timeStr + '</p>';
              html += '  </div>';
              html += '</div>';
            });
            detailsList.innerHTML = html;
          } else {
            document.getElementById('moodCheckDetailsList').innerHTML = '<p class="text-center text-gray-500 py-4 text-sm">No mood checks yet today</p>';
          }
        } catch (error) {
          console.error('Load mood checks error:', error);
          document.getElementById('moodCheckDetailsList').innerHTML = '<p class="text-center text-red-500 py-4 text-sm">Unable to load mood checks</p>';
        }
      }
      
      // Refresh mood stats
