        html += '<button type="button" onclick="insertBenefitEmoji(\\\'🏊\\\')" class="px-2 py-1 bg-white border border-gray-300 rounded hover:bg-gray-100 text-sm" title="Activities">🏊</button>';
        html += '</div>';
