      window.closeFaceEnrollModal = function() {
        const modal = document.getElementById('face-enroll-modal');
        if (modal) {
          // Stop any webcam streams
          const videos = modal.querySelectorAll('video');
          videos.forEach(video => {
            if (video.srcObject) {
              video.srcObject.getTracks().forEach(track => track.stop());
            }
          });
          modal.remove();
        }
      };
      
      // Signature pad drawing state
      let signatureData = {};
      
      window.initializeSignaturePad = function(passId) {
        const canvas = document.getElementById('signature-pad-' + passId);
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        let drawing = false;
        let hasSignature = false;
        
        signatureData[passId] = null;
        
        // Mouse events
        canvas.addEventListener('mousedown', (e) => {
          drawing = true;
          const rect = canvas.getBoundingClientRect();
          ctx.beginPath();
          ctx.moveTo(e.clientX - rect.left, e.clientY - rect.top);
        });
        
        canvas.addEventListener('mousemove', (e) => {
          if (!drawing) return;
          const rect = canvas.getBoundingClientRect();
          ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
          ctx.strokeStyle = '#000';
          ctx.lineWidth = 2;
          ctx.lineCap = 'round';
          ctx.stroke();
          hasSignature = true;
          document.getElementById('consent-btn-' + passId).disabled = false;
        });
        
        canvas.addEventListener('mouseup', () => {
          drawing = false;
          if (hasSignature) {
            signatureData[passId] = canvas.toDataURL('image/png');
          }
        });
        
        // Touch events for tablets
        canvas.addEventListener('touchstart', (e) => {
          e.preventDefault();
          drawing = true;
          const rect = canvas.getBoundingClientRect();
          const touch = e.touches[0];
          ctx.beginPath();
          ctx.moveTo(touch.clientX - rect.left, touch.clientY - rect.top);
        });
        
        canvas.addEventListener('touchmove', (e) => {
          e.preventDefault();
          if (!drawing) return;
          const rect = canvas.getBoundingClientRect();
          const touch = e.touches[0];
          ctx.lineTo(touch.clientX - rect.left, touch.clientY - rect.top);
          ctx.strokeStyle = '#000';
          ctx.lineWidth = 2;
          ctx.lineCap = 'round';
          ctx.stroke();
          hasSignature = true;
          document.getElementById('consent-btn-' + passId).disabled = false;
        });
        
        canvas.addEventListener('touchend', () => {
          drawing = false;
          if (hasSignature) {
            signatureData[passId] = canvas.toDataURL('image/png');
          }
        });
      };
      
      window.clearSignature = function(passId) {
        const canvas = document.getElementById('signature-pad-' + passId);
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        signatureData[passId] = null;
        document.getElementById('consent-btn-' + passId).disabled = true;
      };
      
      let currentPassReference = null;
      
      window.proceedToPhotoCapture = async function(passId, passReference) {
        const signature = signatureData[passId];
        if (!signature) {
          alert('Please sign the consent form before proceeding.');
          return;
        }
        
        currentPassReference = passReference;
        
        // Show loading state
        const consentBtn = document.getElementById('consent-btn-' + passId);
        consentBtn.disabled = true;
        consentBtn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>Saving consent...';
        
        try {
          // Save consent signature to database
          const response = await fetchWithAuth('/api/admin/face-enrollment/consent', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              pass_reference: passReference,
              signature_data: signature,
              consent_language: 'en',
              consent_timestamp: new Date().toISOString(),
              staff_id: localStorage.getItem('userEmail') || 'unknown'
            })
          });
          
          if (!response.ok) {
            const error = await response.json();
            throw new Error(error.error || 'Failed to save consent');
          }
          
          const data = await response.json();
          console.log('Consent saved:', data);
          
          // Hide consent step, show photo capture step
          document.getElementById('consent-step-' + passId).classList.add('hidden');
          document.getElementById('photo-capture-step-' + passId).classList.remove('hidden');
        } catch (error) {
          console.error('Consent save error:', error);
          alert('❌ Failed to save consent: ' + error.message);
          consentBtn.disabled = false;
          consentBtn.innerHTML = '<i class="fas fa-check mr-2"></i>I Consent - Proceed to Photo Capture';
        }
      };

      // GDPR/BIPA: Withdraw biometric consent and delete all biometric data
      window.withdrawBiometricConsent = async function(passId, guestName) {
        const confirmed = confirm(
          '⚠️ WITHDRAW BIOMETRIC CONSENT\\n\\n' +
          'Guest: ' + guestName + '\\n\\n' +
          'This will IMMEDIATELY:\\n' +
          '• Delete all facial recognition data\\n' +
          '• Remove biometric templates permanently\\n' +
          '• Switch to QR code, wristband, or room card\\n\\n' +
          'This action is irreversible.\\n\\n' +
          'Are you sure?'
        );
        
        if (!confirmed) return;
        
        try {
          const response = await fetchWithAuth('/api/admin/all-inclusive/passes/' + passId + '/withdraw-consent', {
            method: 'POST'
          });
          
          if (response.ok) {
            const data = await response.json();
            alert(
              '✅ Biometric Consent Withdrawn\\n\\n' +
              'All biometric data has been permanently deleted.\\n\\n' +
              'Guest can now use:\\n' +
              '• QR Code\\n' +
              '• Wristband\\n' +
              '• Room Card\\n\\n' +
              'Deletion logged for GDPR/BIPA compliance.'
            );
            loadPasses(); // Reload to show updated status
          } else {
            const error = await response.json();
            alert('❌ Error: ' + (error.error || 'Failed to withdraw consent'));
          }
        } catch (error) {
          console.error('Withdraw consent error:', error);
          alert('❌ Error: ' + error.message);
        }
      };
      
      let currentPhotoData = null;
      let currentFaceEmbedding = null;
      
      window.handlePhotoUpload = async function(passId, input) {
        if (!input.files || !input.files[0]) return;
        
        const file = input.files[0];
        const reader = new FileReader();
        
        reader.onload = async function(e) {
          currentPhotoData = e.target.result;
          
          // Show preview
          const previewArea = document.getElementById('photo-preview-' + passId);
          const previewImg = document.getElementById('preview-img-' + passId);
          const statusEl = document.getElementById('face-status-' + passId);
          
          previewImg.src = currentPhotoData;
          previewArea.classList.remove('hidden');
          statusEl.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>Detecting face...';
          
          // Detect face using face-api.js
          await detectFaceInImage(previewImg, passId);
          
          document.getElementById('submit-area-' + passId).classList.remove('hidden');
        };
        
        reader.readAsDataURL(file);
      };
      
      window.startWebcam = async function(passId) {
        const webcamArea = document.getElementById('webcam-area-' + passId);
        const video = document.getElementById('webcam-' + passId);
        const canvas = document.getElementById('webcam-canvas-' + passId);
        
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: 640, height: 480 } });
          video.srcObject = stream;
          webcamArea.classList.remove('hidden');
          
          // Setup canvas
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          
          // Start face detection
          video.addEventListener('loadedmetadata', () => {
            detectFaceInWebcam(video, canvas);
          });
        } catch (error) {
          alert('Failed to access webcam: ' + error.message);
        }
      };
      
      window.stopWebcam = function(passId) {
        const video = document.getElementById('webcam-' + passId);
        if (video.srcObject) {
          video.srcObject.getTracks().forEach(track => track.stop());
        }
        document.getElementById('webcam-area-' + passId).classList.add('hidden');
      };
      
      window.capturePhoto = async function(passId) {
        const video = document.getElementById('webcam-' + passId);
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        
        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0);
        
        currentPhotoData = canvas.toDataURL('image/jpeg', 0.9);
        
        // Stop webcam
        stopWebcam(passId);
        
        // Show preview
        const previewArea = document.getElementById('photo-preview-' + passId);
        const previewImg = document.getElementById('preview-img-' + passId);
        const statusEl = document.getElementById('face-status-' + passId);
        
        previewImg.src = currentPhotoData;
        previewArea.classList.remove('hidden');
        statusEl.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>Detecting face...';
        
        // Detect face
        await detectFaceInImage(previewImg, passId);
        
        document.getElementById('submit-area-' + passId).classList.remove('hidden');
      };
      
      async function detectFaceInImage(imgElement, passId) {
        const statusEl = document.getElementById('face-status-' + passId);
        
        try {
          // Load face-api.js models if not loaded
          if (!window.faceapi) {
            statusEl.innerHTML = '<i class="fas fa-exclamation-circle text-yellow-500 mr-2"></i>Face detection library loading... (enrollment will continue)';
            return;
          }
          
          const detection = await faceapi.detectSingleFace(imgElement, new faceapi.TinyFaceDetectorOptions())
            .withFaceLandmarks()
            .withFaceDescriptor();
          
          if (detection) {
            currentFaceEmbedding = Array.from(detection.descriptor);
            statusEl.innerHTML = '<i class="fas fa-check-circle text-green-500 mr-2"></i>Face detected successfully! Ready to enroll.';
          } else {
            currentFaceEmbedding = null;
            statusEl.innerHTML = '<i class="fas fa-exclamation-triangle text-yellow-500 mr-2"></i>No face detected. Photo will be saved without facial recognition.';
          }
        } catch (error) {
          console.error('Face detection error:', error);
          statusEl.innerHTML = '<i class="fas fa-info-circle text-blue-500 mr-2"></i>Face detection unavailable. Photo will be saved for manual verification.';
        }
      }
      
      async function detectFaceInWebcam(video, canvas) {
        if (!window.faceapi || !video.srcObject) return;
        
        const detections = await faceapi.detectAllFaces(video, new faceapi.TinyFaceDetectorOptions());
        
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        
        if (detections.length > 0) {
          const { x, y, width, height } = detections[0].box;
          ctx.strokeStyle = '#10b981';
          ctx.lineWidth = 3;
          ctx.strokeRect(x, y, width, height);
        }
        
        requestAnimationFrame(() => detectFaceInWebcam(video, canvas));
      }
      
      window.submitFaceEnrollment = async function(passId) {
        if (!currentPhotoData) {
          alert('Please upload or capture a photo first');
          return;
        }
        
        if (!currentFaceEmbedding) {
          alert('Face detection failed. Please try another photo with a clear view of the face.');
          return;
        }
        
        if (!currentPassReference) {
          alert('Pass reference not found. Please close and try again.');
          return;
        }
        
        const submitBtn = document.querySelector('#submit-area-' + passId + ' button');
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>Enrolling with consent...';
        
        try {
          // Use the new consent-based enrollment endpoint
          const response = await fetchWithAuth('/api/admin/face-enrollment/complete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              pass_reference: currentPassReference,
              photo_data: currentPhotoData, // Sent but not stored permanently
              face_embedding: currentFaceEmbedding,
              staff_id: localStorage.getItem('userEmail') || 'unknown'
            })
          });
          
          const data = await response.json();
          
          if (data.success) {
            alert(
              '✅ Face Enrolled Successfully!\\n\\n' +
              'Guest can now use facial recognition.\\n' +
              'Data will be auto-deleted: ' + new Date(data.scheduled_deletion_date).toLocaleDateString() + '\\n\\n' +
              '🔒 Privacy Protected:\\n' +
              '• Only irreversible face template stored\\n' +
              '• Photo not saved permanently\\n' +
              '• Digital consent signature captured\\n' +
              '• Automatic deletion after checkout'
            );
            closeFaceEnrollModal();
            loadPasses(); // Reload passes to show updated status
          } else {
            if (data.requires_consent) {
              alert('❌ Consent Required\\n\\nPlease complete the consent signature step first before enrolling.');
            } else {
              alert('❌ Failed to enroll face: ' + (data.error || 'Unknown error'));
            }
            submitBtn.disabled = false;
            submitBtn.innerHTML = '<i class="fas fa-check mr-2"></i>Enroll Face & Save';
          }
        } catch (error) {
          console.error('Face enrollment error:', error);
          alert('❌ Failed to enroll face: ' + error.message);
          submitBtn.disabled = false;
          submitBtn.innerHTML = '<i class="fas fa-check mr-2"></i>Enroll Face & Save';
        }
      };
      
