          html += '<div class="text-xs text-gray-500">Approved</div>';
          html += '</div>';
          html += '<div class="text-center">';
          html += '<div class="text-2xl font-bold text-yellow-600">' + (stats.manual_reviews || 0) + '</div>';
          html += '<div class="text-xs text-gray-500">Manual</div>';
          html += '</div>';
          html += '<div class="text-center">';
