// Get menu for a specific restaurant
app.get('/api/alacarte/menu/:restaurant_id', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const restaurant_id = c.req.param('restaurant_id')

  try {
    const restaurant = await DB.prepare(`
      SELECT offering_id, title_en, title_ar, short_description_en, short_description_ar, currency
      FROM hotel_offerings
      WHERE offering_id = ? AND property_id = ? AND offering_type IN ('restaurant', 'room_service')
    `).bind(restaurant_id, property_id).first()

    if (!restaurant) {
      return c.json({ success: false, error: 'Restaurant not found' }, 404)
    }

    const menu = await DB.prepare(`
      SELECT 
        item_id,
        category,
        item_name,
        item_name_ar,
        description,
        description_ar,
        cost_to_hotel,
        is_premium,
        allergens,
        display_order
      FROM alacarte_menu_items
      WHERE restaurant_id = ? AND property_id = ? AND is_available = 1
      ORDER BY 
        CASE category
          WHEN 'salad' THEN 1
          WHEN 'starter' THEN 2
          WHEN 'main' THEN 3
          WHEN 'dessert' THEN 4
          ELSE 5
        END,
        display_order,
        item_name
    `).bind(restaurant_id, property_id).all()

    // Group by category
    const menuByCategory: Record<string, any[]> = {}
    for (const item of menu.results) {
      const cat = item.category as string
      if (!menuByCategory[cat]) {
        menuByCategory[cat] = []
      }
      menuByCategory[cat].push(item)
    }

    return c.json({
      success: true,
      restaurant,
      menu: menuByCategory,
      categories: ['salad', 'starter', 'main', 'dessert']
    })
  } catch (error) {
    console.error('Get menu error:', error)
    return c.json({ success: false, error: 'Failed to fetch menu' }, 500)
  }
})

// Check guest voucher eligibility
app.get('/api/alacarte/voucher-eligibility/:pass_reference', async (c) => {
  const { DB } = c.env
  const pass_reference = c.req.param('pass_reference')
  const property_id = c.req.header('X-Property-ID') || '1'

  try {
    // Get digital pass and tier info
    const passInfo = await DB.prepare(`
      SELECT 
        dp.pass_id,
        dp.pass_reference,
        dp.primary_guest_name,
        dp.room_number,
        dp.num_adults,
        dp.num_children,
        dp.valid_from,
        dp.valid_until,
        t.tier_id,
        t.tier_code,
        t.tier_display_name,
        t.tier_color,
        t.alacarte_meals_per_stay,
        t.alacarte_eligible_restaurants,
        t.alacarte_premium_surcharge,
        t.alacarte_privileges_message
      FROM digital_passes dp
      JOIN all_inclusive_tiers t ON dp.tier_id = t.tier_id
      WHERE dp.pass_reference = ? AND dp.property_id = ?
    `).bind(pass_reference, property_id).first()

    if (!passInfo) {
      return c.json({ success: false, error: 'Pass not found' }, 404)
    }

    // Check if tier is eligible
    const mealsAllowed = passInfo.alacarte_meals_per_stay || 0
    if (mealsAllowed === 0) {
      return c.json({
        success: true,
        eligible: false,
        reason: 'Tier not eligible for à la carte dining',
        tier: {
          tier_code: passInfo.tier_code,
          tier_name: passInfo.tier_display_name,
          tier_color: passInfo.tier_color
        }
      })
    }

    // Calculate total vouchers: meals_per_stay × number_of_guests
    const numGuests = (passInfo.num_adults || 1) + (passInfo.num_children || 0)
    const totalVouchers = mealsAllowed * numGuests

    // Count used vouchers for this pass
    const usedVouchers = await DB.prepare(`
      SELECT COUNT(*) as used_count
      FROM alacarte_vouchers
      WHERE pass_id = ? AND status IN ('confirmed', 'used')
    `).bind(passInfo.pass_id).first()

    const vouchersUsed = usedVouchers?.used_count || 0
    const vouchersRemaining = totalVouchers - vouchersUsed

    // Parse eligible restaurants
    let eligibleRestaurants = []
    try {
      if (passInfo.alacarte_eligible_restaurants) {
        eligibleRestaurants = JSON.parse(passInfo.alacarte_eligible_restaurants)
      }
    } catch (e) {
      console.error('Parse eligible restaurants error:', e)
    }

    // Get restaurant details if specific restaurants are set
    let restaurantDetails = []
    if (eligibleRestaurants.length > 0) {
      const restaurantList = await DB.prepare(`
        SELECT offering_id, title_en, location, images
        FROM hotel_offerings
        WHERE offering_id IN (${eligibleRestaurants.map(() => '?').join(',')})
          AND property_id = ?
          AND offering_type = 'restaurant'
          AND status = 'active'
      `).bind(...eligibleRestaurants, property_id).all()
      // Parse images JSON for each restaurant
      restaurantDetails = restaurantList.results.map(r => ({
        ...r,
        images: r.images ? JSON.parse(r.images) : []
      }))
    } else {
      // All à la carte restaurants are eligible
      const allRestaurants = await DB.prepare(`
        SELECT offering_id, title_en, location, images
        FROM hotel_offerings
        WHERE property_id = ?
          AND offering_type = 'restaurant'
          AND status = 'active'
        ORDER BY display_order, title_en
      `).bind(property_id).all()
      // Parse images JSON for each restaurant
      restaurantDetails = allRestaurants.results.map(r => ({
        ...r,
        images: r.images ? JSON.parse(r.images) : []
      }))
    }

    return c.json({
      success: true,
      eligible: vouchersRemaining > 0,
      guest_name: passInfo.primary_guest_name,
      num_guests: numGuests,
      num_adults: passInfo.num_adults || 1,
      num_children: passInfo.num_children || 0,
      tier: {
        tier_code: passInfo.tier_code,
        tier_name: passInfo.tier_display_name,
        tier_color: passInfo.tier_color,
        privileges_message: passInfo.alacarte_privileges_message
      },
      vouchers: {
        meals_per_stay: mealsAllowed,
        total_vouchers: totalVouchers,
        used: vouchersUsed,
        remaining: vouchersRemaining
      },
      eligible_restaurants: restaurantDetails,
      premium_surcharge: passInfo.alacarte_premium_surcharge || 0
    })
  } catch (error) {
    console.error('Check voucher eligibility error:', error)
    console.error('Error details:', error.message, error.stack)
    return c.json({ 
      success: false, 
      error: 'Failed to check eligibility',
      debug: error.message 
    }, 500)
  }
})

// Create à la carte voucher
app.post('/api/alacarte/voucher', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const {
      pass_reference,
      restaurant_id,
      reservation_date,
      reservation_time,
      num_people, // Number of people ordering (uses this many vouchers)
      table_id,
      preorder_items, // Array of { item_id, quantity }
      special_requests,
      allergy_info, // NEW: Allergy/dietary restriction information
      no_allergies_confirmed // NEW: Guest confirmed no allergies
    } = body
    
    // Build special requests field with allergy info
    let combinedSpecialRequests = special_requests || ''
    if (allergy_info) {
      const allergyNote = `🚨 ALLERGIES/DIETARY RESTRICTIONS: ${allergy_info}`
      combinedSpecialRequests = combinedSpecialRequests 
        ? `${combinedSpecialRequests}\n\n${allergyNote}` 
        : allergyNote
    } else if (no_allergies_confirmed) {
      const noAllergyNote = `✅ NO ALLERGIES - Guest confirmed no dietary restrictions`
      combinedSpecialRequests = combinedSpecialRequests 
        ? `${combinedSpecialRequests}\n\n${noAllergyNote}` 
        : noAllergyNote
    }

    // Verify pass and get eligibility info
    const passInfo = await DB.prepare(`
      SELECT 
        dp.pass_id,
        dp.property_id,
        dp.num_adults,
        dp.num_children,
        t.alacarte_meals_per_stay,
        t.alacarte_eligible_restaurants,
        t.alacarte_premium_surcharge
      FROM digital_passes dp
      JOIN all_inclusive_tiers t ON dp.tier_id = t.tier_id
      WHERE dp.pass_reference = ? AND dp.property_id = ?
    `).bind(pass_reference, property_id).first()

    if (!passInfo) {
      return c.json({ success: false, error: 'Pass not found' }, 404)
    }

    // Calculate total vouchers available
    const numGuests = (passInfo.num_adults || 1) + (passInfo.num_children || 0)
    const mealsPerStay = passInfo.alacarte_meals_per_stay || 0
    const totalVouchers = mealsPerStay * numGuests

    // Validate num_people
    const peopleOrdering = num_people || 1
    if (peopleOrdering > numGuests) {
      return c.json({ 
        success: false, 
        error: `Cannot order for ${peopleOrdering} people. Pass only has ${numGuests} guest${numGuests > 1 ? 's' : ''}.` 
      }, 400)
    }

    // Check vouchers remaining
    const usedVouchers = await DB.prepare(`
      SELECT COUNT(*) as used_count
      FROM alacarte_vouchers
      WHERE pass_id = ? AND status IN ('confirmed', 'used')
    `).bind(passInfo.pass_id).first()

    const vouchersUsed = usedVouchers?.used_count || 0
    const vouchersRemaining = totalVouchers - vouchersUsed

    // Validate enough vouchers
    const vouchersNeeded = peopleOrdering
    if (vouchersNeeded > vouchersRemaining) {
      return c.json({ 
        success: false, 
        error: `Not enough vouchers. Need ${vouchersNeeded} but only ${vouchersRemaining} remaining.` 
      }, 400)
    }

    // Check restaurant eligibility
    let eligibleRestaurants = []
    try {
      if (passInfo.alacarte_eligible_restaurants) {
        eligibleRestaurants = JSON.parse(passInfo.alacarte_eligible_restaurants)
        if (eligibleRestaurants.length > 0 && !eligibleRestaurants.includes(restaurant_id.toString())) {
          return c.json({ success: false, error: 'Restaurant not eligible for your tier' }, 400)
        }
      }
    } catch (e) {
      console.error('Parse restaurants error:', e)
    }

    // Calculate total cost from items with quantities
    let totalCost = 0
    const itemsArray = preorder_items || []
    
    for (const preorderItem of itemsArray) {
      const item = await DB.prepare(`
        SELECT cost_to_hotel FROM alacarte_menu_items WHERE item_id = ?
      `).bind(preorderItem.item_id).first()
      
      if (item) {
        totalCost += (item.cost_to_hotel || 0) * (preorderItem.quantity || 1)
      }
    }

    // Get tier_id for the voucher
    const passWithTier = await DB.prepare(`
      SELECT tier_id FROM digital_passes WHERE pass_id = ?
    `).bind(passInfo.pass_id).first()

    // Get table number if table_id provided
    let tableNumber = null
    if (table_id) {
      const table = await DB.prepare(`
        SELECT table_number FROM restaurant_tables WHERE table_id = ?
      `).bind(table_id).first()
      tableNumber = table?.table_number || null
    }

    // Create vouchers (one for each person ordering)
    const voucherCodes = []
    for (let i = 0; i < peopleOrdering; i++) {
      // Generate unique voucher code
      const dateStr = reservation_date.replace(/-/g, '')
      const randomNum = Math.floor(1000 + Math.random() * 9000)
      const voucherCode = `MEAL-${dateStr}-${randomNum}`
      voucherCodes.push(voucherCode)

      // Insert voucher with items as JSON array
      await DB.prepare(`
        INSERT INTO alacarte_vouchers (
          property_id,
          pass_id,
          voucher_code,
          tier_id,
          meal_number,
          restaurant_id,
          reservation_date,
          reservation_time,
          party_size,
          table_number,
          preorder_item_ids,
          special_requests,
          total_cost,
          status
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        property_id,
        passInfo.pass_id,
        voucherCode,
        passWithTier?.tier_id || 1,
        vouchersUsed + i + 1, // Sequential meal number
        restaurant_id,
        reservation_date,
        reservation_time,
        1, // Party size is 1 per voucher (each person gets their own voucher)
        tableNumber,
        JSON.stringify(itemsArray), // Store items with quantities as JSON
        combinedSpecialRequests || null,
        totalCost / peopleOrdering, // Divide cost evenly per person
        'confirmed'
      ).run()
    }

    const newVouchersUsed = vouchersUsed + peopleOrdering
    const newVouchersRemaining = totalVouchers - newVouchersUsed

    return c.json({
      success: true,
      voucher_code: voucherCodes[0], // Primary voucher code
      voucher_codes: voucherCodes, // All voucher codes
      num_vouchers_created: peopleOrdering,
      total_cost: totalCost, // Total cost for all items
      vouchers_used: newVouchersUsed,
      vouchers_remaining: newVouchersRemaining
    })
  } catch (error) {
    console.error('Create voucher error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to create voucher',
      details: error.message || String(error)
    }, 500)
  }
})

// Get voucher details
app.get('/api/alacarte/voucher/:voucher_code', async (c) => {
  const { DB } = c.env
  const voucher_code = c.req.param('voucher_code')
  const property_id = c.req.header('X-Property-ID') || '1'

  try {
    const voucher = await DB.prepare(`
      SELECT 
        v.*,
        r.title_en as restaurant_name,
        r.location as restaurant_location,
        dp.pass_reference,
        dp.primary_guest_name,
        salad.item_name as salad_name,
        starter.item_name as starter_name,
        main.item_name as main_name,
        dessert.item_name as dessert_name
      FROM alacarte_vouchers v
      JOIN hotel_offerings r ON v.restaurant_id = r.offering_id
      JOIN digital_passes dp ON v.pass_id = dp.pass_id
      LEFT JOIN alacarte_menu_items salad ON v.preorder_salad_id = salad.item_id
      LEFT JOIN alacarte_menu_items starter ON v.preorder_starter_id = starter.item_id
      LEFT JOIN alacarte_menu_items main ON v.preorder_main_id = main.item_id
      LEFT JOIN alacarte_menu_items dessert ON v.preorder_dessert_id = dessert.item_id
      WHERE v.voucher_code = ? AND v.property_id = ?
    `).bind(voucher_code, property_id).first()

    if (!voucher) {
      return c.json({ success: false, error: 'Voucher not found' }, 404)
    }

    return c.json({
      success: true,
      voucher
    })
  } catch (error) {
    console.error('Get voucher error:', error)
    return c.json({ success: false, error: 'Failed to fetch voucher' }, 500)
  }
})

