// Front Desk Manual À La Carte Booking
app.post('/api/front-desk/alacarte-booking', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const {
      pass_reference, // OPTIONAL - for digital pass voucher bookings
      guest_name,
      room_number,
      party_size,
      reservation_date,
      reservation_time,
      restaurant_id,
      table_id, // OPTIONAL - selected table ID
      staff_id, // OPTIONAL - staff member creating the booking
      items, // [{ item_id, quantity, custom_limit }]
      allergy_info,
      no_allergies_confirmed
    } = body
    
    console.log('[Front Desk Booking] property_id:', property_id, 'type:', typeof property_id)
    
    // Validate required fields (pass_reference is OPTIONAL for walk-in guests)
    if (!guest_name || !room_number || !party_size || !reservation_date || !reservation_time || !restaurant_id || !items || items.length === 0) {
      return c.json({ success: false, error: 'Missing required fields' }, 400)
    }
    
    let pass = null
    let passId = null
    let tierId = 1 // Default tier for walk-in
    let mealNumber = 1
    
    // If pass_reference provided, verify the pass
    if (pass_reference) {
      pass = await DB.prepare(`
        SELECT pass_id, tier_id, num_adults, num_children, pass_status
        FROM digital_passes
        WHERE pass_reference = ? AND property_id = ?
      `).bind(pass_reference, property_id).first()
      
      if (!pass) {
        return c.json({ success: false, error: 'Digital pass not found' }, 404)
      }
      
      if (pass.pass_status !== 'active') {
        return c.json({ success: false, error: 'Pass is not active' }, 400)
      }
      
      const maxGuests = (pass.num_adults || 1) + (pass.num_children || 0)
      if (party_size > maxGuests) {
        return c.json({ 
          success: false, 
          error: `Party size (${party_size}) exceeds maximum guests on pass (${maxGuests})` 
        }, 400)
      }
      
      // Get meal number (next available)
      const vouchersUsed = await DB.prepare(`
        SELECT COUNT(*) as count
        FROM alacarte_vouchers
        WHERE pass_id = ? AND status IN ('confirmed', 'used')
      `).bind(pass.pass_id).first()
      
      mealNumber = (vouchersUsed?.count || 0) + 1
      passId = pass.pass_id
      tierId = pass.tier_id || 1
    }
    
    // Generate voucher code
    const timestamp = Date.now()
    const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0')
    const voucher_code = `MEAL-${reservation_date.replace(/-/g, '')}-${random}`
    
    // Get item IDs and quantities
    // Item IDs already have rm_ prefix for extra-charge items (added by front-end)
    const preorder_items = items.map(i => ({
      item_id: i.item_id, // Use as-is - rm_ prefix already added by front-end for extra-charge
      quantity: i.quantity || 1
    }))
    
    // Look up table number if table_id provided
    let table_number = null
    if (table_id) {
      const table = await DB.prepare(`
        SELECT table_number
        FROM restaurant_tables
        WHERE table_id = ? AND offering_id = ?
      `).bind(table_id, restaurant_id).first()
      
      if (table) {
        table_number = table.table_number
      }
    }
    
    // Build special requests with allergy info
    let special_requests = `Manual booking via Front Desk - Guest: ${guest_name}, Room: ${room_number}`
    if (pass_reference) {
      special_requests += `, Pass: ${pass_reference}`
    } else {
      special_requests += ` (Walk-in - No Pass)`
    }
    
    if (allergy_info && allergy_info.trim()) {
      special_requests = `ALLERGIES/DIETARY RESTRICTIONS: ${allergy_info}\n\n${special_requests}`
    } else if (no_allergies_confirmed) {
      special_requests = `NO ALLERGIES CONFIRMED\n\n${special_requests}`
    }
    
    // Create voucher (with or without pass)
    console.log('[Front Desk Booking] About to INSERT with property_id:', property_id)
    await DB.prepare(`
      INSERT INTO alacarte_vouchers (
        property_id,
        voucher_code,
        pass_id,
        tier_id,
        meal_number,
        restaurant_id,
        reservation_date,
        reservation_time,
        party_size,
        table_number,
        preorder_item_ids,
        special_requests,
        created_by_staff_id,
        status,
        created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
    `).bind(
      property_id,
      voucher_code,
      passId, // NULL for walk-in guests
      tierId,
      mealNumber,
      restaurant_id,
      reservation_date,
      reservation_time,
      party_size,
      table_number, // Will be NULL if no table selected
      JSON.stringify(preorder_items),
      special_requests,
      staff_id || null, // Staff member creating the booking (NULL if not provided)
      'confirmed'
    ).run()
    console.log('[Front Desk Booking] INSERT completed for voucher:', voucher_code)
    
    return c.json({
      success: true,
      voucher_code,
      message: 'Booking created successfully'
    })
  } catch (error) {
    console.error('Front desk booking error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to create booking',
      details: error.message 
    }, 500)
  }
})

// Guest à la carte booking (from QR code - no pass required)
app.post('/api/front-desk/guest-alacarte-booking', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const {
      room_number,
      guest_name,
      party_size,
      restaurant_id,
      reservation_date,
      reservation_time,
      table_id,
      items, // [{ item_id, quantity }]
      allergy_info,
      no_allergies_confirmed
    } = body
    
    console.log('📱 Guest QR booking:', { room_number, guest_name, party_size, restaurant_id, table_id })
    
    // Validate required fields
    if (!room_number || !guest_name || !party_size || !reservation_date || !reservation_time || !restaurant_id || !items || items.length === 0) {
      return c.json({ success: false, error: 'Missing required fields' }, 400)
    }
    
    // Get table_number from table_id if provided
    let actual_table_number = null
    if (table_id) {
      const table = await DB.prepare(`
        SELECT table_number FROM restaurant_tables WHERE table_id = ?
      `).bind(table_id).first()
      // CRITICAL: Only use table_number if table exists, otherwise NULL
      // DO NOT fall back to table_id (which might be room_number)
      actual_table_number = table?.table_number || null
      console.log('📍 Table lookup:', { table_id, table_number: actual_table_number })
    }
    
    // Look up or create a digital pass for this room
    let pass = await DB.prepare(`
      SELECT pass_id, tier_id, pass_reference
      FROM digital_passes
      WHERE room_number = ? AND property_id = ? AND pass_status = 'active'
      ORDER BY pass_id DESC
      LIMIT 1
    `).bind(room_number, property_id).first()
    
    if (!pass) {
      // Create a temporary pass for this guest
      const pass_reference = `QR-${Date.now()}-${Math.random().toString(36).substring(7).toUpperCase()}`
      const qr_secret = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
      
      await DB.prepare(`
        INSERT INTO digital_passes (
          property_id,
          pass_reference,
          primary_guest_name,
          room_number,
          num_adults,
          num_children,
          tier_id,
          pass_status,
          valid_from,
          valid_until,
          qr_secret,
          issued_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
      `).bind(
        property_id,
        pass_reference,
        guest_name,
        room_number,
        party_size,
        0,
        2, // Use existing tier_id
        'active',
        reservation_date,
        reservation_date,
        qr_secret
      ).run()
      
      // Retrieve the newly created pass
      pass = await DB.prepare(`
        SELECT pass_id, tier_id, pass_reference
        FROM digital_passes
        WHERE pass_reference = ? AND property_id = ?
      `).bind(pass_reference, property_id).first()
      
      console.log('✅ Created temporary pass:', pass_reference)
    }
    
    // Get meal number for this pass
    const vouchersUsed = await DB.prepare(`
      SELECT COUNT(*) as count
      FROM alacarte_vouchers
      WHERE pass_id = ? AND status IN ('confirmed', 'used')
    `).bind(pass.pass_id).first()
    
    const mealNumber = (vouchersUsed?.count || 0) + 1
    
    // Generate voucher code
    const timestamp = Date.now()
    const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0')
    const voucher_code = `MEAL-${reservation_date.replace(/-/g, '')}-${random}`
    
    // Get item IDs and quantities
    // Guest ordering items don't have rm_ prefix (they're all set menu), but we'll keep the code simple
    const preorder_items = items.map(i => ({
      item_id: i.item_id, // Use as-is
      quantity: i.quantity || 1
    }))
    
    // Build special requests with allergy and table info
    let special_requests = `📱 Guest order via QR code\nGuest: ${guest_name}, Room: ${room_number}`
    if (actual_table_number) {
      special_requests += `\nTable: ${actual_table_number}`
    }
    if (allergy_info && allergy_info.trim()) {
      special_requests = `⚠️ ALLERGIES/DIETARY RESTRICTIONS: ${allergy_info}\n\n${special_requests}`
    } else if (no_allergies_confirmed) {
      special_requests = `✅ NO ALLERGIES CONFIRMED\n\n${special_requests}`
    }
    
    // Create voucher with pass reference
    await DB.prepare(`
      INSERT INTO alacarte_vouchers (
        property_id,
        pass_id,
        tier_id,
        meal_number,
        voucher_code,
        restaurant_id,
        reservation_date,
        reservation_time,
        party_size,
        table_number,
        preorder_item_ids,
        special_requests,
        status,
        created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
    `).bind(
      property_id,
      pass.pass_id,
      pass.tier_id || 1,
      mealNumber,
      voucher_code,
      restaurant_id,
      reservation_date,
      reservation_time,
      party_size,
      actual_table_number, // Use the looked-up table_number
      JSON.stringify(preorder_items),
      special_requests,
      'confirmed'
    ).run()
    
    console.log('✅ Guest QR booking created:', voucher_code)
    
    return c.json({
      success: true,
      voucher_code,
      message: 'Booking created successfully'
    })
  } catch (error) {
    console.error('Guest QR booking error:', error)
    return c.json({ 
      success: false, 
      error: 'Failed to create booking',
      details: error.message 
    }, 500)
  }
})

// Mark voucher as used
app.post('/api/alacarte/voucher/:voucher_code/redeem', async (c) => {
  const { DB } = c.env
  const voucher_code = c.req.param('voucher_code')
  const property_id = c.req.header('X-Property-ID') || '1'

  try {
    const body = await c.req.json()
    const { staff_id, staff_name } = body

    // Get voucher
    const voucher = await DB.prepare(`
      SELECT voucher_id, status
      FROM alacarte_vouchers
      WHERE voucher_code = ? AND property_id = ?
    `).bind(voucher_code, property_id).first()

    if (!voucher) {
      return c.json({ success: false, error: 'Voucher not found' }, 404)
    }

    if (voucher.status === 'used') {
      return c.json({ success: false, error: 'Voucher already used' }, 400)
    }

    if (voucher.status === 'cancelled') {
      return c.json({ success: false, error: 'Voucher cancelled' }, 400)
    }

    // Mark as used
    await DB.prepare(`
      UPDATE alacarte_vouchers
      SET 
        status = 'used',
        checked_in_at = CURRENT_TIMESTAMP,
        checked_in_by = ?
      WHERE voucher_id = ?
    `).bind(staff_name || 'Staff', voucher.voucher_id).run()

    return c.json({
      success: true,
      message: 'Voucher redeemed successfully'
    })
  } catch (error) {
    console.error('Redeem voucher error:', error)
    return c.json({ success: false, error: 'Failed to redeem voucher' }, 500)
  }
})

