// Called by the op-ring cron every minute: keep ringing while anything is
// unacknowledged (recent guest activity with no staff ack), cutoff 20 min
app.post('/api/staff/ring-check', async (c) => {
  const { DB } = c.env
  try {
    const unackedChats = await DB.prepare(`
      SELECT COUNT(*) as n FROM chatbot_conversations c
      WHERE c.property_id = 1
        AND EXISTS (
          SELECT 1 FROM chatbot_messages m
          WHERE m.conversation_id = c.conversation_id
            AND m.role = 'user'
            AND m.created_at > datetime('now', '-20 minutes')
            AND (c.staff_ack_at IS NULL OR m.created_at > c.staff_ack_at)
        )
    `).first()
    const unreadFb = await DB.prepare(`
      SELECT COUNT(*) as n FROM feedback_submissions
      WHERE property_id = 1 AND is_read = 0
        AND submitted_at > datetime('now', '-20 minutes')
    `).first()
    const pending = ((unackedChats && unackedChats.n) || 0) + ((unreadFb && unreadFb.n) || 0)
    if (pending > 0) {
      c.executionCtx.waitUntil(ringStaff(c.env, DB, 2, 5000))
    }
    // Nobody picked up in time? Escalate to management on WhatsApp.
    c.executionCtx.waitUntil(runEscalations(c.env, DB).catch(() => {}))
    return c.json({ success: true, pending })
  } catch (e) {
    console.error('ring-check', e)
    return c.json({ success: false }, 500)
  }
})

// Staff translation: guests write in any language, the front desk reads
// English or Arabic. DeepSeek does the work; D1 caches so the app's 15s
// polling never re-pays for the same message.
const LANG_NAMES: Record<string, string> = {
  en: 'English', ar: 'Arabic', ru: 'Russian', de: 'German', fr: 'French', it: 'Italian',
  es: 'Spanish', pl: 'Polish', cs: 'Czech', uk: 'Ukrainian', tr: 'Turkish', nl: 'Dutch',
  ro: 'Romanian', hu: 'Hungarian', sv: 'Swedish', zh: 'Chinese', ja: 'Japanese', ko: 'Korean',
  pt: 'Portuguese', he: 'Hebrew', fa: 'Persian', hi: 'Hindi', sk: 'Slovak', bg: 'Bulgarian', sr: 'Serbian'
}

async function cacheKey(text: string, target: string): Promise<string> {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(target + '::' + text))
  return Array.from(new Uint8Array(buf)).slice(0, 16).map(b => b.toString(16).padStart(2, '0')).join('')
}

app.post('/api/staff/translate', async (c) => {
  const { DB } = c.env
  try {
    const body = await c.req.json()
    const target = (body.target || 'en').toLowerCase()
    const items: any[] = (body.items || []).filter((i: any) => i && i.text && String(i.text).trim())
    if (!items.length) return c.json({ success: true, results: [] })

    const results: any[] = []
    const todo: any[] = []
    for (const it of items) {
      const key = await cacheKey(String(it.text), target)
      const hit = await DB.prepare('SELECT src_lang, translated FROM staff_translations WHERE cache_key = ?').bind(key).first()
      if (hit) {
        results.push({ id: it.id, lang: hit.src_lang, text: hit.translated })
      } else {
        todo.push({ ...it, _key: key })
      }
    }

    if (todo.length) {
      const apiKey = c.env.DEEPSEEK_API_KEY
      const targetName = LANG_NAMES[target] || 'English'
      if (!apiKey) {
        todo.forEach(t => results.push({ id: t.id, lang: 'unknown', text: t.text }))
      } else {
        // Each item carries an echo of its own opening characters; a result is
        // only accepted (and cached) when the echo matches its claimed index —
        // this makes batch-index mixups impossible to poison the cache with.
        const payload = todo.map((t, i) => ({ i: i, src: String(t.text).slice(0, 12), text: String(t.text).slice(0, 1500) }))
        const prompt = 'You are a hotel front-desk translator. For EACH item, detect the source language and translate "text" into ' + targetName + '.\n' +
          'Reply with ONLY a JSON array, no markdown. For each item copy "i" and "src" UNCHANGED from the input and add your output:\n' +
          '[{"i":0,"src":"<copied verbatim>","lang":"<ISO 639-1 code of the SOURCE language>","text":"<translation into ' + targetName + '>"}]\n' +
          'If an item is already in ' + targetName + ', copy its text unchanged and still report its language code. Preserve meaning, tone and any room numbers or times exactly.\n\n' +
          JSON.stringify(payload)
        try {
          const r = await fetch('https://api.deepseek.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
            body: JSON.stringify({
              model: 'deepseek-chat',
              messages: [{ role: 'user', content: prompt }],
              temperature: 0,
              max_tokens: 2400
            })
          })
          const d: any = await r.json()
          let raw = (d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content) || '[]'
          raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim()
          const arr = JSON.parse(raw)
          for (const out of arr) {
            const src = todo[out.i]
            if (!src) continue
            // Reject misaligned results instead of caching a wrong translation
            if (String(out.src || '') !== String(src.text).slice(0, 12)) continue
            results.push({ id: src.id, lang: out.lang || 'unknown', text: out.text || src.text })
            try {
              await DB.prepare(`
                INSERT INTO staff_translations (cache_key, src_lang, target_lang, translated)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(cache_key) DO UPDATE SET translated = excluded.translated, src_lang = excluded.src_lang
              `).bind(src._key, out.lang || 'unknown', target, out.text || src.text).run()
            } catch (e) {}
          }
          // anything the model skipped falls back to the original
          todo.forEach(t => {
            if (!results.find(r2 => r2.id === t.id)) results.push({ id: t.id, lang: 'unknown', text: t.text })
          })
        } catch (e) {
          console.error('staff translate error', e)
          todo.forEach(t => results.push({ id: t.id, lang: 'unknown', text: t.text }))
        }
      }
    }

    // Remember the guest's language so staff replies can be sent back in it
    if (body.session_id) {
      const guestLang = results.map(r => r.lang).find(l => l && l !== 'unknown' && l !== target)
      if (guestLang) {
        try {
          await DB.prepare('UPDATE chatbot_conversations SET guest_lang = ? WHERE session_id = ?')
            .bind(guestLang, body.session_id).run()
        } catch (e) {}
      }
    }

    return c.json({ success: true, results })
  } catch (error) {
    console.error('translate endpoint error', error)
    return c.json({ success: false, error: 'translation failed' }, 500)
  }
})

// ── Agent coaching: admins grade real conversations; verdicts become standing
// orders injected into every future system prompt ──
app.get('/api/admin/agent/overview', async (c) => {
  const { DB } = c.env
  const pid = c.req.query('property_id') || '1'
  try {
    const conv = await DB.prepare(`
      SELECT c.conversation_id, c.session_id, c.guest_name, c.room_number, c.is_ai_paused, c.started_at,
        (SELECT COUNT(*) FROM chatbot_messages m WHERE m.conversation_id = c.conversation_id) as msgs,
        (SELECT content FROM chatbot_messages m WHERE m.conversation_id = c.conversation_id AND m.role='user' ORDER BY m.created_at DESC, m.rowid DESC LIMIT 1) as last_user,
        (SELECT MAX(m.created_at) FROM chatbot_messages m WHERE m.conversation_id = c.conversation_id) as last_at,
        (SELECT COUNT(*) FROM chatbot_lessons l WHERE l.conversation_id = c.conversation_id) as lessons
      FROM chatbot_conversations c
      WHERE c.property_id = ?
      ORDER BY last_at DESC
      LIMIT 40
    `).bind(pid).all()

    const stats = await DB.prepare(`
      SELECT
        (SELECT COUNT(*) FROM chatbot_conversations WHERE property_id = ?1 AND started_at > datetime('now','-24 hours')) as convos24,
        (SELECT COUNT(*) FROM chatbot_messages m JOIN chatbot_conversations cc ON m.conversation_id = cc.conversation_id WHERE cc.property_id = ?1 AND m.created_at > datetime('now','-24 hours')) as msgs24,
        (SELECT COUNT(*) FROM chatbot_chunks WHERE property_id = ?1) as chunks,
        (SELECT COUNT(*) FROM chatbot_lessons WHERE property_id = ?1 AND is_active = 1) as lessons,
        (SELECT COUNT(*) FROM hotel_offerings WHERE property_id = ?1) as offerings,
        (SELECT COUNT(*) FROM info_pages WHERE property_id = ?1) as pages
    `).bind(pid).first()

    return c.json({ success: true, conversations: conv.results || [], stats: stats || {} })
  } catch (e) {
    console.error('agent overview', e)
    return c.json({ success: false, error: 'failed' }, 500)
  }
})

