// ── WhatsApp escalation: nobody answered the guest, so wake a manager ──
//
// Sent through Meta's WhatsApp Cloud API directly (no reseller markup): Egypt
// utility templates are ~$0.0073 per message, so a busy month costs cents.
// A free CallMeBot key per contact is supported as a no-setup fallback.
async function sendWhatsApp(env: any, contact: any, text: string, templateParams: string[]) {
  const token = env.WHATSAPP_TOKEN
  const phoneId = env.WHATSAPP_PHONE_ID

  // WaSender: sends free-form text from the hotel's own WhatsApp number, so
  // alerts need no template approval and read like a normal message.
  // The free plan allows 1 request/minute, so a 429 is retried briefly rather
  // than being written off as a failed alert.
  if (env.WASENDER_TOKEN) {
    // No long retry sleeps here: the escalation cron returns every minute, so a
    // rate-limited send is logged as such and simply takes the next minute's
    // quota. Long waits inside waitUntil get the worker killed mid-flight.
    const to = '+' + String(contact.phone).replace(/[^0-9]/g, '')
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const r = await fetch('https://www.wasenderapi.com/api/send-message', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + env.WASENDER_TOKEN },
          body: JSON.stringify({ to, text })
        })
        const body = await r.text()
        if (r.status === 429 && attempt === 0) {
          await new Promise(res => setTimeout(res, 3000))
          continue
        }
        if (r.status === 429) {
          return { channel: 'wasender', ok: false, detail: 'rate limited (free plan allows 1 message/minute) — retries on the next cycle' }
        }
        let ok = r.ok
        try { ok = ok && JSON.parse(body).success !== false } catch (e) { /* keep HTTP verdict */ }
        return { channel: 'wasender', ok, detail: body.slice(0, 260) }
      } catch (e: any) {
        if (attempt === 1) return { channel: 'wasender', ok: false, detail: String(e).slice(0, 200) }
      }
    }
    return { channel: 'wasender', ok: false, detail: 'send failed' }
  }

  if (token && phoneId) {
    const template = env.WHATSAPP_TEMPLATE || 'guest_waiting_alert'
    const lang = env.WHATSAPP_TEMPLATE_LANG || 'en'
    const r = await fetch('https://graph.facebook.com/v21.0/' + phoneId + '/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: JSON.stringify({
        messaging_product: 'whatsapp',
        to: contact.phone,
        type: 'template',
        template: {
          name: template,
          language: { code: lang },
          components: [{ type: 'body', parameters: templateParams.map(p => ({ type: 'text', text: p })) }]
        }
      })
    })
    const body = await r.text()
    return { channel: 'cloud-api', ok: r.ok, detail: body.slice(0, 300) }
  }

  if (contact.callmebot_key) {
    const url = 'https://api.callmebot.com/whatsapp.php?phone=' + encodeURIComponent('+' + contact.phone) +
                '&text=' + encodeURIComponent(text) + '&apikey=' + encodeURIComponent(contact.callmebot_key)
    const r = await fetch(url)
    const body = await r.text()
    return { channel: 'callmebot', ok: r.ok, detail: body.slice(0, 300) }
  }

  return { channel: 'none', ok: false, detail: 'No WhatsApp channel configured' }
}

// Escalation ladder: up to four levels, each with its own start time, its own
// rhythm and its own people. Level 1 is the duty phone; if nobody answers,
// level 2 starts hammering another number every minute, then 3, then 4.
const LEVEL_TONE: Record<number, string> = {
  1: '🔔 Old Palace — guest waiting',
  2: '⚠️ LEVEL 2 — still no reply to a guest',
  3: '🚨 LEVEL 3 — URGENT: guest ignored',
  4: '🆘 FINAL ESCALATION — guest ignored'
}

async function runEscalations(env: any, DB: any) {
  const s = await DB.prepare('SELECT * FROM escalation_settings WHERE property_id = 1').first()
  if (!s || s.enabled !== 1) return

  const levelRows = await DB.prepare(
    'SELECT level, start_after_minutes, repeat_minutes, max_alerts FROM escalation_levels WHERE property_id = 1 ORDER BY level'
  ).all()
  const levels = (levelRows.results || []).filter((l: any) => l.level >= 1 && l.level <= 4)
  if (!levels.length) return

  const contacts = await DB.prepare(
    'SELECT * FROM escalation_contacts WHERE property_id = 1 AND is_active = 1'
  ).all()
  const byLevel: Record<number, any[]> = {}
  for (const ct of (contacts.results || [])) {
    const lv = ct.level || 1
    if (!byLevel[lv]) byLevel[lv] = []
    byLevel[lv].push(ct)
  }
  if (!Object.keys(byLevel).length) return

  const firstStart = Math.min(...levels.map((l: any) => l.start_after_minutes || 5))

  const stale = await DB.prepare(`
    SELECT c.conversation_id, c.session_id, c.guest_name, c.room_number,
      (SELECT MAX(m.created_at) FROM chatbot_messages m
        WHERE m.conversation_id = c.conversation_id AND m.role = 'user') as last_user_at,
      (SELECT m.content FROM chatbot_messages m
        WHERE m.conversation_id = c.conversation_id AND m.role = 'user'
        ORDER BY m.created_at DESC, m.rowid DESC LIMIT 1) as last_text
    FROM chatbot_conversations c
    WHERE c.property_id = 1
      AND EXISTS (
        SELECT 1 FROM chatbot_messages m
        WHERE m.conversation_id = c.conversation_id
          AND m.role = 'user'
          AND m.created_at > datetime('now', '-6 hours')
          AND m.created_at <= datetime('now', '-' || ? || ' minutes')
          AND (c.staff_ack_at IS NULL OR m.created_at > c.staff_ack_at)
      )
    LIMIT 5
  `).bind(firstStart).all()

  for (const conv of (stale.results || [])) {
    const waitedRow = await DB.prepare(
      `SELECT CAST((julianday('now') - julianday(?)) * 1440 AS INTEGER) as mins`
    ).bind(conv.last_user_at).first()
    const waited = (waitedRow && waitedRow.mins) || 0

    const who = conv.guest_name || 'A guest'
    const room = conv.room_number ? 'Room ' + conv.room_number : 'room not linked'
    const msg = String(conv.last_text || '').slice(0, 120)

    for (const lvl of levels) {
      const L = lvl.level
      const recipients = byLevel[L]
      if (!recipients || !recipients.length) continue
      if (waited < (lvl.start_after_minutes || 5)) continue

      // Per-level throttle. Counting every attempt (not just successes) so a
      // broken channel can never loop-spam once it comes back.
      const prior = await DB.prepare(`
        SELECT COUNT(*) as n, MAX(sent_at) as last_at FROM escalation_log
        WHERE session_id = ? AND level = ? AND sent_at > ?
      `).bind(conv.session_id, L, conv.last_user_at).first()

      if (((prior && prior.n) || 0) >= (lvl.max_alerts || 3)) continue
      if (prior && prior.last_at) {
        const recent = await DB.prepare(
          `SELECT 1 AS active WHERE datetime(?) > datetime('now', '-' || ? || ' minutes')`
        ).bind(prior.last_at, lvl.repeat_minutes || 10).first()
        if (recent) continue
      }

      const text = (LEVEL_TONE[L] || LEVEL_TONE[1]) + ' ' + waited + ' min with no reply\n' +
                   who + ' (' + room + ')\n"' + msg + '"\nOpen the Ops app to answer.'

      for (const contact of recipients) {
        try {
          const res = await sendWhatsApp(env, contact, text, [who + ' (' + room + ')', String(waited), msg])
          await DB.prepare(`
            INSERT INTO escalation_log (property_id, session_id, contact_phone, channel, status, detail, level)
            VALUES (1, ?, ?, ?, ?, ?, ?)
          `).bind(conv.session_id, contact.phone, res.channel, res.ok ? 'sent' : 'failed', res.detail, L).run()
        } catch (e: any) {
          await DB.prepare(`
            INSERT INTO escalation_log (property_id, session_id, contact_phone, channel, status, detail, level)
            VALUES (1, ?, ?, 'error', 'failed', ?, ?)
          `).bind(conv.session_id, contact.phone, String(e).slice(0, 200), L).run()
        }
      }
    }
  }
}

// Is the WhatsApp channel genuinely able to send right now? A saved token is
// not enough — WaSender also needs a linked WhatsApp session behind it.
async function whatsappHealth(env: any, DB?: any) {
  if (env.WASENDER_TOKEN) {
    // The free plan allows only 1 request/minute, and an alert must never lose
    // that slot to a status check — so the result is cached for 10 minutes.
    if (DB) {
      try {
        const cached = await DB.prepare(`
          SELECT state, note FROM wasender_health
          WHERE id = 1 AND checked_at > datetime('now', '-10 minutes')
        `).first()
        if (cached) return { channel: 'WaSender', state: cached.state, note: cached.note || '' }
      } catch (e) { /* table may not exist yet */ }
    }
    try {
      const r = await fetch('https://www.wasenderapi.com/api/status', {
        headers: { 'Authorization': 'Bearer ' + env.WASENDER_TOKEN }
      })
      const body = await r.text()
      let state = 'error'
      let note = body.slice(0, 160)
      if (r.ok) { state = 'ready'; note = '' }
      else if (r.status === 429) {
        // Out of quota this minute, not broken — keep the previous verdict
        state = 'ready'
        note = ''
      } else if (/session not found/i.test(body)) {
        state = 'no_session'
        note = 'No WhatsApp number is linked in WaSender yet — scan the QR in your WaSender dashboard, then paste that session\'s API key here.'
      } else if (/invalid api key/i.test(body)) {
        state = 'bad_key'
        note = 'WaSender rejected this key. Use the key from the WhatsApp session page (the key icon), not the account token.'
      }
      if (DB) {
        try {
          await DB.prepare(`
            INSERT INTO wasender_health (id, state, note, checked_at) VALUES (1, ?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(id) DO UPDATE SET state = excluded.state, note = excluded.note, checked_at = CURRENT_TIMESTAMP
          `).bind(state, note).run()
        } catch (e) { /* cache is best effort */ }
      }
      return { channel: 'WaSender', state, note }
    } catch (e) {
      return { channel: 'WaSender', state: 'error', note: 'Could not reach WaSender' }
    }
  }
  if (env.WHATSAPP_TOKEN && env.WHATSAPP_PHONE_ID) {
    return { channel: 'Meta Cloud API', state: 'ready', note: '' }
  }
  return { channel: '', state: 'none', note: '' }
}

app.get('/api/staff/escalation/config', async (c) => {
  const { DB } = c.env
  try {
    const health = await whatsappHealth(c.env, DB)
    const s = await DB.prepare('SELECT * FROM escalation_settings WHERE property_id = 1').first()
    const contacts = await DB.prepare('SELECT * FROM escalation_contacts WHERE property_id = 1 ORDER BY contact_id').all()
    const levels = await DB.prepare('SELECT level, start_after_minutes, repeat_minutes, max_alerts FROM escalation_levels WHERE property_id = 1 ORDER BY level').all()
    const log = await DB.prepare(`
      SELECT session_id, contact_phone, channel, status, detail, sent_at, level
      FROM escalation_log ORDER BY log_id DESC LIMIT 25
    `).all()
    return c.json({
      success: true,
      settings: s || {},
      contacts: contacts.results || [],
      levels: levels.results || [],
      log: log.results || [],
      whatsapp_ready: health.state === 'ready',
      channel: health.channel,
      channel_state: health.state,
      channel_note: health.note
    })
  } catch (e) {
    return c.json({ success: false, error: 'failed' }, 500)
  }
})

// WaSender webhook: a manager replying on WhatsApp closes the loop.
// If the reply comes from a number we escalate to, treat it as an
// acknowledgement — the phone stops ringing and repeat alerts stop.
app.post('/api/staff/wasender-webhook', async (c) => {
  const { DB } = c.env
  try {
    // "Anyone with this key can fake events" — so reject anything unsigned
    const secret = c.env.WASENDER_WEBHOOK_SECRET
    if (secret) {
      const sig = c.req.header('X-Webhook-Signature') || c.req.header('x-webhook-signature') || ''
      if (sig !== secret) return c.json({ success: false, error: 'bad signature' }, 401)
    }

    const payload = await c.req.json().catch(() => ({}))
    const flat = JSON.stringify(payload)

    // Ignore our own outgoing messages
    if (/"fromMe"\s*:\s*true/.test(flat)) return c.json({ success: true, ignored: 'outgoing' })

    // Pull the sender's number out of whatever shape the event arrives in
    const jid = (flat.match(/"(?:remoteJid|from|jid|sender)"\s*:\s*"(\d{6,})@/) || [])[1] || ''
    if (!jid) return c.json({ success: true, ignored: 'no sender' })

    const contact = await DB.prepare(
      'SELECT contact_id, name, phone FROM escalation_contacts WHERE property_id = 1 AND is_active = 1 AND phone = ?'
    ).bind(jid).first()
    if (!contact) return c.json({ success: true, ignored: 'not an escalation contact' })

    const text = (flat.match(/"(?:conversation|text|body)"\s*:\s*"([^"]{1,200})"/) || [])[1] || ''

    // Acknowledge everything outstanding, exactly like tapping Acknowledge
    await DB.prepare("UPDATE chatbot_conversations SET staff_ack_at = datetime('now') WHERE property_id = 1").run()
    await DB.prepare('UPDATE feedback_submissions SET is_read = 1 WHERE property_id = 1 AND is_read = 0').run()
    await DB.prepare("UPDATE staff_test_ring SET until = datetime('now', '-1 second') WHERE id = 1").run()
    await DB.prepare(`
      INSERT INTO escalation_log (property_id, session_id, contact_phone, channel, status, detail)
      VALUES (1, 'whatsapp-reply', ?, 'wasender', 'acknowledged', ?)
    `).bind(contact.phone, ((contact.name || 'Manager') + ' replied: ' + text).slice(0, 200)).run()

    return c.json({ success: true, acknowledged_by: contact.name || contact.phone })
  } catch (e) {
    // Always 200 quickly: a webhook that errors gets disabled by the provider
    return c.json({ success: true })
  }
})

app.post('/api/staff/escalation/settings', async (c) => {
  const { DB } = c.env
  try {
    const b = await c.req.json()
    await DB.prepare(`
      INSERT INTO escalation_settings (property_id, enabled, delay_minutes, repeat_minutes, max_alerts)
      VALUES (1, ?, ?, ?, ?)
      ON CONFLICT(property_id) DO UPDATE SET
        enabled = excluded.enabled, delay_minutes = excluded.delay_minutes,
        repeat_minutes = excluded.repeat_minutes, max_alerts = excluded.max_alerts
    `).bind(b.enabled ? 1 : 0, b.delay_minutes || 5, b.repeat_minutes || 10, b.max_alerts || 3).run()
    // Ladder tuning: each level's start / rhythm / cap
    for (const lv of (Array.isArray(b.levels) ? b.levels : [])) {
      const L = Math.min(4, Math.max(1, parseInt(lv.level, 10) || 0))
      if (!L) continue
      await DB.prepare(`
        INSERT INTO escalation_levels (property_id, level, start_after_minutes, repeat_minutes, max_alerts)
        VALUES (1, ?, ?, ?, ?)
        ON CONFLICT(property_id, level) DO UPDATE SET
          start_after_minutes = excluded.start_after_minutes,
          repeat_minutes = excluded.repeat_minutes,
          max_alerts = excluded.max_alerts
      `).bind(
        L,
        Math.max(0, parseInt(lv.start_after_minutes, 10) || 0),
        Math.max(1, parseInt(lv.repeat_minutes, 10) || 1),
        Math.max(1, parseInt(lv.max_alerts, 10) || 1)
      ).run()
    }
    return c.json({ success: true })
  } catch (e) { return c.json({ success: false }, 500) }
})

app.post('/api/staff/escalation/contacts', async (c) => {
  const { DB } = c.env
  try {
    const b = await c.req.json()
    const phone = String(b.phone || '').replace(/[^0-9]/g, '')
    if (!phone) return c.json({ success: false, error: 'phone required' }, 400)
    const level = Math.min(4, Math.max(1, parseInt(b.level, 10) || 1))
    await DB.prepare(`
      INSERT INTO escalation_contacts (property_id, name, phone, callmebot_key, is_active, level)
      VALUES (1, ?, ?, ?, 1, ?)
    `).bind(b.name || '', phone, b.callmebot_key || null, level).run()
    return c.json({ success: true })
  } catch (e) { return c.json({ success: false }, 500) }
})

