  const { DB } = c.env
  try {
    await DB.prepare('DELETE FROM escalation_contacts WHERE contact_id = ?').bind(c.req.param('id')).run()
    return c.json({ success: true })
  } catch (e) { return c.json({ success: false }, 500) }
