app.post('/api/staff/escalation/test', async (c) => {
  const { DB } = c.env
  try {
    const contacts = await DB.prepare('SELECT * FROM escalation_contacts WHERE property_id = 1 AND is_active = 1').all()
    const list = contacts.results || []
    if (!list.length) return c.json({ success: false, error: 'No escalation numbers saved yet' }, 400)
    const results: any[] = []
    for (const contact of list) {
      const res = await sendWhatsApp(c.env, contact,
        '🔔 Old Palace test alert — WhatsApp escalation is working. No action needed.',
        ['Test Guest (Room 000)', '5', 'This is a test of the escalation alert'])
      await DB.prepare(`
        INSERT INTO escalation_log (property_id, session_id, contact_phone, channel, status, detail)
        VALUES (1, 'test', ?, ?, ?, ?)
      `).bind(contact.phone, res.channel, res.ok ? 'sent' : 'failed', res.detail).run()
      results.push({ phone: contact.phone, ok: res.ok, channel: res.channel, detail: res.detail })
    }
    return c.json({ success: true, results })
  } catch (e: any) {
    return c.json({ success: false, error: String(e).slice(0, 200) }, 500)
  }
})

// The phone's native watcher checks in here every poll, so the console can
// show whether alerting is actually alive on the device.
app.post('/api/staff/ring-heartbeat', async (c) => {
  const { DB } = c.env
  try {
    const b = await c.req.json().catch(() => ({}))
    await DB.prepare(`
      INSERT INTO staff_watchdog (device, property_id, app_version, ringing, last_seen)
      VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
      ON CONFLICT(device) DO UPDATE SET
        app_version = excluded.app_version,
        ringing = excluded.ringing,
        last_seen = CURRENT_TIMESTAMP
    `).bind(b.device || 'unknown', b.property_id || 1, b.app || '', b.ringing ? 1 : 0).run()
    return c.json({ success: true })
  } catch (e) {
    return c.json({ success: false }, 500)
  }
})

app.get('/api/staff/watchdog', async (c) => {
  const { DB } = c.env
  try {
    const rows = await DB.prepare(`
      SELECT device, app_version, ringing, last_seen,
             CAST((julianday('now') - julianday(last_seen)) * 86400 AS INTEGER) as seconds_ago
      FROM staff_watchdog ORDER BY last_seen DESC LIMIT 10
    `).all()
    return c.json({ success: true, devices: rows.results || [] })
  } catch (e) {
    return c.json({ success: false, devices: [] })
  }
})

