// ============================================
// À LA CARTE ANALYTICS API
// ============================================

app.get('/api/analytics/alacarte', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const period = c.req.query('period') || 'today' // today, week, month
  const restaurant_id = c.req.query('restaurant_id') // optional filter
  
  try {
    // Calculate date range based on period
    let dateFilter = ''
    let startDate = ''
    let endDate = ''
    
    if (period.startsWith('custom:')) {
      // Parse custom date range: custom:YYYY-MM-DD:YYYY-MM-DD
      const parts = period.split(':')
      if (parts.length === 3) {
        startDate = parts[1]
        endDate = parts[2]
        dateFilter = `'${startDate}'`
      } else {
        throw new Error('Invalid custom date format. Expected: custom:YYYY-MM-DD:YYYY-MM-DD')
      }
    } else if (period === 'today') {
      dateFilter = "date('now')"
    } else if (period === 'week') {
      dateFilter = "date('now', '-7 days')"
    } else if (period === 'month') {
      dateFilter = "date('now', '-30 days')"
    } else if (period === 'all') {
      dateFilter = "date('2000-01-01')" // All historical data
    } else {
      // Default to today
      dateFilter = "date('now')"
    }
    
    // Build date condition for custom range
    let dateCondition = `v.reservation_date >= ${dateFilter}`
    if (startDate && endDate) {
      dateCondition = `v.reservation_date BETWEEN '${startDate}' AND '${endDate}'`
    }
    
    // Build restaurant filter
    let restaurantFilter = ''
    if (restaurant_id) {
      restaurantFilter = `AND v.restaurant_id = ${restaurant_id}`
    }
    
    // Get key metrics
    const metrics = await DB.prepare(`
      SELECT 
        COUNT(DISTINCT v.voucher_id) as total_orders,
        SUM(v.total_cost) as total_revenue,
        AVG(v.total_cost) as avg_order_value,
        COUNT(DISTINCT v.pass_id) as unique_guests
      FROM alacarte_vouchers v
      WHERE v.property_id = ?
        AND ${dateCondition}
        ${restaurantFilter}
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served')
    `).bind(property_id).first()
    
    // Get orders by time of day
    const ordersByTime = await DB.prepare(`
      SELECT 
        CAST(substr(v.reservation_time, 1, 2) AS INTEGER) as hour,
        COUNT(*) as order_count
      FROM alacarte_vouchers v
      WHERE v.property_id = ?
        AND ${dateCondition}
        ${restaurantFilter}
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served')
      GROUP BY hour
      ORDER BY hour
    `).bind(property_id).all()
    
    // Get top selling items
    const topItems = await DB.prepare(`
      SELECT 
        m.item_name,
        m.category,
        m.cost_to_hotel as price,
        m.is_premium,
        COUNT(*) as order_count,
        SUM(m.cost_to_hotel) as total_revenue
      FROM alacarte_vouchers v,
           json_each(v.preorder_item_ids) je
      JOIN alacarte_menu_items m ON m.item_id = je.value
      WHERE v.property_id = ?
        AND ${dateCondition}
        ${restaurantFilter}
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served')
      GROUP BY m.item_id
      ORDER BY order_count DESC
      LIMIT 10
    `).bind(property_id).all()
    
    // Get revenue trend (daily)
    const revenueTrend = await DB.prepare(`
      SELECT 
        v.reservation_date as date,
        COUNT(*) as order_count,
        SUM(v.total_cost) as revenue
      FROM alacarte_vouchers v
      WHERE v.property_id = ?
        AND ${dateCondition}
        ${restaurantFilter}
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served')
      GROUP BY v.reservation_date
      ORDER BY v.reservation_date
    `).bind(property_id).all()
    
    // Get popular time slots
    const popularTime = await DB.prepare(`
      SELECT 
        v.reservation_time,
        COUNT(*) as booking_count
      FROM alacarte_vouchers v
      WHERE v.property_id = ?
        AND ${dateCondition}
        ${restaurantFilter}
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served')
      GROUP BY v.reservation_time
      ORDER BY booking_count DESC
      LIMIT 1
    `).bind(property_id).first()
    
    // Get restaurant breakdown
    const restaurantStats = await DB.prepare(`
      SELECT 
        ho.offering_id,
        ho.title_en as restaurant_name,
        COUNT(*) as order_count,
        SUM(v.total_cost) as revenue
      FROM alacarte_vouchers v
      JOIN hotel_offerings ho ON v.restaurant_id = ho.offering_id
      WHERE v.property_id = ?
        AND v.reservation_date >= ${dateFilter}
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served')
      GROUP BY v.restaurant_id
      ORDER BY order_count DESC
    `).bind(property_id).all()
    
    return c.json({
      success: true,
      period,
      metrics: {
        total_orders: metrics?.total_orders || 0,
        total_revenue: metrics?.total_revenue || 0,
        avg_order_value: metrics?.avg_order_value || 0,
        unique_guests: metrics?.unique_guests || 0,
        popular_time: popularTime?.reservation_time || 'N/A'
      },
      charts: {
        top_items: topItems.results || [],
        revenue_trend: revenueTrend.results || [],
        orders_by_time: ordersByTime.results || []
      },
      restaurants: restaurantStats.results || []
    })
  } catch (error) {
    console.error('Analytics error:', error)
    return c.json({
      success: false,
      error: 'Failed to load analytics',
      details: error.message
    }, 500)
  }
})

// Detailed Order History API
app.get('/api/analytics/alacarte/orders', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const { period = 'month' } = c.req.query()
  
  try {
    // Calculate date range based on period
    let dateCondition = ''
    let dateConditionWaiter = ''
    if (period === 'today') {
      dateCondition = "AND DATE(v.created_at) = DATE('now')"
      dateConditionWaiter = "AND DATE(w.created_at) = DATE('now')"
    } else if (period === 'week') {
      dateCondition = "AND v.created_at >= datetime('now', '-7 days')"
      dateConditionWaiter = "AND w.created_at >= datetime('now', '-7 days')"
    } else if (period === 'month') {
      dateCondition = "AND v.created_at >= datetime('now', '-30 days')"
      dateConditionWaiter = "AND w.created_at >= datetime('now', '-30 days')"
    } else if (period === 'all') {
      // No date filter - show all orders
      dateCondition = ""
      dateConditionWaiter = ""
    } else if (period.startsWith('custom:')) {
      // Handle custom date range: custom:2026-03-14:2026-03-14
      const parts = period.split(':')
      if (parts.length === 3) {
        dateCondition = `AND DATE(v.created_at) >= '${parts[1]}' AND DATE(v.created_at) <= '${parts[2]}'`
        dateConditionWaiter = `AND DATE(w.created_at) >= '${parts[1]}' AND DATE(w.created_at) <= '${parts[2]}'`
      }
    }
    
    // Query combining both alacarte_vouchers and waiter_orders
    const query = `
      SELECT * FROM (
        SELECT 
          v.voucher_id as order_id,
          v.voucher_code,
          v.voucher_code as guest_name,
          v.table_number as room_number,
          v.party_size,
          v.reservation_date,
          v.reservation_time,
          v.status,
          v.preorder_item_ids as items,
          v.total_cost,
          v.special_requests,
          v.created_at,
          v.checked_in_at,
          r.title_en as restaurant_name,
          v.checked_in_by as created_by_staff,
          'voucher' as order_type
        FROM alacarte_vouchers v
        LEFT JOIN hotel_offerings r ON v.restaurant_id = r.offering_id
        WHERE v.property_id = ?
        ${dateCondition}
        
        UNION ALL
        
        SELECT 
          w.order_id,
          'WALK-' || w.order_id as voucher_code,
          w.guest_name,
          w.room_number,
          w.party_size,
          DATE(w.created_at) as reservation_date,
          TIME(w.created_at) as reservation_time,
          w.status,
          w.items,
          w.total_cost,
          NULL as special_requests,
          w.created_at,
          NULL as checked_in_at,
          r.title_en as restaurant_name,
          u.first_name || ' ' || u.last_name as created_by_staff,
          'waiter' as order_type
        FROM waiter_orders w
        LEFT JOIN hotel_offerings r ON w.restaurant_id = r.offering_id
        LEFT JOIN users u ON w.waiter_id = u.user_id
        WHERE 1=1
        ${dateConditionWaiter}
      )
      ORDER BY created_at DESC
      LIMIT 500
    `
    
    const orders = await DB.prepare(query).bind(property_id).all()
    
    // Format orders and fetch item details
    const formattedOrders = await Promise.all((orders.results || []).map(async (order) => {
      let parsedItems = []
      
      // Parse items based on order type
      if (order.order_type === 'voucher' && order.items) {
        try {
          const itemsData = JSON.parse(order.items)
          
          // Extract item IDs
          const itemIds = itemsData.map(item => {
            if (typeof item === 'object' && item.item_id) {
              return item.item_id
            }
            return item
          })
          
          // Create quantity map
          const quantityMap = {}
          itemsData.forEach(item => {
            if (typeof item === 'object' && item.item_id) {
              quantityMap[item.item_id] = item.quantity || 1
            } else {
              quantityMap[item] = 1
            }
          })
          
          // Separate set menu and extra charge items
          const setMenuIds = []
          const extraChargeIds = []
          
          itemIds.forEach(id => {
            if (typeof id === 'string' && id.startsWith('rm_')) {
              const numericId = parseInt(id.substring(3))
              if (!isNaN(numericId)) {
                extraChargeIds.push({ original: id, numeric: numericId })
              }
            } else {
              setMenuIds.push(id)
            }
          })
          
          // Fetch set menu items
          if (setMenuIds.length > 0) {
            const setMenuItems = await Promise.all(
              setMenuIds.map(async (id) => {
                const result = await DB.prepare(
                  'SELECT item_id, item_name, category FROM alacarte_menu_items WHERE item_id = ?'
                ).bind(id).first()
                return result ? { ...result, quantity: quantityMap[id] || 1, extraCharge: false } : null
              })
            )
            parsedItems.push(...setMenuItems.filter(Boolean))
          }
          
          // Fetch extra charge items
          if (extraChargeIds.length > 0) {
            const extraItems = await Promise.all(
              extraChargeIds.map(async ({ original, numeric }) => {
                const result = await DB.prepare(
                  `SELECT 
                    mi.item_id, 
                    mi.item_name, 
                    mc.category_name as category, 
                    mi.price 
                  FROM menu_items mi
                  LEFT JOIN menu_categories mc ON mi.category_id = mc.category_id
                  WHERE mi.item_id = ?`
                ).bind(numeric).first()
                return result ? { 
                  item_id: original, 
                  item_name: result.item_name, 
                  category: result.category,
                  quantity: quantityMap[original] || 1,
                  extraCharge: true,
                  price: result.price
                } : null
              })
            )
            parsedItems.push(...extraItems.filter(Boolean))
          }
        } catch (e) {
          console.error('Failed to parse voucher items:', e)
        }
      } else if (order.order_type === 'waiter' && order.items) {
        // Waiter orders already have items as JSON
        try {
          parsedItems = JSON.parse(order.items)
        } catch (e) {
          console.error('Failed to parse waiter items:', e)
        }
      }
      
      return {
        ...order,
        voucher_id: order.order_id,
        created_by_staff: order.created_by_staff || 'System',
        items: JSON.stringify(parsedItems) // Convert back to JSON string for frontend
      }
    }))
    
    return c.json({
      success: true,
      orders: formattedOrders,
      total: formattedOrders.length
    })
  } catch (error) {
    console.error('Order history error:', error)
    return c.json({
      success: false,
      error: 'Failed to load order history',
      details: error.message
    }, 500)
  }
})

// Staff Performance Analytics API
app.get('/api/analytics/staff-performance', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const { period = 'month', start_date, end_date } = c.req.query()
  
  try {
    // Calculate date range
    let dateCondition = ''
    let params = [property_id]
    
    if (start_date && end_date) {
      dateCondition = 'AND v.reservation_date >= ? AND v.reservation_date <= ?'
      params.push(start_date, end_date)
    } else if (period === 'today') {
      dateCondition = 'AND v.reservation_date = DATE("now")'
    } else if (period === 'week') {
      dateCondition = 'AND v.reservation_date >= DATE("now", "-7 days")'
    } else if (period === 'month') {
      dateCondition = 'AND v.reservation_date >= DATE("now", "-30 days")'
    }
    
    // Staff performance summary
    const staffPerformance = await DB.prepare(`
      SELECT 
        u.user_id,
        u.first_name || ' ' || u.last_name AS staff_name,
        u.email,
        u.role,
        COUNT(DISTINCT v.voucher_id) AS total_bookings,
        SUM(v.party_size) AS total_guests,
        COUNT(CASE WHEN v.total_cost > 0 THEN 1 END) AS upsell_count,
        ROUND(COUNT(CASE WHEN v.total_cost > 0 THEN 1 END) * 100.0 / NULLIF(COUNT(v.voucher_id), 0), 1) AS upsell_rate,
        SUM(v.total_cost) AS total_upsell_revenue,
        ROUND(AVG(v.total_cost), 2) AS avg_upsell_per_booking,
        COUNT(DISTINCT v.reservation_date) AS active_days
      FROM users u
      LEFT JOIN alacarte_vouchers v ON u.user_id = v.created_by_staff_id
        AND v.property_id = ?
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served', 'used')
        ${dateCondition}
      WHERE u.property_id = ? AND u.status = 'active'
      GROUP BY u.user_id, u.first_name, u.last_name, u.email, u.role
      HAVING total_bookings > 0
      ORDER BY total_upsell_revenue DESC, upsell_rate DESC
    `).bind(...params, property_id).all()
    
    // Extra charge items breakdown (items from menu_items table with rm_ prefix)
    const extraChargeStats = await DB.prepare(`
      SELECT 
        mi.item_name,
        mc.category_name AS category,
        mi.price AS cost_to_hotel,
        COUNT(*) AS times_sold,
        SUM(CAST(json_extract(items.value, '$.quantity') AS INTEGER)) AS total_quantity,
        SUM(mi.price * CAST(json_extract(items.value, '$.quantity') AS INTEGER)) AS total_revenue
      FROM alacarte_vouchers v
      CROSS JOIN json_each(v.preorder_item_ids) AS items
      INNER JOIN menu_items mi ON mi.item_id = CAST(
        CASE 
          WHEN json_extract(items.value, '$.item_id') LIKE 'rm_%' 
          THEN SUBSTR(json_extract(items.value, '$.item_id'), 4)
          ELSE NULL
        END AS INTEGER
      )
      LEFT JOIN menu_categories mc ON mi.category_id = mc.category_id
      WHERE v.property_id = ?
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served', 'used')
        AND v.created_by_staff_id IS NOT NULL
        AND json_extract(items.value, '$.item_id') LIKE 'rm_%'
        AND mi.price > 0
        ${dateCondition}
      GROUP BY mi.item_id, mi.item_name, mc.category_name, mi.price
      ORDER BY total_revenue DESC
      LIMIT 20
    `).bind(...params).all()
    
    // Daily staff performance trend
    const dailyTrend = await DB.prepare(`
      SELECT 
        v.reservation_date,
        COUNT(DISTINCT v.voucher_id) AS total_bookings,
        COUNT(CASE WHEN v.total_cost > 0 THEN 1 END) AS bookings_with_upsell,
        SUM(v.total_cost) AS daily_revenue,
        COUNT(DISTINCT v.created_by_staff_id) AS active_staff_count
      FROM alacarte_vouchers v
      WHERE v.property_id = ?
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served', 'used')
        AND v.created_by_staff_id IS NOT NULL
        ${dateCondition}
      GROUP BY v.reservation_date
      ORDER BY v.reservation_date ASC
    `).bind(...params).all()
    
    // Top upsellers (staff with highest conversion rates)
    const topUpsellers = await DB.prepare(`
      SELECT 
        u.user_id,
        u.first_name || ' ' || u.last_name AS staff_name,
        COUNT(DISTINCT v.voucher_id) AS total_bookings,
        COUNT(CASE WHEN v.total_cost > 0 THEN 1 END) AS upsell_count,
        ROUND(COUNT(CASE WHEN v.total_cost > 0 THEN 1 END) * 100.0 / COUNT(v.voucher_id), 1) AS upsell_rate,
        SUM(v.total_cost) AS total_revenue
      FROM users u
      INNER JOIN alacarte_vouchers v ON u.user_id = v.created_by_staff_id
      WHERE v.property_id = ?
        AND v.status IN ('confirmed', 'preparing', 'ready', 'served', 'used')
        ${dateCondition}
      GROUP BY u.user_id, u.first_name, u.last_name
      HAVING total_bookings >= 5
      ORDER BY upsell_rate DESC, total_revenue DESC
      LIMIT 10
    `).bind(...params).all()
    
    return c.json({
      success: true,
      period: period,
      date_range: { start_date, end_date },
      staff_performance: staffPerformance.results || [],
      extra_charge_items: extraChargeStats.results || [],
      daily_trend: dailyTrend.results || [],
      top_upsellers: topUpsellers.results || []
    })
  } catch (error) {
    console.error('Staff analytics error:', error)
    return c.json({
      success: false,
      error: 'Failed to load staff analytics',
      details: error.message
    }, 500)
  }
})

// Staff Management API - Add new staff
app.post('/api/admin/staff', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const { email, first_name, last_name, role = 'staff', password } = body
    
    if (!email || !first_name || !last_name || !password) {
      return c.json({ success: false, error: 'Missing required fields' }, 400)
    }
    
    // Check if email already exists
    const existing = await DB.prepare(`
      SELECT user_id FROM users WHERE email = ? AND property_id = ?
    `).bind(email, property_id).first()
    
    if (existing) {
      return c.json({ success: false, error: 'Email already exists' }, 400)
    }
    
    // Hash password (simple for demo - use bcrypt in production)
    const crypto = require('crypto')
    const password_hash = crypto.createHash('sha256').update(password).digest('hex')
    
    // Insert new staff member
    const result = await DB.prepare(`
      INSERT INTO users (
        email, password_hash, first_name, last_name, role, 
        property_id, status, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, 'active', CURRENT_TIMESTAMP)
    `).bind(email, password_hash, first_name, last_name, role, property_id).run()
    
    return c.json({
      success: true,
      user_id: result.meta.last_row_id,
      message: 'Staff member added successfully'
    })
  } catch (error) {
    console.error('Add staff error:', error)
    return c.json({ success: false, error: 'Failed to add staff member' }, 500)
  }
})

// Staff Management API - Update staff
app.put('/api/admin/staff/:user_id', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const { user_id } = c.req.param()
  
  try {
    const body = await c.req.json()
    const { first_name, last_name, role, status } = body
    
    // Update staff member
    await DB.prepare(`
      UPDATE users 
      SET first_name = COALESCE(?, first_name),
          last_name = COALESCE(?, last_name),
          role = COALESCE(?, role),
          status = COALESCE(?, status),
          updated_at = CURRENT_TIMESTAMP
      WHERE user_id = ? AND property_id = ?
    `).bind(first_name, last_name, role, status, user_id, property_id).run()
    
    return c.json({
      success: true,
      message: 'Staff member updated successfully'
    })
  } catch (error) {
    console.error('Update staff error:', error)
    return c.json({ success: false, error: 'Failed to update staff member' }, 500)
  }
})

// Staff Management API - Deactivate staff
app.delete('/api/admin/staff/:user_id', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const { user_id } = c.req.param()
  
  try {
    // Soft delete by setting status to inactive
    await DB.prepare(`
      UPDATE users 
      SET status = 'inactive',
          updated_at = CURRENT_TIMESTAMP
      WHERE user_id = ? AND property_id = ?
    `).bind(user_id, property_id).run()
    
    return c.json({
      success: true,
      message: 'Staff member deactivated successfully'
    })
  } catch (error) {
    console.error('Delete staff error:', error)
    return c.json({ success: false, error: 'Failed to deactivate staff member' }, 500)
  }
})

