// Get restaurant info
app.get('/api/restaurant/:restaurant_id/info', async (c) => {
  const { DB } = c.env
  const { restaurant_id } = c.req.param()
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const restaurant = await DB.prepare(`
      SELECT 
        offering_id, 
        title_en, 
        title_ar,
        short_description_en as description,
        full_description_en as full_description,
        price,
        currency
      FROM hotel_offerings
      WHERE offering_id = ? AND property_id = ?
    `).bind(restaurant_id, property_id).first()
    
    if (!restaurant) {
      return c.json({ success: false, error: 'Restaurant not found' }, 404)
    }
    
    return c.json({ success: true, restaurant })
  } catch (error) {
    console.error('Get restaurant info error:', error)
    return c.json({ success: false, error: 'Failed to get restaurant info' }, 500)
  }
})

// Get extra charge menu items
app.get('/api/restaurant/:restaurant_id/menu/extra-charge', async (c) => {
  const { DB } = c.env
  const { restaurant_id } = c.req.param()
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    // Get BOTH extra charge items from menu_items AND premium items from alacarte_menu_items
    
    // 1. Get extra charge items from menu_items table (the REAL restaurant menu with prices)
    const menuItems = await DB.prepare(`
      SELECT 
        mi.item_id,
        mi.item_name,
        mc.category_name as category,
        mi.description,
        mi.price as cost_to_hotel,
        0 as is_premium,
        mi.is_available,
        'menu_items' as source_table
      FROM menu_items mi
      LEFT JOIN menu_categories mc ON mi.category_id = mc.category_id
      LEFT JOIN restaurant_menus rm ON mc.menu_id = rm.menu_id
      WHERE rm.offering_id = ?
        AND mi.is_available = 1
        AND mi.price > 0
      ORDER BY mc.display_order, mi.display_order, mi.item_name
    `).bind(restaurant_id).all()
    
    // 2. Get premium items from alacarte_menu_items table (extra charge within set menu)
    const premiumItems = await DB.prepare(`
      SELECT 
        item_id,
        item_name,
        category,
        description,
        cost_to_hotel,
        1 as is_premium,
        is_available,
        'alacarte_menu_items' as source_table
      FROM alacarte_menu_items
      WHERE restaurant_id = ?
        AND is_available = 1
        AND is_premium = 1
        AND cost_to_hotel > 0
      ORDER BY category, display_order, item_name
    `).bind(restaurant_id).all()
    
    // Combine both lists
    const allItems = [...(menuItems.results || []), ...(premiumItems.results || [])]
    
    return c.json({
      success: true,
      items: allItems,
      count: allItems.length,
      breakdown: {
        menu_items: menuItems.results.length,
        premium_items: premiumItems.results.length
      }
    })
  } catch (error) {
    console.error('Get menu items error:', error)
    return c.json({ success: false, error: 'Failed to get menu items' }, 500)
  }
})

// Get tables with current status
app.get('/api/waiter/tables', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const { restaurant, property, date } = c.req.query()
  
  try {
    // Use provided date or default to today
    const filterDate = date || new Date().toISOString().split('T')[0]
    
    // Calculate max date (same day for single-day view)
    const maxDate = filterDate
    
    console.log(`📅 Waiter tables date filter: ${filterDate}`)
    
    // Get all tables for restaurant with position data
    const tables = await DB.prepare(`
      SELECT 
        rt.table_id,
        rt.table_number,
        rt.capacity,
        rt.position_x,
        rt.position_y,
        rt.width,
        rt.height,
        rt.shape
      FROM restaurant_tables rt
      WHERE rt.offering_id = ?
        AND rt.is_active = 1
      ORDER BY CAST(rt.table_number AS INTEGER)
    `).bind(restaurant).all()
    
    // Get waiter orders (only pending/confirmed/seated - not yet cleared)
    const waiterOrders = await DB.prepare(`
      SELECT table_id, order_id, guest_name, room_number, party_size, status, waiter_id
      FROM waiter_orders
      WHERE restaurant_id = ? 
        AND status IN ('pending', 'confirmed', 'seated', 'preparing', 'ready')
    `).bind(restaurant).all()
    
    // Get kitchen bookings for the selected date ONLY
    const kitchenBookings = await DB.prepare(`
      SELECT 
        av.table_number,
        av.special_requests,
        av.party_size,
        av.status,
        av.voucher_id,
        av.reservation_date,
        av.reservation_time,
        av.preorder_item_ids,
        av.created_at,
        av.checked_in_at,
        av.checked_in_by,
        dp.primary_guest_name as guest_name,
        dp.room_number
      FROM alacarte_vouchers av
      LEFT JOIN digital_passes dp ON av.pass_id = dp.pass_id
      WHERE av.restaurant_id = ?
        AND av.property_id = ?
        AND av.status IN ('confirmed', 'preparing', 'ready', 'checked_in')
        AND av.reservation_date = ?
      ORDER BY av.reservation_date, av.reservation_time
    `).bind(restaurant, property_id, filterDate).all()
    
    // Create maps for quick lookup
    const waiterOrderMap = new Map()
    for (const wo of waiterOrders.results) {
      waiterOrderMap.set(wo.table_id, wo)
    }
    
    const kitchenBookingMap = new Map()
    for (const kb of kitchenBookings.results) {
      if (kb.table_number) {
        // Use guest_name from digital_passes JOIN, fallback to special_requests parsing
        let guestName = kb.guest_name || 'Guest'
        let roomNumber = kb.room_number || null
        
        if (!kb.guest_name && kb.special_requests) {
          const guestMatch = kb.special_requests.match(/Guest:\s*([^,\n]+)/)
          if (guestMatch) {
            guestName = guestMatch[1].trim()
          }
        }
        
        // Extract room number from special_requests if not from digital_passes
        if (!roomNumber && kb.special_requests) {
          const roomMatch = kb.special_requests.match(/Room:\s*([^,\s\(\)]+)/)
          if (roomMatch) {
            roomNumber = roomMatch[1].trim()
          }
        }
        
        // Parse items for display
        const preorderItems = kb.preorder_item_ids ? JSON.parse(kb.preorder_item_ids) : []
        
        // Get booked by info from checked_in_by
        const bookedBy = kb.checked_in_by || 'Front Desk'
        
        kitchenBookingMap.set(kb.table_number, { 
          ...kb, 
          guest_name: guestName,
          room_number: roomNumber,
          items_count: preorderItems.length,
          booked_by: bookedBy
        })
      }
    }
    
    // Format response - match tables with orders/bookings
    const formattedTables = tables.results.map(t => {
      const baseTable = {
        table_id: t.table_id,
        table_number: t.table_number,
        capacity: t.capacity,
        position_x: t.position_x || 0,
        position_y: t.position_y || 0,
        width: t.width || 80,
        height: t.height || 80,
        shape: t.shape || 'rectangle',
        rotation: 0
      }
      
      // Check waiter order first (seated but not yet dining)
      const waiterOrder = waiterOrderMap.get(t.table_id)
      if (waiterOrder) {
        return {
          ...baseTable,
          current_order: {
            order_id: waiterOrder.order_id,
            guest_name: waiterOrder.guest_name,
            room_number: waiterOrder.room_number || null,
            party_size: waiterOrder.party_size,
            status: waiterOrder.status,
            source: 'waiter'
          }
        }
      }
      
      // Check kitchen booking (already dining)
      const kitchenBooking = kitchenBookingMap.get(t.table_number)
      if (kitchenBooking) {
        return {
          ...baseTable,
          current_order: {
            order_id: `kitchen-${kitchenBooking.voucher_id}`,
            guest_name: kitchenBooking.guest_name,
            room_number: kitchenBooking.room_number || null,
            party_size: kitchenBooking.party_size,
            status: kitchenBooking.status,
            source: 'kitchen',
            reservation_date: kitchenBooking.reservation_date,
            reservation_time: kitchenBooking.reservation_time,
            items_count: kitchenBooking.items_count,
            booked_by: kitchenBooking.booked_by
          }
        }
      }
      
      // Table is free
      return {
        ...baseTable,
        current_order: null
      }
    })
    
    return c.json({
      success: true,
      tables: formattedTables
    })
  } catch (error) {
    console.error('Get tables error:', error)
    return c.json({ success: false, error: 'Failed to get tables' }, 500)
  }
})

// Get waiter's active orders
app.get('/api/waiter/orders', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  const { restaurant, waiter, property, date, start_date, end_date } = c.req.query()
  
  try {
    // Calculate date range - show ALL historical orders
    const today = new Date()
    const minDate = new Date('2000-01-01') // Very old date to get all historical orders
    const minDateStr = minDate.toISOString().split('T')[0]
    
    const maxDate = new Date(today)
    maxDate.setDate(maxDate.getDate() + 30) // Future 30 days
    const maxDateStr = maxDate.toISOString().split('T')[0]
    
    // Determine start and end dates
    let startDateFilter = start_date || date || minDateStr // Default to all historical
    let endDateFilter = end_date || date || maxDateStr
    
    // Get waiter orders (if waiter=0, get all) - INCLUDE ALL STATUSES
    let waiterOrdersQuery = `
      SELECT 
        wo.order_id,
        wo.table_id,
        rt.table_number,
        wo.guest_name,
        wo.room_number,
        wo.party_size,
        wo.status,
        wo.items,
        wo.total_cost,
        wo.created_at,
        'waiter' as source
      FROM waiter_orders wo
      INNER JOIN restaurant_tables rt ON wo.table_id = rt.table_id
      WHERE wo.restaurant_id = ?
        AND DATE(wo.created_at) BETWEEN ? AND ?
    `
    
    const waiterOrdersParams = [restaurant, startDateFilter, endDateFilter]
    
    // Filter by waiter if specified and not 0
    if (waiter && waiter !== '0') {
      waiterOrdersQuery += ` AND wo.waiter_id = ?`
      waiterOrdersParams.push(waiter)
    }
    
    waiterOrdersQuery += ` ORDER BY wo.created_at DESC`
    
    const waiterOrders = await DB.prepare(waiterOrdersQuery).bind(...waiterOrdersParams).all()
    
    // Get kitchen orders (alacarte_vouchers) for this restaurant - ALL STATUSES
    const kitchenOrders = await DB.prepare(`
      SELECT 
        av.voucher_id,
        av.table_number,
        av.special_requests,
        av.party_size,
        av.status,
        av.preorder_item_ids,
        av.total_cost,
        av.reservation_time,
        av.reservation_date,
        av.created_at,
        av.checked_in_at,
        av.checked_in_by,
        dp.primary_guest_name as guest_name,
        dp.room_number,
        'kitchen' as source
      FROM alacarte_vouchers av
      LEFT JOIN digital_passes dp ON av.pass_id = dp.pass_id
      WHERE av.restaurant_id = ?
        AND av.property_id = ?
        AND av.reservation_date BETWEEN ? AND ?
      ORDER BY av.reservation_date DESC, av.created_at DESC
      LIMIT 200
    `).bind(restaurant, property_id, startDateFilter, endDateFilter).all()
    
    // Parse waiter orders
    const formattedWaiterOrders = waiterOrders.results.map(o => ({
      ...o,
      items: o.items ? JSON.parse(o.items) : []
    }))
    
    // Parse kitchen orders - need to look up menu items
    const formattedKitchenOrders = []
    for (const order of kitchenOrders.results) {
      try {
        const preorderItems = order.preorder_item_ids ? JSON.parse(order.preorder_item_ids) : []
        const items = []
        
        for (const item of preorderItems) {
          if (!item || !item.item_id) continue
          
          const itemId = String(item.item_id)
          let menuItem = null
          
          // Check if this is an extra charge item (starts with 'rm_' or is a string)
          if (itemId.startsWith('rm_')) {
            // Extra charge item from menu_items table
            const numericId = itemId.replace('rm_', '')
            menuItem = await DB.prepare(`
              SELECT item_name, price as cost
              FROM menu_items
              WHERE item_id = ?
            `).bind(numericId).first()
          } else {
            // Regular set menu item from alacarte_menu_items
            menuItem = await DB.prepare(`
              SELECT item_name, cost_to_hotel as cost
              FROM alacarte_menu_items
              WHERE item_id = ?
            `).bind(item.item_id).first()
          }
          
          if (menuItem) {
            items.push({
              item_id: item.item_id,
              item_name: menuItem.item_name || 'Unknown Item',
              quantity: parseInt(item.quantity) || 1,
              cost: parseFloat(menuItem.cost) || 0
            })
          }
        }
        
        // Extract guest name and room number from special_requests
        let guestName = 'Guest'
        let roomNumber = null
        if (order.special_requests) {
          const guestMatch = order.special_requests.match(/Guest:\s*([^,\n]+)/)
          if (guestMatch) {
            guestName = guestMatch[1].trim()
          }
          const roomMatch = order.special_requests.match(/Room:\s*(\d+)/)
          if (roomMatch) {
            roomNumber = roomMatch[1]
          }
        }
        
        const totalCost = order.total_cost ? parseFloat(order.total_cost) : items.reduce((sum, i) => sum + (i.cost * i.quantity), 0)
        
        formattedKitchenOrders.push({
          order_id: `kitchen-${order.voucher_id}`,
          table_number: order.table_number || 'N/A',
          guest_name: guestName,
          room_number: order.room_number || roomNumber,
          party_size: parseInt(order.party_size) || 1,
          status: order.status || 'confirmed',
          items: items,
          total_cost: totalCost,
          source: 'kitchen',
          reservation_date: order.reservation_date,
          reservation_time: order.reservation_time,
          created_at: order.created_at
        })
      } catch (err) {
        console.error('Error processing kitchen order:', order.voucher_id, err)
        // Skip this order if it fails
        continue
      }
    }
    
    // Combine and return
    const allOrders = [...formattedWaiterOrders, ...formattedKitchenOrders]
    
    return c.json({
      success: true,
      orders: allOrders,
      date_range: { from: today, to: maxDateStr }
    })
  } catch (error) {
    console.error('Get orders error:', error)
    return c.json({ success: false, error: 'Failed to get orders', message: error.message }, 500)
  }
})

// Get single waiter order with items
app.get('/api/waiter/order/:order_id', async (c) => {
  const { DB } = c.env
  const { order_id } = c.req.param()
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    // Fetch order details
    const orderResult = await DB.prepare(`
      SELECT 
        wo.order_id,
        wo.table_id,
        wo.restaurant_id,
        wo.waiter_id,
        wo.guest_name,
        wo.party_size,
        wo.items,
        wo.total_cost,
        wo.status,
        wo.created_at,
        rt.table_number
      FROM waiter_orders wo
      LEFT JOIN restaurant_tables rt ON wo.table_id = rt.table_id
      WHERE wo.order_id = ?
    `).bind(order_id).first()
    
    if (!orderResult) {
      return c.json({ success: false, error: 'Order not found' }, 404)
    }
    
    // Parse items
    const items = orderResult.items ? JSON.parse(orderResult.items) : []
    
    // Fetch item details
    const itemIds = items.map(i => i.item_id.replace('rm_', ''))
    const dishes = []
    
    if (itemIds.length > 0) {
      const placeholders = itemIds.map(() => '?').join(',')
      const itemsData = await DB.prepare(`
        SELECT item_id, item_name, price as cost
        FROM menu_items
        WHERE item_id IN (${placeholders})
      `).bind(...itemIds).all()
      
      // Map items with quantities
      for (const item of items) {
        const itemId = item.item_id.replace('rm_', '')
        const itemData = itemsData.results.find(i => i.item_id.toString() === itemId)
        if (itemData) {
          dishes.push({
            item_id: item.item_id,
            originalId: item.item_id,
            item_name: itemData.item_name,
            cost: itemData.cost || 0,
            quantity: item.quantity || 1
          })
        }
      }
    }
    
    return c.json({
      success: true,
      order: {
        ...orderResult,
        items: undefined, // Remove raw JSON
        dishes: dishes,
        source: 'waiter'
      }
    })
  } catch (error) {
    console.error('Error fetching waiter order:', error)
    return c.json({ success: false, error: 'Failed to fetch order' }, 500)
  }
})

// Delete/cancel order
app.delete('/api/waiter/order/:order_id', async (c) => {
  const { DB } = c.env
  const { order_id } = c.req.param()
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    // Check if it's a kitchen order (starts with "kitchen-")
    if (order_id.startsWith('kitchen-')) {
      const voucherId = order_id.replace('kitchen-', '')
      
      // Cancel the voucher (set status to 'cancelled')
      await DB.prepare(`
        UPDATE alacarte_vouchers
        SET status = 'cancelled',
            cancelled_at = CURRENT_TIMESTAMP,
            cancellation_reason = 'Cancelled by waiter'
        WHERE voucher_id = ?
      `).bind(voucherId).run()
      
      return c.json({ success: true, message: 'Kitchen order cancelled' })
    } else {
      // It's a waiter order - delete it
      await DB.prepare(`
        DELETE FROM waiter_orders
        WHERE order_id = ?
      `).bind(order_id).run()
      
      return c.json({ success: true, message: 'Waiter order deleted' })
    }
  } catch (error) {
    console.error('Delete order error:', error)
    return c.json({ success: false, error: 'Failed to delete order' }, 500)
  }
})

// Seat guests at table
app.post('/api/waiter/seat-guests', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const { table_id, restaurant_id, waiter_id, guest_name, room_number, party_size } = body
    
    if (!table_id || !restaurant_id || !waiter_id || !guest_name || !party_size) {
      return c.json({ success: false, error: 'Missing required fields' }, 400)
    }
    
    // Check if table has active order
    const existing = await DB.prepare(`
      SELECT order_id FROM waiter_orders 
      WHERE table_id = ? AND status IN ('pending', 'confirmed')
    `).bind(table_id).first()
    
    if (existing) {
      return c.json({ success: false, error: 'Table already has an active order' }, 400)
    }
    
    // Create new order with automatic check-in (waiter is seating them)
    const result = await DB.prepare(`
      INSERT INTO waiter_orders (
        table_id,
        restaurant_id,
        waiter_id,
        guest_name,
        room_number,
        party_size,
        items,
        total_cost,
        status,
        created_at
      ) VALUES (?, ?, ?, ?, ?, ?, '[]', 0, 'pending', CURRENT_TIMESTAMP)
    `).bind(table_id, restaurant_id, waiter_id, guest_name, room_number || null, party_size).run()
    
    const order = await DB.prepare(`
      SELECT * FROM waiter_orders WHERE order_id = ?
    `).bind(result.meta.last_row_id).first()
    
    return c.json({
      success: true,
      order: {
        ...order,
        items: []
      }
    })
  } catch (error) {
    console.error('Seat guests error:', error)
    return c.json({ success: false, error: 'Failed to seat guests' }, 500)
  }
})

// Confirm guests are seated (for kitchen orders/vouchers)
app.post('/api/waiter/confirm-seated', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const { voucher_id, order_id, order_type, waiter_id, waiter_name } = body
    
    console.log('[Confirm Seated] Received:', { voucher_id, order_id, order_type })
    
    if (!voucher_id && !order_id) {
      return c.json({ success: false, error: 'Missing voucher_id or order_id' }, 400)
    }
    
    const staffName = waiter_name || waiter_id || 'Waiter'
    let updateSuccess = false
    
    // Try kitchen order (alacarte_vouchers) first if voucher_id provided
    if (voucher_id) {
      console.log('[Confirm Seated] Updating kitchen order (voucher):', voucher_id)
      const voucherResult = await DB.prepare(`
        UPDATE alacarte_vouchers
        SET checked_in_at = CURRENT_TIMESTAMP,
            checked_in_by = ?,
            status = 'checked_in'
        WHERE voucher_id = ? AND property_id = ?
      `).bind(staffName, voucher_id, property_id).run()
      
      if (voucherResult.meta.changes > 0) {
        console.log('[Confirm Seated] Kitchen order updated successfully')
        updateSuccess = true
      }
    }
    
    // Try waiter order if order_id provided OR if voucher update failed
    if (!updateSuccess && (order_id || voucher_id)) {
      const waiterOrderId = order_id || voucher_id
      console.log('[Confirm Seated] Attempting waiter order update:', waiterOrderId)
      
      try {
        // NOTE: waiter_orders table may not have checked_in_at columns yet
        // Try to update if columns exist, silently fail if not
        const waiterResult = await DB.prepare(`
          UPDATE waiter_orders
          SET status = 'seated'
          WHERE order_id = ?
        `).bind(waiterOrderId).run()
        
        if (waiterResult.meta.changes > 0) {
          console.log('[Confirm Seated] Waiter order status updated to seated')
          updateSuccess = true
        }
      } catch (waiterError) {
        console.log('[Confirm Seated] Waiter order update failed (table may not have checked_in columns yet):', waiterError.message)
      }
    }
    
    if (updateSuccess) {
      return c.json({ 
        success: true,
        message: 'Guest marked as seated'
      })
    } else {
      console.log('[Confirm Seated] No orders were updated')
      return c.json({ 
        success: false, 
        error: 'Order not found or already seated' 
      }, 404)
    }
  } catch (error) {
    console.error('[Confirm Seated] Error:', error)
    return c.json({ success: false, error: 'Failed to confirm seated: ' + error.message }, 500)
  }
})

// Add items to order
app.post('/api/waiter/add-items', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const { order_id, items } = body
    
    if (!order_id || !items || items.length === 0) {
      return c.json({ success: false, error: 'Missing required fields' }, 400)
    }
    
    // Get current order
    const order = await DB.prepare(`
      SELECT * FROM waiter_orders WHERE order_id = ?
    `).bind(order_id).first()
    
    if (!order) {
      return c.json({ success: false, error: 'Order not found' }, 404)
    }
    
    let currentItems = order.items ? JSON.parse(order.items) : []
    console.log('[ADD-ITEMS] Starting with currentItems:', JSON.stringify(currentItems))
    console.log('[ADD-ITEMS] Incoming items to add:', JSON.stringify(items))
    
    // Add new items
    for (const newItem of items) {
      const itemId = String(newItem.item_id)
      console.log('[ADD-ITEMS] Processing item:', itemId, 'quantity:', newItem.quantity)
      let itemDetails = null
      
      // Check if this is an extra charge item (starts with 'rm_' or is a string)
      if (itemId.startsWith('rm_')) {
        // Extra charge item from menu_items table
        const numericId = itemId.replace('rm_', '')
        console.log('[ADD-ITEMS] Looking up rm_ item, numeric ID:', numericId)
        itemDetails = await DB.prepare(`
          SELECT item_id, item_name, price as cost
          FROM menu_items
          WHERE item_id = ?
        `).bind(numericId).first()
        
        console.log('[ADD-ITEMS] rm_ item lookup result:', JSON.stringify(itemDetails))
        
        if (itemDetails) {
          itemDetails.item_id = itemId // Keep the rm_ prefix
        }
      } else {
        // Regular set menu item from alacarte_menu_items
        console.log('[ADD-ITEMS] Looking up regular item from alacarte_menu_items, item_id:', newItem.item_id)
        itemDetails = await DB.prepare(`
          SELECT item_id, item_name, cost_to_hotel as cost
          FROM alacarte_menu_items
          WHERE item_id = ?
        `).bind(newItem.item_id).first()
        
        console.log('[ADD-ITEMS] Regular item lookup result:', JSON.stringify(itemDetails))
      }
      
      if (itemDetails) {
        console.log('[ADD-ITEMS] Item found! Adding:', JSON.stringify(itemDetails))
        const existing = currentItems.find(i => i.item_id === newItem.item_id)
        if (existing) {
          console.log('[ADD-ITEMS] Item already exists, incrementing quantity')
          existing.quantity += newItem.quantity
        } else {
          console.log('[ADD-ITEMS] New item, pushing to currentItems')
          currentItems.push({
            item_id: itemDetails.item_id,
            item_name: itemDetails.item_name,
            cost: parseFloat(itemDetails.cost) || 0,
            quantity: newItem.quantity
          })
        }
      } else {
        console.error('[ADD-ITEMS] ❌ Item NOT FOUND in database! item_id:', itemId)
      }
    }
    
    console.log('[ADD-ITEMS] Final currentItems after loop:', JSON.stringify(currentItems))
    
    // Calculate total
    const totalCost = currentItems.reduce((sum, item) => sum + (item.cost * item.quantity), 0)
    
    console.log('[ADD-ITEMS] Before update - currentItems:', JSON.stringify(currentItems))
    console.log('[ADD-ITEMS] Before update - totalCost:', totalCost)
    
    // Update order
    await DB.prepare(`
      UPDATE waiter_orders
      SET items = ?, total_cost = ?, updated_at = CURRENT_TIMESTAMP
      WHERE order_id = ?
    `).bind(JSON.stringify(currentItems), totalCost, order_id).run()
    
    console.log('[ADD-ITEMS] After update - returning currentItems length:', currentItems.length)
    
    const responseOrder = {
      order_id: order.order_id,
      table_id: order.table_id,
      restaurant_id: order.restaurant_id,
      waiter_id: order.waiter_id,
      guest_name: order.guest_name,
      room_number: order.room_number,
      party_size: order.party_size,
      items: currentItems,
      total_cost: totalCost,
      status: order.status,
      created_at: order.created_at,
      updated_at: new Date().toISOString()
    }
    
    console.log('[ADD-ITEMS] Response order items length:', responseOrder.items.length)
    
    return c.json({
      success: true,
      order: responseOrder
    })
  } catch (error) {
    console.error('Add items error:', error)
    return c.json({ success: false, error: 'Failed to add items' }, 500)
  }
})

// Update item quantity
app.post('/api/waiter/update-item', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const { order_id, item_id, quantity } = body
    
    console.log('[UPDATE-ITEM] Request:', { order_id, item_id, quantity })
    
    // Get current order
    const order = await DB.prepare(`
      SELECT * FROM waiter_orders WHERE order_id = ?
    `).bind(order_id).first()
    
    if (!order) {
      console.log('[UPDATE-ITEM] Order not found:', order_id)
      return c.json({ success: false, error: 'Order not found' }, 404)
    }
    
    let currentItems = order.items ? JSON.parse(order.items) : []
    console.log('[UPDATE-ITEM] Current items before update:', JSON.stringify(currentItems))
    
    if (quantity === 0) {
      // Remove item
      console.log('[UPDATE-ITEM] Removing item:', item_id)
      const beforeLength = currentItems.length
      currentItems = currentItems.filter(i => {
        console.log('[UPDATE-ITEM] Comparing:', i.item_id, '!==', item_id, '=', i.item_id !== item_id)
        return i.item_id !== item_id
      })
      const afterLength = currentItems.length
      console.log('[UPDATE-ITEM] Items after filter:', beforeLength, '->', afterLength)
    } else {
      // Update quantity
      const item = currentItems.find(i => i.item_id === item_id)
      if (item) {
        console.log('[UPDATE-ITEM] Updating quantity for:', item_id, 'to', quantity)
        item.quantity = quantity
      } else {
        console.log('[UPDATE-ITEM] Item not found in currentItems:', item_id)
      }
    }
    
    console.log('[UPDATE-ITEM] Current items after update:', JSON.stringify(currentItems))
    
    // Calculate total
    const totalCost = currentItems.reduce((sum, item) => sum + (item.cost * item.quantity), 0)
    console.log('[UPDATE-ITEM] New total cost:', totalCost)
    
    // Update order
    await DB.prepare(`
      UPDATE waiter_orders
      SET items = ?, total_cost = ?, updated_at = CURRENT_TIMESTAMP
      WHERE order_id = ?
    `).bind(JSON.stringify(currentItems), totalCost, order_id).run()
    
    console.log('[UPDATE-ITEM] Database updated successfully')
    
    return c.json({
      success: true,
      order: {
        ...order,
        items: currentItems,
        total_cost: totalCost
      }
    })
  } catch (error) {
    console.error('[UPDATE-ITEM] Error:', error)
    return c.json({ success: false, error: 'Failed to update item' }, 500)
  }
})

