// Checkout kitchen order (mark voucher as served/checked out)
app.post('/api/waiter/checkout-table', async (c) => {
  const { DB } = c.env
  const property_id = c.req.header('X-Property-ID') || '1'
  
  try {
    const body = await c.req.json()
    const { voucher_id } = body
    
    if (!voucher_id) {
      return c.json({ success: false, error: 'Voucher ID required' }, 400)
    }
    
    // Mark the alacarte voucher as served/completed
    await DB.prepare(`
      UPDATE alacarte_vouchers
      SET status = 'served',
          completed_at = CURRENT_TIMESTAMP
      WHERE voucher_id = ?
    `).bind(voucher_id).run()
    
    return c.json({
      success: true,
      message: 'Table checked out successfully'
    })
  } catch (error) {
    console.error('Checkout table error:', error)
    return c.json({ success: false, error: 'Failed to checkout table' }, 500)
  }
})

export default {
  fetch: app.fetch,
  async scheduled(event: any, env: any, ctx: any) {
    console.log('Running scheduled jobs...', event.cron)
    
    try {
      // Weekly analytics report (Monday 9 AM)
      if (event.cron === '0 9 * * MON') {
        console.log('📧 Sending weekly analytics reports...')
        
        // Send Beach Analytics
        try {
          const beachResponse = await fetch('https://www.oldpalaceresort.online/api/admin/send-weekly-report?type=beach', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
          })
          const beachResult = await beachResponse.json()
          console.log('✅ Beach report result:', beachResult)
        } catch (error) {
          console.error('❌ Beach report error:', error)
        }
        
        // Send Feedback Analytics
        try {
          const feedbackResponse = await fetch('https://www.oldpalaceresort.online/api/admin/send-weekly-report?type=feedback', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
          })
          const feedbackResult = await feedbackResponse.json()
          console.log('✅ Feedback report result:', feedbackResult)
        } catch (error) {
          console.error('❌ Feedback report error:', error)
        }
        
        // Send General Analytics
        try {
          const generalResponse = await fetch('https://www.oldpalaceresort.online/api/admin/send-weekly-report?type=general', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
          })
          const generalResult = await generalResponse.json()
          console.log('✅ General report result:', generalResult)
        } catch (error) {
          console.error('❌ General report error:', error)
        }
      }
      
      // Biometric data deletion job
      console.log('🗑️ Running biometric data deletion job...')
      
      // Execute the deletion logic directly
      const { DB } = env
      const now = new Date().toISOString()
      
      const passesToDelete = await DB.prepare(`
        SELECT pass_id, property_id, primary_guest_name, guest_email,
               scheduled_deletion_date, valid_until
        FROM digital_passes
        WHERE (face_embedding IS NOT NULL OR face_photo_url IS NOT NULL)
          AND biometric_consent_withdrawn = 0
          AND (
            scheduled_deletion_date <= ?
            OR valid_until < date('now', '-1 day')
          )
      `).bind(now).all()

      const deletedCount = passesToDelete.results.length

      for (const pass of passesToDelete.results) {
        await DB.prepare(`
          UPDATE digital_passes
          SET face_embedding = NULL,
              face_photo_url = NULL,
              face_enrolled_at = NULL,
              face_embedding_version = NULL,
              biometric_consent_given = 0,
              scheduled_deletion_date = NULL
          WHERE pass_id = ? AND property_id = ?
        `).bind(pass.pass_id, pass.property_id).run()

        await DB.prepare(`
          UPDATE pass_family_members
          SET face_embedding = NULL,
              face_photo_url = NULL,
              face_enrolled_at = NULL,
              face_embedding_version = NULL
          WHERE pass_id = ?
        `).bind(pass.pass_id).run()

        await DB.prepare(`
          INSERT INTO biometric_audit_log (
            pass_id, property_id, action_type, action_details,
            performed_by, ip_address, user_agent
          ) VALUES (?, ?, 'AUTO_DELETED', ?, 'automated_job', 'system', 'cloudflare-worker-cron')
        `).bind(
          pass.pass_id,
          pass.property_id,
          JSON.stringify({
            guest_name: pass.primary_guest_name,
            guest_email: pass.guest_email,
            scheduled_deletion_date: pass.scheduled_deletion_date,
            valid_until: pass.valid_until,
            deletion_reason: 'retention_period_expired',
            deletion_time: now
          })
        ).run()
      }

      console.log(`Biometric auto-deletion completed: ${deletedCount} passes processed`)
    } catch (error) {
      console.error('Scheduled biometric deletion error:', error)
    }
  }
}

